const QUESTIONS = [{"id":"c1-q1","chapter":1,"difficulty":1,"type":"single","question":"Mạng Internet xuất phát từ mạng nào của Mỹ vào năm 1969?","options":["ARPANET","WWW","NSFNET","INTERNET"],"correct":[0],"explanation":"Slide 4: Mạng Internet xuất phát từ mạng ARPANET của Mỹ (1969) – mạng kết nối giữa các trường Đại học.","source":"bo1"},{"id":"c1-q2","chapter":1,"difficulty":1,"type":"single","question":"Ai là người phát minh ra giao thức World Wide Web (WWW) và ngôn ngữ HTML vào năm 1989?","options":["Tim Berners-Lee","Vint Cerf","Steve Jobs","Bill Gates"],"correct":[0],"explanation":"Slide 4: Năm 1989, Tim Berners-Lee phát minh ra giao thức World Wide Web, sau đó tạo ra ngôn ngữ Hypertext Markup Language (HTML).","source":"bo1"},{"id":"c1-q3","chapter":1,"difficulty":2,"type":"single","question":"Trình duyệt web (Web Browser) và Web server đầu tiên (info.cern.ch) được tạo ra vào năm nào?","options":["1993","1997","1989","1990"],"correct":[3],"explanation":"Slide 4: Năm 1990, tìm viết trình duyệt (Web Browser) và Web server đầu tiên (info.cern.ch).","source":"bo1"},{"id":"c1-q4","chapter":1,"difficulty":1,"type":"single","question":"Việt Nam chính thức có Internet vào thời gian nào?","options":["Tháng 12/1997","Tháng 10/1997","Tháng 11/1997","Tháng 11/1999"],"correct":[2],"explanation":"Slide 4: Việt Nam có Internet chính thức vào tháng 11/1997.","source":"bo1"},{"id":"c1-q5","chapter":1,"difficulty":1,"type":"single","question":"Máy chủ (Server) là gì?","options":["Là máy tính chuyên cung cấp tài nguyên, dịch vụ cho máy tính khác","Là máy tính chuyên khai thác tài nguyên từ máy khác","Là thiết bị định tuyến kết nối các mạng LAN","Là phần mềm dùng để lướt web"],"correct":[0],"explanation":"Slide 8: Máy chủ là máy tính chuyên cung cấp tài nguyên, dịch vụ cho máy tính khác. Thường có cấu hình cao, hoạt động ổn định.","source":"bo1"},{"id":"c1-q6","chapter":1,"difficulty":1,"type":"single","question":"Máy khách (Client) là gì?","options":["Là máy cung cấp tài nguyên cho máy khác","Là máy chủ chứa cơ sở dữ liệu","Là hệ điều hành mạng","Là máy khai thác dịch vụ của máy chủ"],"correct":[3],"explanation":"Slide 9: Máy khách là máy khai thác dịch vụ của máy chủ.","source":"bo1"},{"id":"c1-q7","chapter":1,"difficulty":2,"type":"single","question":"Phát biểu nào sau đây là đúng về mối quan hệ giữa Máy chủ (Server) và Máy khách (Client)?","options":["Một máy chủ chỉ có thể phục vụ duy nhất một máy khách","Máy chủ không thể khai thác dịch vụ của chính nó","Một máy tính có thể vừa là client vừa là server","Máy khách bắt buộc phải có cấu hình phần cứng cao hơn máy chủ"],"correct":[2],"explanation":"Slide 9: Một máy tính có thể vừa là client vừa là server, có thể khai thác dịch vụ của chính nó.","source":"bo1"},{"id":"c1-q8","chapter":1,"difficulty":1,"type":"single","question":"Bộ giao thức mạng (Protocol) là gì?","options":["Là hệ thống các quy định chung giúp xác định quá trình truyền dữ liệu giữa các máy tính","Là tên gọi khác của địa chỉ IP","Là phần cứng kết nối các máy tính lại với nhau","Là ngôn ngữ lập trình dùng để tạo ra trang web"],"correct":[0],"explanation":"Slide 10: Bộ giao thức mạng là một hệ thống các quy định chung giúp xác định quá trình truyền dữ liệu giữa các máy tính, nhờ đó dữ liệu truyền nhận chính xác.","source":"bo1"},{"id":"c1-q9","chapter":1,"difficulty":1,"type":"single","question":"TCP/IP là viết tắt của cụm từ nào?","options":["Transmission Connect Protocol / Internet Provider","Total Control Protocol / Internet Protocol","Transmission Control Protocol / Internet Protocol","Transfer Control Protocol / Internal Protocol"],"correct":[2],"explanation":"Slide 11: TCP/IP là viết tắt của Transmission Control Protocol / Internet Protocol.","source":"bo1"},{"id":"c1-q10","chapter":1,"difficulty":1,"type":"single","question":"Giao thức FTP (File Transfer Protocol) thường được sử dụng để làm gì?","options":["Hiển thị nội dung trang web lên trình duyệt","Trao đổi thư điện tử (Email)","Bảo mật thông tin khi truy cập web","Truyền tải tập tin từ máy tính này tới máy tính khác qua mạng"],"correct":[3],"explanation":"Slide 12: FTP dùng để truyền tải tài liệu từ một máy tính này tới một máy tính khác qua mạng Internet (Upload/Download).","source":"bo1"},{"id":"c1-q11","chapter":1,"difficulty":1,"type":"single","question":"Công việc chính của giao thức HTTP là gì?","options":["Quản lý tài khoản người dùng","Chuyển nội dung một trang web vào trình duyệt để người dùng xem","Chuyển các file dữ liệu nén qua lại giữa các máy chủ","Mã hóa dữ liệu để bảo mật"],"correct":[1],"explanation":"Slide 13: HTTP (HyperText Transfer Protocol) chuyển nội dung trang web vào trình duyệt cho người dùng xem.","source":"bo1"},{"id":"c1-q12","chapter":1,"difficulty":1,"type":"single","question":"HTTPS là sự kết hợp giữa giao thức HTTP và giao thức bảo mật nào?","options":["FTP","SSL hoặc TLS","SMTP","TCP/IP"],"correct":[1],"explanation":"Slide 14: HTTPS là sự kết hợp giữa HTTP và giao thức bảo mật SSL hay TLS, thường dùng trong các giao dịch cần tính bảo mật cao.","source":"bo1"},{"id":"c1-q13","chapter":1,"difficulty":1,"type":"single","question":"Địa chỉ IPv4 là một con số có độ dài bao nhiêu bit?","options":["16-bit","128-bit","32-bit","64-bit"],"correct":[2],"explanation":"Slide 15: Địa chỉ IP (IPv4) là một con số 32-bit dùng để xác định đối tượng nhận và gửi thông tin.","source":"bo1"},{"id":"c1-q14","chapter":1,"difficulty":1,"type":"single","question":"Nói tới localhost thường ta nói tới địa chỉ IP nào?","options":["192.168.1.1","1.0.0.127","127.0.0.10","127.0.0.1"],"correct":[3],"explanation":"Slide 16: Địa chỉ 127.0.0.1 (localhost) là địa chỉ của chính máy tính đang sử dụng, thường dùng để thử mạng và thử nghiệm trang web.","source":"bo1"},{"id":"c1-q15","chapter":1,"difficulty":2,"type":"single","question":"Địa chỉ IPv6 có độ dài bao nhiêu bit và được biểu diễn dưới dạng nào?","options":["64-bit, dạng 4 nhóm số hexa","128-bit, dạng 4 nhóm số thập phân","128-bit, dạng 8 nhóm số hexa","32-bit, dạng 4 nhóm số thập phân"],"correct":[2],"explanation":"Slide 17: IPv6 dài 128 bits, biểu diễn dưới dạng 8 nhóm số hexa (có thể rút gọn các số 0).","source":"bo1"},{"id":"c1-q16","chapter":1,"difficulty":2,"type":"single","question":"Để biết được địa chỉ IP của một website (ví dụ www.uel.edu.vn), ta làm như thế nào?","options":["Mở trình duyệt và gõ lệnh ipconfig","Vào phần Settings của Windows","Mở CMD và gõ lệnh ping www.uel.edu.vn","Mở Word và nhập đường dẫn"],"correct":[2],"explanation":"Slide 16: Start -> Run -> gõ CMD -> gõ Ping www.uel.edu.vn và enter để xem địa chỉ IP.","source":"bo1"},{"id":"c1-q17","chapter":1,"difficulty":1,"type":"single","question":"Tên miền cấp 1 (TLD) `.edu` đại diện cho loại tổ chức nào?","options":["Các trường học, các tổ chức giáo dục","Công ty thương mại","Các tổ chức quốc tế","Các mạng (network)"],"correct":[0],"explanation":"Slide 20: .edu là các trường học, các tổ chức giáo dục.","source":"bo1"},{"id":"c1-q18","chapter":1,"difficulty":1,"type":"single","question":"Tên miền cấp 1 `.com` đại diện cho loại tổ chức nào?","options":["Các mạng (network)","Công ty thương mại (commercial)","Các tổ chức khác (other organizations)","Các trường học, giáo dục"],"correct":[1],"explanation":"Slide 20: .com là công ty thương mại (commercial).","source":"bo1"},{"id":"c1-q19","chapter":1,"difficulty":2,"type":"single","question":"Trong tên miền `uel.edu.vn`, phần `vn` được gọi là gì?","options":["Tên miền cấp 3","Tên miền cấp 2","Tên miền cấp 1","Tên tổ chức"],"correct":[2],"explanation":"Slide 19: Tên miền được đánh số cấp từ phải qua trái. vn: Nước Việt Nam (cấp 1), edu: Tổ chức giáo dục (cấp 2), uel: Tên cơ quan (cấp 3).","source":"bo1"},{"id":"c1-q20","chapter":1,"difficulty":2,"type":"single","question":"Cú pháp chung của một URL là gì?","options":["protocol.host_name[:port_num][/file_name]","host_name://protocol[:port_num][/path]","protocol://host_name[:port_num][/path][/file_name]","http://www.host_name.com/path"],"correct":[2],"explanation":"Slide 21: URL có cú pháp: protocol://host_name[:port_num][/path][/file_name].","source":"bo1"},{"id":"c1-q21","chapter":1,"difficulty":2,"type":"single","question":"Cổng dịch vụ (Port) mặc định dành cho giao thức Web (HTTP) là bao nhiêu?","options":["21","443","25","80"],"correct":[3],"explanation":"Slide 22: Web sử dụng cổng 80. FTP sử dụng cổng 21. (HTTPS mặc định là 443).","source":"bo1"},{"id":"c1-q22","chapter":1,"difficulty":2,"type":"single","question":"Cổng dịch vụ (Port) mặc định dành cho giao thức FTP là bao nhiêu?","options":["21","80","443","110"],"correct":[0],"explanation":"Slide 22: FTP sử dụng cổng 21.","source":"bo1"},{"id":"c1-q23","chapter":1,"difficulty":1,"type":"single","question":"WWW là viết tắt của cụm từ nào?","options":["World Why Web","Wall Wide Web","Word Wid Wed","World Wide Web"],"correct":[3],"explanation":"Slide 24: WWW là viết tắt của World Wide Web (tập hợp các web site trên mạng internet).","source":"bo1"},{"id":"c1-q24","chapter":1,"difficulty":2,"type":"single","question":"Khi một trang web được viết bằng PHP, ASP, ASPX..., kết quả cuối cùng trả về cho trình duyệt của máy khách là ngôn ngữ gì?","options":["PHP","Python","HTML (Hypertext Markup Language)","C++"],"correct":[2],"explanation":"Slide 23: Dù viết bằng ngôn ngữ nào, kết quả khi trả về máy khách (client) luôn là ngôn ngữ HTML.","source":"bo1"},{"id":"c1-q25","chapter":1,"difficulty":1,"type":"single","question":"Đâu là các phần mềm Web Server chuyên dụng được nhắc đến trong bài?","options":["FileZilla và WinSCP","Notepad và FrontPage","Apache và IIS (Internet Information Services)","Google Chrome và Firefox"],"correct":[2],"explanation":"Slide 25: Web server có Apache (mã nguồn mở) và IIS (sản phẩm của Microsoft).","source":"bo1"},{"id":"c1-q26","chapter":1,"difficulty":1,"type":"single","question":"Web Browser là gì?","options":["Phần mềm chạy trên máy chủ (server) dùng để hiển thị trang web","Là máy phục vụ web","Là giao thức truyền tải siêu văn bản","Phần mềm chạy trên máy khách (client) dùng để hiển thị trang web và khai thác dịch vụ web"],"correct":[3],"explanation":"Slide 26 (và Quiz 1): Web Browser là phần mềm chạy trên máy khách (client) dùng để hiển thị trang web và giúp khai thác dịch vụ web.","source":"bo1"},{"id":"c1-q27","chapter":1,"difficulty":2,"type":"single","question":"Đặc điểm nào sau đây là của Web tĩnh (Static Web)?","options":["Tương tác với người duyệt web yếu, không nhận thông tin phản hồi từ người dùng","Sử dụng nhiều ngôn ngữ lập trình khác nhau","Khó phát triển, phải viết nhiều mã lệnh","Tương tác với người duyệt web mạnh mẽ"],"correct":[0],"explanation":"Slide 27: Web tĩnh dễ phát triển, tương tác yếu, sử dụng HTML, không nhận thông tin phản hồi từ người dùng.","source":"bo1"},{"id":"c1-q28","chapter":1,"difficulty":2,"type":"single","question":"Đặc điểm nào sau đây là của Web động (Dynamic Web)?","options":["Dễ phát triển, chỉ dùng HTML","Không cần viết mã lệnh","Tương tác với người duyệt web mạnh và nhận thông tin phản hồi từ người dùng","Không thể tương tác với người dùng"],"correct":[2],"explanation":"Slide 28: Web động khó phát triển hơn, tương tác mạnh, dùng nhiều ngôn ngữ lập trình, nhận thông tin phản hồi.","source":"bo1"},{"id":"c1-q29","chapter":1,"difficulty":1,"type":"single","question":"Người làm web tĩnh thường sử dụng các công cụ trực quan nào để tạo ra trang web?","options":["Visual Studio Code, Eclipse","FrontPage, Notepad","MySQL, SQL Server","Apache, IIS"],"correct":[1],"explanation":"Slide 27: Người làm web tĩnh thường dùng các công cụ trực quan như FrontPage, Notepad...","source":"bo1"},{"id":"c1-q30","chapter":1,"difficulty":2,"type":"single","question":"ISP là viết tắt của cụm từ nào?","options":["Internal Service Protocol","Internet Server Provider","Internet Access Provider (Nhà cung cấp đường truyền)","Internet Service Provider (Nhà cung cấp dịch vụ Internet)"],"correct":[3],"explanation":"Slide 29: ISP là Internet Service Provider (Nhà cung cấp dịch vụ Internet). IAP là Internet Access Provider (Nhà cung cấp đường truyền).","source":"bo1"},{"id":"c2-q1","chapter":2,"difficulty":1,"type":"single","question":"Trong quy trình các bước thiết lập một website, bước ĐẦU TIÊN cần thực hiện là gì?","options":["Xác định yêu cầu của website","Mua tên miền","Thuê chỗ hosting","Thiết kế website"],"correct":[0],"explanation":"Slide 3: Các bước thiết lập Website gồm: 1. Xác định yêu cầu, 2. Mua tên miền, 3. Thuê chỗ hosting, 4. Thiết kế website, 5. Đưa vào hoạt động, 6. Duy trì bảo trì.","source":"bo1"},{"id":"c2-q2","chapter":2,"difficulty":2,"type":"single","question":"Thứ tự đúng của các bước thiết lập Website là:","options":["Xác định yêu cầu -> Mua tên miền -> Thuê hosting -> Thiết kế -> Đưa vào hoạt động -> Duy trì bảo trì","Thiết kế -> Xác định yêu cầu -> Mua tên miền -> Thuê hosting -> Đưa vào hoạt động -> Duy trì bảo trì","Thuê hosting -> Mua tên miền -> Thiết kế -> Xác định yêu cầu -> Đưa vào hoạt động -> Duy trì bảo trì","Mua tên miền -> Thuê hosting -> Xác định yêu cầu -> Thiết kế -> Đưa vào hoạt động -> Duy trì bảo trì"],"correct":[0],"explanation":"Slide 3: Quy trình chuẩn gồm 6 bước: Xác định yêu cầu, Mua tên miền, Thuê chỗ hosting, Thiết kế website, Đưa vào hoạt động, Duy trì thông tin & bảo trì.","source":"bo1"},{"id":"c2-q3","chapter":2,"difficulty":2,"type":"single","question":"Khi xác định mục tiêu của website, phát biểu nào sau đây là đúng?","options":["Mục tiêu chỉ dành cho đội ngũ kỹ thuật, không liên quan đến ban giám đốc","Mục tiêu phải dài hạn, bao trùm toàn bộ kế hoạch phát triển và là công cụ đánh giá sự thành bại của website","Mục tiêu chỉ cần ngắn gọn, không cần liên quan đến kế hoạch dài hạn","Mục tiêu phải thay đổi liên tục theo từng tháng"],"correct":[1],"explanation":"Slide 5: Mục tiêu phải khái quát, ngắn gọn, rõ ràng, dài hạn, bao trùm toàn bộ kế hoạch phát triển và là công cụ để đánh giá sự thành bại của website.","source":"bo1"},{"id":"c2-q4","chapter":2,"difficulty":2,"type":"single","question":"Một thiết kế web tốt được đánh giá là gì?","options":["Thích hợp cho tất cả các loại độc giả có trình độ và nhu cầu khác nhau","Chỉ phục vụ cho những người rành về công nghệ","Sử dụng càng nhiều hiệu ứng hình ảnh càng tốt","Chỉ cần hiển thị tốt trên một trình duyệt duy nhất"],"correct":[0],"explanation":"Slide 7: Thiết kế web tốt = thích hợp cho tất cả các loại độc giả có trình độ và nhu cầu khác nhau.","source":"bo1"},{"id":"c2-q5","chapter":2,"difficulty":2,"type":"multiple","question":"Một tên miền (Domain) tốt cần đáp ứng những tiêu chí nào sau đây? (chọn nhiều đáp án)","options":["Càng dài và nhiều ký tự đặc biệt càng tốt","Không gây nhầm lẫn","Tên ngắn, gợi nhớ, dễ đọc","Thể hiện được tên công ty hoặc nhãn hiệu"],"correct":[1,2,3],"explanation":"Slide 14: Tên miền tốt cần: Tên ngắn, gợi nhớ, dễ đọc, không gây nhầm lẫn, thể hiện được tên công ty hoặc nhãn hiệu.","source":"bo1"},{"id":"c2-q6","chapter":2,"difficulty":2,"type":"multiple","question":"Khi thuê chỗ hosting (Hosting Provider), ta cần quan tâm tới những vấn đề nào? (chọn nhiều đáp án)","options":["Hệ điều hành","Số lượng nhân viên thiết kế đồ họa của công ty","Dung lượng và băng thông","Ngôn ngữ hỗ trợ và Hệ quản trị CSDL hỗ trợ"],"correct":[0,2,3],"explanation":"Slide 18: Các yếu tố cần quan tâm khi thuê hosting: Hệ điều hành, Dung lượng, Băng thông, Ngôn ngữ hỗ trợ, Hệ quản trị CSDL hỗ trợ, Email POP3...","source":"bo1"},{"id":"c2-q7","chapter":2,"difficulty":2,"type":"single","question":"Nếu website của bạn sử dụng cơ sở dữ liệu là SQL Server thì nên mua Hosting loại nào?","options":["Linux hosting","Windows hosting","MAC hosting","Loại nào cũng được"],"correct":[1],"explanation":"Slide 20 (và Quiz 1): SQL Server là sản phẩm của Microsoft, do đó cần thuê Windows hosting để tương thích tốt nhất. (Linux hosting thường dùng cho MySQL, PHP).","source":"bo1"},{"id":"c2-q8","chapter":2,"difficulty":2,"type":"single","question":"Các bước cơ bản để phát triển một website (tương tự phân tích thiết kế hệ thống thông tin) bao gồm:","options":["Lập trình -> Thiết kế -> Đặc tả -> Phân tích -> Kiểm thử","Thiết kế -> Đặc tả -> Phân tích -> Lập trình -> Kiểm thử","Phân tích -> Đặc tả -> Kiểm thử -> Thiết kế -> Lập trình","Đặc tả -> Phân tích -> Thiết kế -> Lập trình -> Kiểm thử"],"correct":[3],"explanation":"Slide 23: Các bước phát triển website: Đặc tả, Phân tích, Thiết kế, Lập trình (xây dựng), Kiểm thử.","source":"bo1"},{"id":"c2-q9","chapter":2,"difficulty":2,"type":"multiple","question":"Trong bước 'Đặc tả' của quá trình thiết kế website, ta cần trả lời những câu hỏi nào? (chọn nhiều đáp án)","options":["Web cho ai dùng? Trình độ người dùng ra sao?","Nội dung, hình ảnh như thế nào?","Thiết kế cơ sở dữ liệu ra sao?","Web để làm gì?"],"correct":[0,1,3],"explanation":"Slide 24: Bước Đặc tả cần trả lời: Web để làm gì? Web cho ai dùng? Trình độ người dùng ra sao? Nội dung, hình ảnh như thế nào? (Thiết kế CSDL nằm ở bước Thiết kế).","source":"bo1"},{"id":"c2-q10","chapter":2,"difficulty":2,"type":"single","question":"Công việc nào sau đây thuộc bước 'Phân tích' trong quy trình thiết kế website?","options":["Viết mã HTML, CSS, JavaScript","Mua tên miền và thuê hosting","Tìm hiểu mối liên quan giữa các nội dung trang web và thứ tự của chúng","Kiểm tra website trên nhiều trình duyệt khác nhau"],"correct":[2],"explanation":"Slide 24: Phân tích bao gồm: Mối liên quan giữa các nội dung trang web, Thứ tự của các nội dung trang web.","source":"bo1"},{"id":"c2-q11","chapter":2,"difficulty":2,"type":"single","question":"Trong bước 'Kiểm thử' website, ta cần kiểm tra những yếu tố nào?","options":["Chỉ cần kiểm tra trên trình duyệt Google Chrome","Chỉ cần kiểm tra xem mã HTML có bị lỗi cú pháp không","Kiểm tra trên nhiều trình duyệt, nhiều cấu hình mạng, tốc độ, liên kết và bảo mật","Chỉ cần kiểm tra xem website có load được hay không"],"correct":[2],"explanation":"Slide 26: Kiểm thử gồm: Kiểm tra trên nhiều trình duyệt, nhiều cấu hình mạng, tốc độ, các liên kết (link), bảo mật...","source":"bo1"},{"id":"c2-q12","chapter":2,"difficulty":2,"type":"single","question":"Khi thiết kế website, khái niệm trang 'dead-end' (trang cụt) có nghĩa là gì?","options":["Là trang thông báo lỗi 404","Là trang không có khả năng đi đến các trang khác","Là trang chủ của website","Là trang quảng cáo"],"correct":[1],"explanation":"Slide 36 (và Quiz 1): Không nên có trang 'dead-end', nghĩa là trang không có khả năng đi đến các trang khác. Mỗi trang phải có ít nhất một liên kết.","source":"bo1"},{"id":"c2-q13","chapter":2,"difficulty":2,"type":"single","question":"Theo nguyên tắc thiết kế hướng đến người sử dụng, độc giả truy cập website luôn phải trả lời được 3 câu hỏi nào?","options":["Ai tạo ra trang web này? Trang web có kiếm tiền không? Trang web dùng công nghệ gì?","Mật khẩu là gì? Tên đăng nhập là gì? Email là gì?","Trang web có bao nhiêu bài viết? Có bao nhiêu người truy cập? Có bao nhiêu quảng cáo?","Đang ở đâu? Có thể làm được những gì? Có thể tiếp tục đi đâu?"],"correct":[3],"explanation":"Slide 35: Độc giả có thể trả lời được các câu hỏi: Đang ở đâu? Có thể làm được những gì? Có thể tiếp tục đi đâu?","source":"bo1"},{"id":"c2-q14","chapter":2,"difficulty":2,"type":"single","question":"Cấu trúc Website (Sitemap) có đặc điểm gì?","options":["Là một file hình ảnh quảng cáo đặt ở chân trang","Là một trang thông báo lỗi khi người dùng nhập sai đường dẫn","Là danh sách các từ khóa để website dễ tìm kiếm trên Google","Dùng để tổ chức các khối thông tin phức hợp, gần với mô hình tổ chức thực tế và cho cái nhìn tổng quan từ trang chủ"],"correct":[3],"explanation":"Slide 32: Sitemap dùng để tổ chức các khối thông tin phức hợp, là hệ thống thông dụng nhất, gần với mô hình thực tế, dễ hình dung tổ chức website, cho cái nhìn tổng quan từ trang chủ.","source":"bo1"},{"id":"c2-q15","chapter":2,"difficulty":2,"type":"single","question":"Khi thiết kế giao diện, việc chọn Font chữ (phông chữ) phụ thuộc vào những yếu tố nào?","options":["Số lượng bài viết trên trang web","Sở thích của người lập trình","Đặc điểm thông tin, độc giả, trình duyệt, độ phân giải và ngôn ngữ sử dụng","Dung lượng của ổ cứng máy chủ"],"correct":[2],"explanation":"Slide 30: Font chữ phụ thuộc vào: Đặc điểm thông tin, Độc giả, Trình duyệt/độ phân giải, Ngôn ngữ sử dụng...","source":"bo1"},{"id":"c2-q16","chapter":2,"difficulty":2,"type":"single","question":"Để đảm bảo tính thẩm mỹ trong thiết kế website, yêu cầu về gam màu là gì?","options":["Gam màu càng sặc sỡ càng thu hút","Mỗi trang phải sử dụng một gam màu hoàn toàn khác nhau","Chỉ nên dùng 2 màu đen và trắng","Gam màu nên thống nhất toàn bộ website"],"correct":[3],"explanation":"Slide 30: Gam màu nên thống nhất toàn bộ website.","source":"bo1"},{"id":"c2-q17","chapter":2,"difficulty":1,"type":"single","question":"Sau khi website được đưa vào hoạt động, công việc duy trì và bảo trì bao gồm những gì?","options":["Xóa toàn bộ dữ liệu cũ và làm lại từ đầu","Chỉ cần để đó và không cần làm gì thêm","Thông tin phải được cập nhật thường xuyên và có đội ngũ bảo trì để sửa lỗi, nâng cấp","Chuyển toàn bộ website về dạng văn bản thuần túy"],"correct":[2],"explanation":"Slide 40: Khi Website đưa vào hoạt động thì thông tin phải cập nhật thường xuyên, có dữ liệu mới. Phải có đội ngũ bảo trì website để sửa chữa lỗi, nâng cấp phiên bản.","source":"bo1"},{"id":"c3-q1","chapter":3,"difficulty":1,"type":"single","question":"HTML là viết tắt của cụm từ nào?","options":["HyperText Markup Language","HyperText Machine Language","HyperText Makeup Language","Hyper Transfer Markup Language"],"correct":[0],"explanation":"Slide 03: HTML là viết tắt của HyperText Markup Language (Ngôn ngữ đánh dấu siêu văn bản).","source":"bo1"},{"id":"c3-q2","chapter":3,"difficulty":1,"type":"single","question":"HTML được phát minh bởi ai và được W3C đưa thành chuẩn vào năm nào?","options":["Tim Berner Lee - năm 1990","Bill Gates - năm 1990","Vint Cerf - năm 1994","Tim Berner Lee - năm 1994"],"correct":[3],"explanation":"Slide 03: HTML do Tim Berner Lee phát minh và được W3C đưa thành chuẩn năm 1994.","source":"bo1"},{"id":"c3-q3","chapter":3,"difficulty":2,"type":"single","question":"Khi viết sai cú pháp HTML, trình duyệt sẽ phản ứng như thế nào?","options":["Báo lỗi đỏ trên màn hình và dừng tải trang","Hiển thị hộp thoại yêu cầu tải lại trang","Tự động sửa lỗi cú pháp cho người dùng","Không báo lỗi cú pháp, chỉ hiển thị kết quả không đúng với dự định"],"correct":[3],"explanation":"Slide 04: Các trình duyệt thường không báo lỗi cú pháp cho ngôn ngữ HTML. Nếu viết sai cú pháp chỉ dẫn đến kết quả hiển thị không đúng với dự định.","source":"bo1"},{"id":"c3-q4","chapter":3,"difficulty":1,"type":"single","question":"Trong HTML, các thẻ (tags) có phân biệt chữ hoa và chữ thường không?","options":["Có phân biệt hoàn toàn","Chỉ phân biệt đối với thẻ đóng","Không phân biệt (ví dụ: <HTML> = <html>)","Chỉ phân biệt đối với thẻ tự đóng"],"correct":[2],"explanation":"Slide 08: Các thẻ không phân biệt chữ hoa và chữ thường: <HTML> = <Html> = <html>.","source":"bo1"},{"id":"c3-q5","chapter":3,"difficulty":2,"type":"single","question":"Đối với văn bản trong mã nguồn HTML, trình duyệt sẽ xử lý các khoảng trắng thừa và dấu xuống dòng như thế nào?","options":["Gộp tất cả thành một khoảng trống duy nhất khi hiển thị","Giữ nguyên toàn bộ khoảng trắng và xuống dòng","Báo lỗi cú pháp vì có quá nhiều khoảng trắng","Tự động xóa bỏ hoàn toàn các khoảng trắng"],"correct":[0],"explanation":"Slide 08: Trình duyệt bỏ qua các khoảng trắng thừa và các dấu ngắt dòng, xuống dòng. Mọi khoảng trống được hiển thị thành 1 khoảng trống duy nhất.","source":"bo1"},{"id":"c3-q6","chapter":3,"difficulty":2,"type":"multiple","question":"Một thẻ (tag) trong HTML thường có cấu trúc gồm những thành phần nào sau đây? (chọn nhiều đáp án)","options":["Tên của thẻ","Các thành phần con nằm giữa thẻ mở và thẻ đóng","Giá trị của thuộc tính","Thuộc tính của thẻ"],"correct":[0,1,2,3],"explanation":"Slide 06: Một thẻ thường có 3 hoặc 4 phần: Tên thẻ, Thuộc tính thẻ, Giá trị thuộc tính, và thành phần con bên trong.","source":"bo1"},{"id":"c3-q7","chapter":3,"difficulty":1,"type":"single","question":"Thẻ nào sau đây KHÔNG cần có thẻ đóng (thẻ tự đóng)?","options":["<p> và </p>","<br/> và <img/>","<h1> và </h1>","<div> và </div>"],"correct":[1],"explanation":"Slide 07: Một số thẻ không cần thẻ đóng như <img />, <br />.","source":"bo1"},{"id":"c3-q8","chapter":3,"difficulty":2,"type":"single","question":"Trong HTML, để ghi chú (comment) một đoạn mã lệnh ta sử dụng cú pháp nào?","options":["/* Ghi chú ở đây */","<!-- Ghi chú ở đây -->","<comment> Ghi chú ở đây </comment>","// Ghi chú ở đây"],"correct":[1],"explanation":"Slide 09: Ghi chú trong HTML: <!-- Ghi chú -->. (Dấu /* */ và // dùng cho CSS và JS).","source":"bo1"},{"id":"c3-q9","chapter":3,"difficulty":2,"type":"single","question":"Để hiển thị dấu nhỏ hơn (<) và lớn hơn (>) trên trang web, ta sử dụng mã ký tự nào?","options":["&copy; và &reg;","&lt; và &gt;","&nbsp; và &quot;","&lt; và &quot;"],"correct":[1],"explanation":"Slide 09: Dấu nhỏ hơn (<) là &lt; và lớn hơn (>) là &gt;.","source":"bo1"},{"id":"c3-q10","chapter":3,"difficulty":2,"type":"single","question":"Để tạo nhiều khoảng trắng liên tiếp trong văn bản HTML, ta dùng mã nào?","options":["&blank;","&tab;","&nbsp;","&space;"],"correct":[2],"explanation":"Slide 09: Khoảng trống (trong trường hợp muốn có nhiều hơn 1 ký tự trống) dùng &nbsp;.","source":"bo1"},{"id":"c3-q11","chapter":3,"difficulty":1,"type":"single","question":"Thẻ heading nào có kích thước chữ lớn nhất?","options":["<h4>","<h3>","<h6>","<h1>"],"correct":[3],"explanation":"Slide 05: Kích thước của ký tự nhỏ dần từ 1 đến 6. <h1> là lớn nhất, <h6> là nhỏ nhất.","source":"bo1"},{"id":"c3-q12","chapter":3,"difficulty":1,"type":"single","question":"Thẻ <br/> có chức năng gì?","options":["Tạo dòng mới (ngắt dòng đoạn văn bản)","Tạo một đường kẻ ngang","In đậm văn bản","Tạo một đoạn văn bản mới kèm dòng trống"],"correct":[0],"explanation":"Slide 06: Thẻ <br/> dùng để tạo dòng mới, ngắt dòng đoạn văn bản.","source":"bo1"},{"id":"c3-q13","chapter":3,"difficulty":1,"type":"single","question":"Phát biểu nào sau đây đúng về sự khác biệt giữa thẻ <p> và thẻ <br/>?","options":["Cả hai thẻ đều có chức năng giống hệt nhau","<p> tạo đoạn văn bản kèm một dòng trống, <br/> chỉ tạo dòng mới","<p> không cần thẻ đóng, <br/> cần thẻ đóng","<p> chỉ tạo dòng mới, <br/> tạo đoạn văn bản có dòng trống"],"correct":[1],"explanation":"Slide 06: <p> khai báo một đoạn văn bản, tự động xuống dòng và chèn một dòng trống. <br/> chỉ tạo dòng mới (ngắt dòng).","source":"bo1"},{"id":"c3-q14","chapter":3,"difficulty":1,"type":"single","question":"Thẻ <hr/> dùng để làm gì?","options":["Ngắt dòng văn bản","Tạo một tiêu đề phụ","Tạo một vùng văn bản","Hiển thị một đường kẻ ngang"],"correct":[3],"explanation":"Slide 06: Thẻ <hr/> hiển thị đường kẻ ngang.","source":"bo1"},{"id":"c3-q15","chapter":3,"difficulty":2,"type":"single","question":"Sự khác biệt cơ bản giữa thẻ <div> và thẻ <span> là gì?","options":["<div> chiếm bằng đúng nội dung, <span> chiếm trọn một dòng","<div> mặc định chiếm trọn một dòng, <span> chiếm bằng đúng nội dung và nằm trên cùng dòng","Cả hai đều chiếm trọn một dòng","Cả hai đều nằm trên cùng dòng"],"correct":[1],"explanation":"Slide 07: <div> khai báo vùng văn bản chiếm trọn một dòng riêng biệt. <span> chiếm bằng đúng nội dung mà nó chứa và nằm trên cùng một dòng.","source":"bo1"},{"id":"c3-q16","chapter":3,"difficulty":2,"type":"single","question":"Để định dạng một đoạn văn bản vừa In đậm, vừa In nghiêng, vừa Gạch chân, ta viết mã HTML như thế nào?","options":["<u><i><b>Văn bản</u></i></b>","<b><u><i>Văn bản</b></u></i>","<b><i><u>Văn bản</b></i></u>","<b><i><u>Văn bản</u></i></b>"],"correct":[3],"explanation":"Slide 08: Các thẻ cần được lồng (nest) đúng cách. Thẻ mở nào mở trước thì thẻ đóng đó phải đóng sau cùng: <b><i><u>...</u></i></b>.","source":"bo1"},{"id":"c3-q17","chapter":3,"difficulty":1,"type":"single","question":"Thẻ <sub> và <sup> lần lượt dùng để định dạng loại chữ nào?","options":["Chữ dưới dòng (Subscript) và chữ trên dòng (Superscript)","Chữ in đậm và chữ in nghiêng","Chữ trên dòng và chữ dưới dòng","Chữ gạch chân và chữ gạch ngang"],"correct":[0],"explanation":"Slide 09: <sub> là Subscript (chữ dưới dòng, ví dụ H2O), <sup> là Superscript (chữ trên dòng, ví dụ X2).","source":"bo1"},{"id":"c3-q18","chapter":3,"difficulty":2,"type":"single","question":"Để viết công thức hóa học N₂O₄ trong HTML, ta sử dụng mã lệnh nào?","options":["N<sub>2</sub>O<sup>4</sup>","N<sup>2</sup>O<sup>4</sup>","N<sup>2</sup>O<sub>4</sub>","N<sub>2</sub>O<sub>4</sub>"],"correct":[3],"explanation":"Slide 09: Ký tự dưới dòng (số 2 và 4) phải dùng thẻ <sub>.","source":"bo1"},{"id":"c3-q19","chapter":3,"difficulty":2,"type":"single","question":"Trong thẻ <font>, thuộc tính nào dùng để thiết lập kiểu chữ (font chữ)?","options":["type","name","style","face"],"correct":[3],"explanation":"Slide 08: Thẻ <font> có 3 thuộc tính chính: face (kiểu chữ), size (kích thước), color (màu sắc).","source":"bo1"},{"id":"c3-q20","chapter":3,"difficulty":1,"type":"single","question":"Trong trường hợp hình ảnh không thể hiển thị, thuộc tính nào của thẻ <img> thường được dùng để hiển thị văn bản thay thế?","options":["src","title","placeholder","alt"],"correct":[3],"explanation":"Slide 10: Thuộc tính alt (alternative text) quy định chuỗi ký tự thay thế cho ảnh khi ảnh không hiển thị. Thuộc tính title dùng để hiện tooltip khi rê chuột.","source":"bo1"},{"id":"c3-q21","chapter":3,"difficulty":2,"type":"single","question":"Làm thế nào để thiết lập hình nền cho toàn bộ trang web?","options":["Sử dụng thuộc tính background trong thẻ <html>","Sử dụng thuộc tính bg trong thẻ <head>","Sử dụng thuộc tính background trong thẻ <body>","Sử dụng thuộc tính src trong thẻ <div>"],"correct":[2],"explanation":"Slide 10: Thiết lập hình nền cho thẻ body: <body background=\"hinh1.png\">.","source":"bo1"},{"id":"c3-q22","chapter":3,"difficulty":1,"type":"single","question":"Trong hệ màu Hexa, tổ hợp RRGGBB đại diện cho những màu nào?","options":["RR: Red, GG: Green, BB: Blue","RR: Red, GG: Gray, BB: Brown","RR: Red, GG: Grey, BB: Black","RR: Red, GG: Green, BB: Brown"],"correct":[0],"explanation":"Slide 11: RR (red), GG (Green), BB (Blue).","source":"bo1"},{"id":"c3-q23","chapter":3,"difficulty":2,"type":"single","question":"Mã Hexa color nào đại diện cho màu trắng và màu đen?","options":["#FFFFFF (trắng), #000000 (đen)","#FFFFFF (trắng), #111111 (đen)","#CCCCCC (trắng), #000000 (đen)","#000000 (trắng), #FFFFFF (đen)"],"correct":[0],"explanation":"Slide 11: Giá trị thấp nhất 000000 là màu đen, giá trị cao nhất FFFFFF là màu trắng.","source":"bo1"},{"id":"c3-q24","chapter":3,"difficulty":2,"type":"single","question":"Mã thập lục phân #FF00FF tương đương với mã RGB nào sau đây?","options":["rgb(0,255,0)","rgb(255,255,0)","rgb(0,0,255)","rgb(255,0,255)"],"correct":[3],"explanation":"Slide 11: FF (255) - 00 (0) - FF (255). Vậy là rgb(255,0,255).","source":"bo1"},{"id":"c3-q25","chapter":3,"difficulty":1,"type":"single","question":"Thẻ <ol> dùng để tạo loại danh sách nào?","options":["Danh sách có đánh số thứ tự","Danh sách dạng bảng","Danh sách phân cấp có diễn giải","Danh sách không có số thứ tự (dạng nút)"],"correct":[0],"explanation":"Slide 12: <ol> (Ordered list) dùng để trình bày danh sách đánh số thứ tự. <ul> dùng cho danh sách dạng nút.","source":"bo1"},{"id":"c3-q26","chapter":3,"difficulty":2,"type":"single","question":"Để tạo danh sách không có số thứ tự với các nút hình vuông, ta dùng mã nào?","options":["<ul type=\"circle\">","<ul type=\"disc\">","<ol type=\"square\">","<ul type=\"square\">"],"correct":[3],"explanation":"Slide 12: <ul> có các type: square (hình vuông đầy), circle (hình tròn rỗng), disc (hình tròn đầy - mặc định).","source":"bo1"},{"id":"c3-q27","chapter":3,"difficulty":2,"type":"single","question":"Trong thẻ <ol>, thuộc tính type=\"I\" sẽ hiển thị dạng đánh số như thế nào?","options":["Chữ cái thường: a, b, c...","Chữ số La Mã: I, II, III...","Chữ số thường: 1, 2, 3...","Chữ cái in hoa: A, B, C..."],"correct":[1],"explanation":"Slide 12: type=\"I\" dùng chữ số La Mã (I, II, III). type=\"A\" dùng chữ in hoa, type=\"a\" dùng chữ thường, type=\"1\" dùng số.","source":"bo1"},{"id":"c3-q28","chapter":3,"difficulty":2,"type":"single","question":"Thẻ <dl> dùng để tạo loại danh sách nào?","options":["Danh sách phân cấp có diễn giải","Danh sách dạng bảng","Danh sách không có số thứ tự","Danh sách có số thứ tự"],"correct":[0],"explanation":"Slide 13: Thẻ <dl> (Definition List) tạo danh sách đề mục có diễn giải. Trong đó <dt> là từ khóa, <dd> là diễn giải.","source":"bo1"},{"id":"c3-q29","chapter":3,"difficulty":1,"type":"single","question":"Trong danh sách <dl>, thẻ nào dùng để chứa phần diễn giải cho từ khóa?","options":["<dl>","<dt>","<dd>","<li>"],"correct":[2],"explanation":"Slide 13: <dt> là từ khoá (Definition Term), <dd> là diễn giải (Definition Description).","source":"bo1"},{"id":"c3-q30","chapter":3,"difficulty":1,"type":"single","question":"Thuộc tính href trong thẻ <a> có ý nghĩa gì?","options":["Hiển thị tiêu đề khi rê chuột","Quy định cửa sổ mở trang","Quy định tên của liên kết","Quy định đích liên kết (địa chỉ trang sẽ mở)"],"correct":[3],"explanation":"Slide 14: href=\"đích liên kết\" quy định địa chỉ nội dung sẽ hiện ra. title hiển thị tooltip khi rê chuột. target quy định cửa sổ đích.","source":"bo1"},{"id":"c3-q31","chapter":3,"difficulty":2,"type":"single","question":"Khi muốn mở một liên kết trong một cửa sổ mới (tab mới), ta sử dụng thuộc tính target với giá trị nào?","options":["_self","_blank","_new","_top"],"correct":[1],"explanation":"Slide 14: target=\"_blank\" mở cửa sổ mới, target=\"_self\" mở ở cửa sổ hiện tại (mặc định).","source":"bo1"},{"id":"c3-q32","chapter":3,"difficulty":2,"type":"single","question":"Để tạo một liên kết gửi email, mã lệnh nào sau đây là đúng?","options":["<a href=\"https://thanhtd@uel.edu.vn\">Gửi email</a>","<a href=\"mailto:thanhtd@uel.edu.vn\">Gửi email</a>","<a href=\"email:thanhtd@uel.edu.vn\">Gửi email</a>","<a src=\"mailto:thanhtd@uel.edu.vn\">Gửi email</a>"],"correct":[1],"explanation":"Slide 15: Liên kết đến địa chỉ Email sử dụng cú pháp mailto: <a href=\"mailto:email@domain.com\">.","source":"bo1"},{"id":"c3-q33","chapter":3,"difficulty":2,"type":"single","question":"Kỹ thuật bookmark - hyper link trong cùng một trang hiện hành được thực hiện bằng cách nào trong HTML5?","options":["Đặt title cho thẻ cần liên kết đến và dùng href=\"title\" để trỏ tới","Đặt class cho thẻ cần liên kết đến và dùng href=\".class\" để trỏ tới","Đặt name cho thẻ cần liên kết đến và dùng href=\"name\" để trỏ tới","Đặt id cho thẻ cần liên kết đến và dùng href=\"#id\" để trỏ tới"],"correct":[3],"explanation":"Slide 15: HTML5 không còn thuộc tính name trong thẻ a, sử dụng id. Ví dụ: <h1 id=\"tieude\"> và <a href=\"#tieude\">.","source":"bo1"},{"id":"c3-q34","chapter":3,"difficulty":2,"type":"single","question":"Để liên kết đến một phần nội dung nằm trong một trang KHÁC (ví dụ trang `gioithieu.html`), ta viết mã như thế nào?","options":["<a src=\"gioithieu.html#id_phan_do\">Xem phần giới thiệu</a>","<a href=\"#id_phan_do\">Xem phần giới thiệu</a>","<a href=\"gioithieu.html#id_phan_do\">Xem phần giới thiệu</a>","<a href=\"gioithieu.html\">Xem phần giới thiệu</a>"],"correct":[2],"explanation":"Slide 15: Liên kết chéo trang cần ghi rõ tên file html và id của phần đó: `gioithieu.html#id_phan_do`.","source":"bo1"},{"id":"c3-q35","chapter":3,"difficulty":2,"type":"single","question":"Cho đoạn mã sau: `<a href=\"https://uel.edu.vn\" target=\"_blank\">UEL</a>`. Khi nhấn vào chữ UEL, điều gì sẽ xảy ra?","options":["Trình duyệt tải file uel.edu.vn xuống máy tính","Trình duyệt tải lại trang hiện tại","Trình duyệt mở trang web uel.edu.vn ngay tại tab hiện tại","Trình duyệt mở trang web uel.edu.vn trong một tab/cửa sổ mới"],"correct":[3],"explanation":"Slide 14: target=\"_blank\" có tác dụng mở liên kết trong cửa sổ mới.","source":"bo1"},{"id":"c3-q36","chapter":3,"difficulty":1,"type":"single","question":"Để xem trước tài liệu HTML và tự động cập nhật khi thay đổi code trong Visual Studio Code, ta sử dụng extension nào?","options":["Live Server","HTML CSS Support","Auto Rename Tag","Prettier"],"correct":[0],"explanation":"Slide 03: Cài đặt plug-in Live Server để chạy và tự động cập nhật tài liệu HTML.","source":"bo1"},{"id":"c3-q37","chapter":3,"difficulty":2,"type":"single","question":"Trong cấu trúc cơ bản của một tài liệu HTML, thẻ nào chứa tiêu đề của trang (hiển thị trên thanh tab trình duyệt)?","options":["<h1>","<title>","<head>","<header>"],"correct":[1],"explanation":"Slide 04: Thẻ <title> nằm trong <head>, dùng để đặt tiêu đề cho tài liệu (hiển thị trên tab trình duyệt). Thẻ <h1> là tiêu đề hiển thị trên nội dung trang (nằm trong <body>).","source":"bo1"},{"id":"c3-q38","chapter":3,"difficulty":2,"type":"multiple","question":"Cho đoạn mã HTML sau: `<img src=\"h1.png\" width=\"300\" height=\"500\" alt=\"Không có hình\" title=\"Đây là hình\"/>`. Những thuộc tính nào sau đây được sử dụng trong thẻ img này? (chọn nhiều đáp án)","options":["width","src","height","align"],"correct":[0,1,2],"explanation":"Slide 10: Đoạn mã trên chứa các thuộc tính src, width, height, alt, title. Không có thuộc tính align.","source":"bo1"},{"id":"c3-q39","chapter":3,"difficulty":2,"type":"single","question":"Đoạn mã HTML sau hiển thị kết quả như thế nào? `<b>UEL</b> <i>UEL</i> <u>UEL</u>`","options":["UEL (đậm), UEL (gạch chân), UEL (nghiêng)","Lỗi cú pháp vì thiếu thẻ đóng","UEL (đậm), UEL (nghiêng), UEL (gạch chân)","Cả 3 chữ UEL đều in đậm và gạch chân"],"correct":[2],"explanation":"Slide 08: <b> là in đậm, <i> là in nghiêng, <u> là gạch chân.","source":"bo1"},{"id":"c3-q40","chapter":3,"difficulty":2,"type":"single","question":"Tại sao ta nên sử dụng mã màu Hexa (ví dụ #FF0000) thay vì tên màu (ví dụ red)?","options":["Vì trình duyệt không hỗ trợ tên màu","Vì mã Hexa cung cấp hàng triệu màu sắc khác nhau, trong khi tên màu chỉ có số lượng giới hạn","Vì mã Hexa giúp trang web bảo mật hơn","Vì mã Hexa chạy nhanh hơn tên màu"],"correct":[1],"explanation":"Slide 11: Tên màu có định nghĩa sẵn nhưng số lượng rất hạn chế. Mã Hexa cho phép lựa chọn chính xác bất kỳ màu nào (hàng triệu màu).","source":"bo1"},{"id":"c4-q1","chapter":4,"difficulty":1,"type":"single","question":"Thẻ nào được sử dụng để tạo một bảng (Table) trong HTML?","options":["<tb>","<tab>","<table>","<tbl>"],"correct":[2],"explanation":"Slide 16: Để tạo một bảng ta dùng tag <table>...</table>.","source":"bo1"},{"id":"c4-q2","chapter":4,"difficulty":1,"type":"single","question":"Trong bảng HTML, thẻ <tr> dùng để làm gì?","options":["Tạo một cột cho bảng","Tạo ô tiêu đề","Tạo một dòng cho bảng","Tạo ô dữ liệu"],"correct":[2],"explanation":"Slide 16: Thẻ <tr> (Table Row) dùng để tạo dòng cho bảng. Bảng có bao nhiêu dòng thì có bấy nhiêu cặp thẻ <tr>.","source":"bo1"},{"id":"c4-q3","chapter":4,"difficulty":1,"type":"single","question":"Sự khác biệt giữa thẻ <td> và <th> trong bảng là gì?","options":["Cả hai thẻ có chức năng hoàn toàn giống nhau","<td> tạo ô dữ liệu, <th> tạo ô tiêu đề (thường in đậm và căn giữa)","<td> tạo ô tiêu đề, <th> tạo ô dữ liệu","<td> tạo dòng, <th> tạo cột"],"correct":[1],"explanation":"Slide 16: <th> là ô tiêu đề của bảng (Table Header), <td> là ô dữ liệu (Table Data).","source":"bo1"},{"id":"c4-q4","chapter":4,"difficulty":2,"type":"single","question":"Để tạo một ô trống (không có dữ liệu) trong bảng HTML, ta cần làm gì?","options":["Thêm thuộc tính empty=\"true\" vào thẻ <td>","Sử dụng thẻ <empty>","Đặt nội dung ô là &nbsp;","Để trống thẻ <td></td>"],"correct":[2],"explanation":"Slide 16: Để có được một ô trống trong bảng thì cần đặt nội dung ô là &nbsp;.","source":"bo1"},{"id":"c4-q5","chapter":4,"difficulty":2,"type":"single","question":"Thuộc tính nào của thẻ <table> dùng để kẻ đường viền cho bảng?","options":["outline","frame","border","line"],"correct":[2],"explanation":"Slide 16: Thuộc tính border=\"số\": kích thước đường viền. Đặt bằng 0 (mặc định): không có đường viền.","source":"bo1"},{"id":"c4-q6","chapter":4,"difficulty":2,"type":"single","question":"Thuộc tính cellpadding trong thẻ <table> có tác dụng gì?","options":["Quy định khoảng cách giữa 2 ô liên tiếp","Quy định màu nền của bảng","Quy định khoảng cách từ góc ô đến nội dung ô","Quy định độ rộng của bảng"],"correct":[2],"explanation":"Slide 16: cellpadding là khoảng cách từ góc ô đến nội dung ô. cellspacing là khoảng cách giữa 2 ô liên tiếp.","source":"bo1"},{"id":"c4-q7","chapter":4,"difficulty":2,"type":"single","question":"Thuộc tính cellspacing trong thẻ <table> có tác dụng gì?","options":["Quy định khoảng cách từ góc ô đến nội dung ô","Quy định tiêu đề của bảng","Quy định số cột của bảng","Quy định khoảng cách giữa 2 ô liên tiếp"],"correct":[3],"explanation":"Slide 16: cellspacing là khoảng cách giữa 2 ô liên tiếp.","source":"bo1"},{"id":"c4-q8","chapter":4,"difficulty":2,"type":"single","question":"Để trộn 2 cột trong một dòng của bảng, ta sử dụng thuộc tính nào?","options":["cellspan","colmerge","colspan","rowspan"],"correct":[2],"explanation":"Slide 18: colspan=\"n\" dùng để trộn cột (mặc định = 1). rowspan=\"n\" dùng để trộn dòng.","source":"bo1"},{"id":"c4-q9","chapter":4,"difficulty":2,"type":"single","question":"Để trộn 3 dòng trong cùng một cột của bảng, ta sử dụng thuộc tính nào và gán giá trị bao nhiêu?","options":["colspan=\"2\"","colspan=\"3\"","rowspan=\"3\"","rowspan=\"2\""],"correct":[2],"explanation":"Slide 18: rowspan=\"n\" dùng để trộn dòng, giá trị n là số dòng cần trộn. Vậy trộn 3 dòng là rowspan=\"3\".","source":"bo1"},{"id":"c4-q10","chapter":4,"difficulty":3,"type":"single","question":"Trong thẻ <td> hoặc <th>, thuộc tính valign dùng để làm gì?","options":["Trộn cột","Căn lề theo chiều ngang (left, right, center)","Căn lề theo chiều dọc (top, middle, bottom)","Trộn dòng"],"correct":[2],"explanation":"Slide 16: align dùng căn lề ngang (left, right, center, justify). valign dùng căn lề đứng (top, middle, bottom).","source":"bo1"},{"id":"c4-q11","chapter":4,"difficulty":2,"type":"single","question":"Thuộc tính nowrap trong thẻ <td> có tác dụng gì?","options":["Ẩn nội dung của ô","Làm cho dữ liệu trong ô không tự xuống dòng","Trộn các dòng lại với nhau","Tự động xuống dòng khi hết ô"],"correct":[1],"explanation":"Slide 16: nowrap: nếu có sẽ làm cho dữ liệu trong ô không tự xuống dòng.","source":"bo1"},{"id":"c4-q12","chapter":4,"difficulty":1,"type":"single","question":"Thẻ nào dùng để định nghĩa tiêu đề (caption) cho bảng?","options":["<caption>","<title>","<header>","<thead>"],"correct":[0],"explanation":"Slide 17: <caption> định nghĩa tiêu đề cho bảng, thường nằm ngay sau thẻ <table> mở.","source":"bo1"},{"id":"c4-q13","chapter":4,"difficulty":2,"type":"single","question":"Cấu trúc đầy đủ của một thẻ <table> chuẩn bao gồm những thành phần nào?","options":["<caption>, <thead>, <tbody>, <tfoot>","<colgroup>, <col>, <tr>","<header>, <main>, <footer>","<head>, <body>, <foot>"],"correct":[0],"explanation":"Slide 17: Cấu trúc đầy đủ gồm <caption> (tiêu đề), <thead> (phần đầu), <tbody> (phần thân), <tfoot> (phần chân bảng).","source":"bo1"},{"id":"c4-q14","chapter":4,"difficulty":2,"type":"single","question":"Thẻ <colgroup> trong bảng HTML dùng để làm gì?","options":["Định dạng cột hàng loạt một cách nhanh chóng (ví dụ: đổi màu nền cho cả cột)","Nhóm các dòng lại với nhau","Trộn các cột lại với nhau","Tạo tiêu đề cho bảng"],"correct":[0],"explanation":"Slide 19: <colgroup> dùng để định dạng cột hàng loạt (như màu nền, độ rộng) giúp tiết kiệm thời gian.","source":"bo1"},{"id":"c4-q15","chapter":4,"difficulty":3,"type":"multiple","question":"Trong đoạn mã HTML sau: `<table border=\"1\"><thead style=\"background-color:yellow;\"><tr><th rowspan=\"2\">STT</th><th colspan=\"2\">Điểm</th></tr></thead></table>`. Những phát biểu nào sau đây là ĐÚNG? (chọn nhiều đáp án)","options":["Tiêu đề bảng có nền màu vàng","Ô STT sẽ chiếm 2 cột","Ô STT sẽ chiếm 2 dòng","Ô Điểm sẽ chiếm 2 cột"],"correct":[0,2,3],"explanation":"Slide 18: rowspan=\"2\" ở ô STT giúp nó chiếm 2 dòng. colspan=\"2\" ở ô Điểm giúp nó chiếm 2 cột. Thead có style màu vàng.","source":"bo1"},{"id":"c4-q16","chapter":4,"difficulty":1,"type":"single","question":"Thẻ <iframe> trong HTML dùng để làm gì?","options":["Chèn video từ file mp4","Lắp ghép (nhúng) một tài liệu HTML này vào trong một tài liệu HTML khác","Tạo một khung viền cho hình ảnh","Tạo một bảng biểu"],"correct":[1],"explanation":"Slide 20: Thẻ <iframe> dùng để lắp ghép nhiều tài liệu HTML vào trong một tài liệu HTML gốc.","source":"bo1"},{"id":"c4-q17","chapter":4,"difficulty":2,"type":"single","question":"Thuộc tính nào của thẻ <iframe> dùng để trỏ tới đường dẫn của tài liệu HTML cần nhúng?","options":["url","src","href","link"],"correct":[1],"explanation":"Slide 20: Thuộc tính src (source) dùng để trỏ tới tài liệu HTML cần hiển thị trong iframe.","source":"bo1"},{"id":"c4-q18","chapter":4,"difficulty":2,"type":"single","question":"Thẻ <frameset> có chức năng gì?","options":["Tạo một khung hình ảnh","Phân chia cửa sổ trình duyệt thành nhiều khung (frame) chứa các trang HTML khác nhau","Tạo một bảng dữ liệu","Nhúng video"],"correct":[1],"explanation":"Slide 21: Thẻ <frameset> dùng để phân chia và lắp ghép giao diện tài liệu HTML thành nhiều khung.","source":"bo1"},{"id":"c4-q19","chapter":4,"difficulty":3,"type":"single","question":"Để phân chia màn hình thành 2 cột: cột trái chiếm 30% và cột phải chiếm 70%, ta sử dụng thuộc tính nào trong thẻ <frameset>?","options":["<frameset width=\"30%,70%\">","<frameset split=\"30%,70%\">","<frameset rows=\"30%,70%\">","<frameset cols=\"30%,70%\">"],"correct":[3],"explanation":"Slide 21: Thuộc tính cols dùng để chia cột (dọc), rows dùng để chia dòng (ngang).","source":"bo1"},{"id":"c4-q20","chapter":4,"difficulty":3,"type":"single","question":"Khi sử dụng <frameset>, làm thế nào để khi nhấp vào một liên kết, trang web sẽ hiển thị ở một khung cụ thể (ví dụ khung tên là \"mainframe\")?","options":["Sử dụng thuộc tính name=\"mainframe\" trong thẻ <a>","Sử dụng thuộc tính href=\"mainframe\" trong thẻ <a>","Sử dụng thuộc tính src=\"mainframe\" trong thẻ <a>","Sử dụng thuộc tính target=\"mainframe\" trong thẻ <a>"],"correct":[3],"explanation":"Slide 21: Khung cần hiển thị (frame) phải có name=\"mainframe\". Thẻ <a> liên kết phải có target=\"mainframe\".","source":"bo1"},{"id":"c4-q21","chapter":4,"difficulty":2,"type":"single","question":"Trong tài liệu HTML sử dụng <frameset>, thẻ <body> có được phép sử dụng không?","options":["Chỉ dùng thẻ <body> ở frame con","Không, thẻ <body> sẽ bị thay thế bởi <frameset>","Bắt buộc phải có <body> bên trong <frameset>","Có, luôn phải có thẻ <body>"],"correct":[1],"explanation":"Slide 21: Khi dùng <frameset>, cấu trúc HTML là <html><head>...</head><frameset>...</frameset></html>, không có thẻ <body>.","source":"bo1"},{"id":"c4-q22","chapter":4,"difficulty":1,"type":"single","question":"Thẻ <marquee> có tác dụng gì?","options":["Tạo một bảng biểu","Làm cho đối tượng (chữ, hình ảnh) di chuyển trên trang web","Tạo một khung viền cho văn bản","Nhúng video"],"correct":[1],"explanation":"Slide 22: Thẻ <marquee> sẽ làm chạy hầu hết các đối tượng trong thẻ như chữ, hình ảnh, các định dạng khác.","source":"bo1"},{"id":"c4-q23","chapter":4,"difficulty":2,"type":"single","question":"Theo mặc định (không có thuộc tính direction), đối tượng trong thẻ <marquee> sẽ di chuyển theo hướng nào?","options":["Từ phải sang trái","Từ dưới lên trên","Từ trên xuống dưới","Từ trái sang phải"],"correct":[0],"explanation":"Slide 22: Mặc định các đối tượng sẽ chạy từ phải sang trái (tương đương direction=\"left\").","source":"bo1"},{"id":"c4-q24","chapter":4,"difficulty":2,"type":"single","question":"Thuộc tính behavior=\"alternate\" trong thẻ <marquee> có nghĩa là gì?","options":["Dừng lại ngay lập tức","Chạy bình thường liên tục","Chạy 1 lần rồi dừng","Chạy qua rồi chạy lại (qua lại)"],"correct":[3],"explanation":"Slide 22: behavior (kiểu chạy) gồm: slide (chạy 1 lần rồi dừng), scroll (chạy bình thường), alternate (chạy qua rồi chạy lại).","source":"bo1"},{"id":"c4-q25","chapter":4,"difficulty":2,"type":"single","question":"Để đối tượng trong thẻ <marquee> di chuyển lặp vô tận, ta đặt thuộc tính loop bằng bao nhiêu?","options":["loop=\"0\"","loop=\"infinite\"","loop=\"1\"","loop=\"-1\""],"correct":[3],"explanation":"Slide 22: Lặp 1 lần: loop = 1. Lặp liên tục (vô tận): loop = -1.","source":"bo1"},{"id":"c4-q26","chapter":4,"difficulty":2,"type":"single","question":"Thuộc tính nào của thẻ <marquee> dùng để điều chỉnh tốc độ di chuyển của đối tượng?","options":["timer","scrollamount","speed","velocity"],"correct":[1],"explanation":"Slide 22: Thuộc tính scrollamount giúp tăng hay giảm tốc độ chạy (nhận giá trị số nguyên).","source":"bo1"},{"id":"c4-q27","chapter":4,"difficulty":1,"type":"single","question":"Thẻ nào được sử dụng để chèn âm thanh vào trang web trong HTML5?","options":["<music>","<mp3>","<audio>","<sound>"],"correct":[2],"explanation":"Slide 23: Thẻ <audio> (HTML5) dùng để chèn nhạc vào trang web.","source":"bo1"},{"id":"c4-q28","chapter":4,"difficulty":2,"type":"single","question":"Để hiển thị thanh điều khiển (play, pause, volume...) cho thẻ <audio> và <video>, ta sử dụng thuộc tính nào?","options":["buttons","controls","play","toolbar"],"correct":[1],"explanation":"Slide 23: Thuộc tính controls (ví dụ: <audio controls>) hiển thị thanh điều khiển phát media.","source":"bo1"},{"id":"c4-q29","chapter":4,"difficulty":2,"type":"single","question":"Trong thẻ <video> hoặc <audio>, thẻ nào được sử dụng để chỉ định đường dẫn của file media?","options":["<file>","<link>","<src>","<source>"],"correct":[3],"explanation":"Slide 23: Thuộc tính src thường được đặt trong thẻ <source> để chỉ định file media, cho phép khai báo nhiều định dạng khác nhau.","source":"bo1"},{"id":"c4-q30","chapter":4,"difficulty":2,"type":"single","question":"Để nhúng một video từ Youtube vào trang web HTML, ta thường sử dụng cách nào sau đây?","options":["Sử dụng mã iframe do Youtube cung cấp khi chọn \"Nhúng\" (Embed)","Sử dụng thẻ <youtube>","Sử dụng thẻ <embed> với tên video","Sử dụng thẻ <video> với đường dẫn tới video đó"],"correct":[0],"explanation":"Slide 23: Để chèn video từ Youtube, ta bấm Share -> Embed và copy đoạn mã <iframe> đó dán vào HTML.","source":"bo1"},{"id":"c4-q31","chapter":4,"difficulty":3,"type":"single","question":"Cho bảng gồm 3 cột và 2 dòng. Để ô ở dòng 1 trộn cả 3 cột lại với nhau, ta viết mã như thế nào?","options":["<td rowspan=\"2\">Nội dung</td>","<td colspan=\"2\">Nội dung</td>","<td colspan=\"3\">Nội dung</td>","<td rowspan=\"3\">Nội dung</td>"],"correct":[2],"explanation":"Slide 18: Trộn 3 cột sử dụng colspan=\"3\".","source":"bo1"},{"id":"c4-q32","chapter":4,"difficulty":3,"type":"single","question":"Trong Table, nếu ta muốn kẻ viền và tạo khoảng cách giữa các ô là 0, khoảng cách từ viền đến nội dung là 5px, ta viết thẻ <table> như thế nào?","options":["<table border=\"0\" cellspacing=\"5\" cellpadding=\"5\">","<table border=\"1\" cellpadding=\"0\" cellspacing=\"5\">","<table border=\"1\" cellspacing=\"0\" cellpadding=\"5\">","<table border=\"1\" spacing=\"0\" padding=\"5\">"],"correct":[2],"explanation":"Slide 16: cellspacing là khoảng cách giữa 2 ô, cellpadding là khoảng cách từ góc ô đến nội dung.","source":"bo1"},{"id":"c4-q33","chapter":4,"difficulty":3,"type":"single","question":"Cho đoạn mã: `<frameset rows=\"20%,80%\"><frame src=\"menu.html\"><frame src=\"content.html\" name=\"main\"></frameset>`. Màn hình sẽ được chia như thế nào?","options":["Chia làm 2 cột bằng nhau","Chia làm 2 hàng: hàng trên chiếm 20% (menu), hàng dưới chiếm 80% (content)","Chia làm 2 cột: cột trái 20% (menu), cột phải 80% (content)","Chia làm 2 hàng: hàng trên 80%, hàng dưới 20%"],"correct":[1],"explanation":"Slide 21: Thuộc tính rows chia giao diện theo hàng ngang (từ trên xuống). Thứ tự 20%, 80% tương ứng trên, dưới.","source":"bo1"},{"id":"c4-q34","chapter":4,"difficulty":3,"type":"single","question":"Trong đoạn mã `<marquee direction=\"up\" behavior=\"scroll\" loop=\"1\">Hello</marquee>`, chữ \"Hello\" sẽ chạy như thế nào?","options":["Chạy từ dưới lên trên, kiểu cuộn, lặp lại 1 lần","Chạy từ phải sang trái, kiểu cuộn, lặp vô tận","Chạy từ dưới lên trên, kiểu trượt, lặp 1 lần","Chạy từ trên xuống dưới, kiểu trượt, lặp vô tận"],"correct":[0],"explanation":"Slide 22: direction=\"up\" là chạy từ dưới lên, behavior=\"scroll\" là cuộn, loop=\"1\" là lặp 1 lần.","source":"bo1"},{"id":"c4-q35","chapter":4,"difficulty":3,"type":"single","question":"Trong thẻ <video>, nếu trình duyệt không hỗ trợ định dạng video, ta nên hiển thị thông báo thay thế bằng cách nào?","options":["Sử dụng thẻ <caption>","Đặt nội dung văn bản thông báo ngay bên trong cặp thẻ <video>...</video>","Không thể hiển thị thông báo thay thế","Sử dụng thuộc tính alt=\"Thông báo\""],"correct":[1],"explanation":"Slide 23: Ví dụ trên slide có ghi: `<video>... Your browser does not support the video tag. </video>`. Nội dung text nằm giữa thẻ mở và đóng sẽ được hiển thị nếu trình duyệt không hỗ trợ.","source":"bo1"},{"id":"c5-q1","chapter":5,"difficulty":1,"type":"single","question":"CSS là viết tắt của cụm từ nào? (What does CSS stand for?)","options":["Creative Style Sheets","Cascading Style Sheets","Colorful Style Sheets","Computer Style Sheets"],"correct":[1],"explanation":"Slide 24: CSS là viết tắt của Cascading Style Sheets.","source":"bo1"},{"id":"c5-q2","chapter":5,"difficulty":2,"type":"single","question":"DHTML (Dynamic HyperText Markup Language) là sự kết hợp của những thành phần nào?","options":["HTML, CSS và Database","HTML, CSS và Scripts","CSS và JavaScript","HTML và XML"],"correct":[1],"explanation":"Slide 24: DHTML là sự kết hợp của HTML (nội dung), CSS (giao diện) và Scripts (xử lý tương tác).","source":"bo1"},{"id":"c5-q3","chapter":5,"difficulty":2,"type":"multiple","question":"Những ưu điểm nào sau đây là của CSS? (chọn nhiều đáp án)","options":["Kiểm soát bố cục trang, kỹ thuật thiết kế phông và dạng chữ tốt hơn","Dễ duy trì hoạt động của site hơn","Thông tin kiểu được tách ra khỏi cấu trúc site","Hỗ trợ đồng đều trên tất cả các trình duyệt cũ"],"correct":[0,1,2],"explanation":"Slide 24: Ưu điểm của CSS: Kiểm soát bố cục tốt hơn, dễ duy trì, tách biệt style và cấu trúc. Nhược điểm là phụ thuộc trình duyệt, không hỗ trợ rộng rãi.","source":"bo1"},{"id":"c5-q4","chapter":5,"difficulty":2,"type":"single","question":"Cú pháp chuẩn của một đoạn mã CSS là gì?","options":["selector {property = value}","selector {property: value}","selector (property: value)","selector [property: value]"],"correct":[1],"explanation":"Slide 24: Cú pháp CSS gồm 3 phần: selector {property: value}.","source":"bo1"},{"id":"c5-q5","chapter":5,"difficulty":2,"type":"single","question":"Which of the following is the correct CSS syntax?","options":["body {color: black;}","{body:color=black;}","{body;color:black;}","body:color=black;"],"correct":[0],"explanation":"Slide 24: Cú pháp đúng là selector {property: value}. Các dấu chấm phẩy dùng để ngăn cách các thuộc tính.","source":"bo1"},{"id":"c5-q6","chapter":5,"difficulty":2,"type":"single","question":"Trong CSS, đơn vị nào sau đây là đơn vị nhỏ nhất (Pixel)?","options":["pc","pt","in","px"],"correct":[3],"explanation":"Slide 24: Các giá trị độ lớn gồm px (pixel - đơn vị nhỏ nhất), pc (pica), in (inch), mm, cm, %.","source":"bo1"},{"id":"c5-q7","chapter":5,"difficulty":2,"type":"single","question":"Which CSS property is used to change the text color of an element?","options":["text-color","color","font-color","foreground-color"],"correct":[1],"explanation":"Slide 24: Thuộc tính color dùng để đổi màu chữ. Thuộc tính font-family đổi font chữ.","source":"bo1"},{"id":"c5-q8","chapter":5,"difficulty":3,"type":"single","question":"Thứ tự ưu tiên của các loại Style (từ cao xuống thấp) là gì?","options":["Inline Styles > Internal Style Sheet > External Style Sheet > Browser Default Styles","External Style Sheet > Internal Style Sheet > Inline Styles > Browser Default Styles","Browser Default Styles > Inline Styles > Internal Style Sheet > External Style Sheet","Internal Style Sheet > Inline Styles > External Style Sheet > Browser Default Styles"],"correct":[0],"explanation":"Slide 24: Thứ tự ưu tiên giảm dần: Inline > Internal > External > Browser Default.","source":"bo1"},{"id":"c5-q9","chapter":5,"difficulty":1,"type":"single","question":"Which HTML attribute is used to define inline styles?","options":["font","style","styles","class"],"correct":[1],"explanation":"Slide 25: Inline Style được định nghĩa trong thuộc tính style của từng tag HTML.","source":"bo1"},{"id":"c5-q10","chapter":5,"difficulty":1,"type":"single","question":"Đoạn mã HTML sau sử dụng loại CSS nào? `<p style=\"color: red; margin-left: 20px;\">Hello</p>`","options":["Browser Default Style","Inline Style Sheet","Internal Style Sheet","External Style Sheet"],"correct":[1],"explanation":"Slide 25: Định dạng nằm trực tiếp trong thuộc tính style của thẻ <p> nên đây là Inline CSS.","source":"bo1"},{"id":"c5-q11","chapter":5,"difficulty":1,"type":"single","question":"Internal Style Sheet được khai báo ở đâu trong tài liệu HTML?","options":["Bên trong thẻ <style> nằm trong phần <head>","Trong một file .css riêng biệt","Trong thuộc tính style của thẻ HTML","Bên trong thẻ <body>"],"correct":[0],"explanation":"Slide 26: Internal Style Sheet được nhúng trong tag <style> (đặt trong <head>).","source":"bo1"},{"id":"c5-q12","chapter":5,"difficulty":2,"type":"single","question":"How do you insert a comment in a CSS file?","options":["// this is a comment","<!-- this is a comment -->","// this is a comment //","/* this is a comment */"],"correct":[3],"explanation":"Slide 26: Comment trong CSS giống C++, Java: /* Nội dung comment */.","source":"bo1"},{"id":"c5-q13","chapter":5,"difficulty":2,"type":"single","question":"Trong Internal Style Sheet, để định dạng cho một class có tên là 'left', ta viết selector như thế nào?","options":["#left","class.left",".left","left"],"correct":[2],"explanation":"Slide 26: Class trong CSS được bắt đầu bằng dấu chấm (VD: p.left {text-align:left}).","source":"bo1"},{"id":"c5-q14","chapter":5,"difficulty":2,"type":"single","question":"Đoạn mã sau sử dụng loại CSS nào?\n<head>\n  <style type=\"text/css\"> p { color:blue; } </style>\n</head>","options":["Internal Style Sheet","Inline Style Sheet","External Style Sheet","Browser Default Style"],"correct":[0],"explanation":"Slide 26: Định dạng nằm trong thẻ <style> ở phần <head> nên là Internal CSS.","source":"bo1"},{"id":"c5-q15","chapter":5,"difficulty":2,"type":"single","question":"External Style Sheet được lưu trữ dưới dạng tập tin có phần mở rộng là gì?","options":[".css",".html",".js",".style"],"correct":[0],"explanation":"Slide 27: Mọi style đều lưu trong file có phần mở rộng là *.css.","source":"bo1"},{"id":"c5-q16","chapter":5,"difficulty":2,"type":"single","question":"Which is the correct way to link an external stylesheet named 'style.css' to an HTML file?","options":["<style src=\"style.css\">","<link src=\"style.css\">","<link rel=\"stylesheet\" href=\"style.css\">","<script src=\"style.css\">"],"correct":[2],"explanation":"Slide 27: Liên kết External Style bằng tag link: <link rel=\"stylesheet\" href=\"URL\" type=\"text/css\">.","source":"bo1"},{"id":"c5-q17","chapter":5,"difficulty":2,"type":"single","question":"Ngoài thẻ <link>, ta có thể triệu gọi External Style Sheet bằng cách nào khác trong thẻ <style>?","options":["Sử dụng @include URL;","Sử dụng @external URL;","Sử dụng @import url(URL);","Sử dụng @link URL;"],"correct":[2],"explanation":"Slide 27: Liên kết bằng tag style dùng @import url(URL); (VD: @import url(ex1.css);).","source":"bo1"},{"id":"c5-q18","chapter":5,"difficulty":3,"type":"single","question":"Nhược điểm lớn nhất của External Style Sheet là gì?","options":["Phải khai báo lại thông tin style cho các tài liệu khác trong mỗi lần sử dụng","Không được trình duyệt cache lại","Không thể tái sử dụng cho nhiều trang web khác nhau","Tốn thời gian download file *.css và làm chậm quá trình biên dịch web ở trình duyệt trong lần đầu sử dụng"],"correct":[3],"explanation":"Slide 27: Nhược điểm của External Style là tốn thời gian download file .css ở lần đầu (tuy nhiên các lần sau được trình duyệt cache lại).","source":"bo1"},{"id":"c5-q19","chapter":5,"difficulty":2,"type":"single","question":"Để nhóm các selector có chung một định dạng (ví dụ h1, h2, hr cùng màu xanh), ta viết mã như thế nào?","options":["h1, h2, hr { color: green; }","h1 & h2 & hr { color: green; }","h1.h2.hr { color: green; }","h1 + h2 + hr { color: green; }"],"correct":[0],"explanation":"Slide 28: Gom nhóm nhiều thẻ: Selector1, selector2, selector3 { property: value; }.","source":"bo1"},{"id":"c5-q20","chapter":5,"difficulty":3,"type":"single","question":"Khi kết hợp Internal Style và External Style, nếu chúng cùng định dạng 1 thuộc tính nhưng khác giá trị, trình duyệt sẽ ưu tiên sử dụng style nào?","options":["Trình duyệt tự động chọn ngẫu nhiên","Cả hai đều bị bỏ qua","External Style Sheet","Internal Style Sheet"],"correct":[3],"explanation":"Slide 24 & 28: Theo thứ tự ưu tiên, Internal Style Sheet (nằm trong head) có độ ưu tiên cao hơn External Style Sheet. Nếu cùng áp dụng cho 1 thẻ, Internal sẽ thắng.","source":"bo1"},{"id":"c5-q21","chapter":5,"difficulty":2,"type":"single","question":"Cho đoạn mã CSS sau: `h1 { color: red; }`. Đâu là tên của thuộc tính (property)?","options":["text-color","h1","red","color"],"correct":[3],"explanation":"Slide 24: Cú pháp `selector {property: value}`. Ở đây `h1` là selector, `color` là property, `red` là value.","source":"bo1"},{"id":"c5-q22","chapter":5,"difficulty":3,"type":"multiple","question":"Những phát biểu nào sau đây về Inline CSS là ĐÚNG? (chọn nhiều đáp án)","options":["Dễ dàng quản lý style cho toàn bộ trang web","Được định nghĩa trong thuộc tính style của từng tag","Khó cập nhật style","Có độ ưu tiên cao nhất trong các loại CSS"],"correct":[0,1,3],"explanation":"Slide 25 & 27: Inline CSS định nghĩa trong thẻ, có độ ưu tiên cao nhất. Nhược điểm là khó cập nhật và phải khai báo lại cho từng tài liệu.","source":"bo1"},{"id":"c5-q23","chapter":5,"difficulty":2,"type":"single","question":"Which CSS property controls the text size?","options":["font-size","text-style","font-style","text-size"],"correct":[0],"explanation":"Slide 24: Thuộc tính font-size quy định kích thước chữ. font-style dùng để in nghiêng (italic).","source":"bo1"},{"id":"c5-q24","chapter":5,"difficulty":2,"type":"single","question":"Đoạn mã `<h1 style=\"color:blue;\">Xin chào</h1>` là ví dụ của loại CSS nào?","options":["Internal CSS","Inline CSS","CSS Selector","External CSS"],"correct":[1],"explanation":"Slide 25: Thuộc tính style nằm trực tiếp trong thẻ HTML nên là Inline CSS.","source":"bo1"},{"id":"c5-q25","chapter":5,"difficulty":2,"type":"single","question":"Cho đoạn mã: `<link rel=\"stylesheet\" href=\"ex2.css\">`. Đoạn mã này dùng để làm gì?","options":["Liên kết một file External CSS tên là ex2.css","Tạo một liên kết đến trang web ex2.css","Nhúng file Javascript ex2.css","Import file ảnh ex2.css"],"correct":[0],"explanation":"Slide 27: Đây là cú pháp chuẩn để gọi file External CSS.","source":"bo1"},{"id":"c5-q26","chapter":5,"difficulty":3,"type":"single","question":"Sự khác biệt lớn nhất giữa Internal CSS và External CSS là gì?","options":["Internal CSS dùng dấu #, External CSS dùng dấu .","Internal CSS dùng trong <body>, External CSS dùng trong <head>","Internal CSS không cần thẻ <style>, External CSS cần thẻ <style>","Internal CSS viết trong thẻ <style> ở <head>, External CSS viết trong một file .css riêng biệt"],"correct":[3],"explanation":"Slide 26 & 27: Internal CSS nhúng trực tiếp vào file HTML qua thẻ <style>, External CSS tách riêng ra file .css.","source":"bo1"},{"id":"c5-q27","chapter":5,"difficulty":2,"type":"single","question":"Đơn vị 'pt' trong CSS là viết tắt của gì?","options":["Pica","Percent","Point (1/72 inch)","Pixel"],"correct":[2],"explanation":"Slide 24: pt là Point, một đơn vị đo lường trong CSS (in là inch, pc là pica, px là pixel, % là phần trăm).","source":"bo1"},{"id":"c5-q28","chapter":5,"difficulty":2,"type":"single","question":"Nếu ta có 3 thẻ `<h1>`, `<h2>`, `<h3>` cùng muốn định dạng màu chữ là đỏ, ta nên làm gì để tối ưu mã CSS?","options":["h1 {color: red;} h2 {color: red;} h3 {color: red;}","h1, h2, h3 {color: red;}",".h1.h2.h3 {color: red;}","h1+h2+h3 {color: red;}"],"correct":[1],"explanation":"Slide 28: Nhóm nhiều selector có cùng thuộc tính giúp mã CSS ngắn gọn: Selector1, selector2, selector3 { property: value; }.","source":"bo1"},{"id":"c5-q29","chapter":5,"difficulty":3,"type":"single","question":"Kỹ thuật `@import url(ex1.css);` phải được đặt ở đâu để hoạt động đúng?","options":["Trong thuộc tính style của một thẻ","Cuối file HTML sau thẻ </html>","Trực tiếp trong thẻ <body>","Bên trong thẻ <style> (thường ở <head>)"],"correct":[3],"explanation":"Slide 27: Cú pháp @import được đặt bên trong cặp thẻ <style type=\"text/css\"> ... </style>.","source":"bo1"},{"id":"c5-q30","chapter":5,"difficulty":3,"type":"single","question":"Which of the following is NOT a valid reason to use External CSS?","options":["Nó có thể thiết lập Style cho nhiều tài liệu Web cùng lúc","Nó giúp việc cập nhật style cho từng thẻ trở nên dễ dàng hơn","Thông tin các Style được trình duyệt cache lại","Nó giúp tách biệt nội dung và giao diện"],"correct":[1],"explanation":"Slide 27: Việc cập nhật style cho TỪNG THẺ (tag cụ thể) dễ dàng hơn là đặc điểm của Inline CSS. External CSS giúp cập nhật toàn bộ trang web hoặc nhiều trang cùng lúc.","source":"bo1"},{"id":"c6-q1","chapter":6,"difficulty":1,"type":"single","question":"How do you select an element with id 'demo' in CSS?","options":["demo",".demo","#demo","*demo"],"correct":[2],"explanation":"Slide 29: ID selector được ký hiệu bằng dấu thăng (#). Class selector dùng dấu chấm (.).","source":"bo1"},{"id":"c6-q2","chapter":6,"difficulty":1,"type":"single","question":"Để khai báo CSS cho một class có tên là 'highlight', ta sử dụng cú pháp nào?","options":["*highlight { ... }",".highlight { ... }","#highlight { ... }","highlight { ... }"],"correct":[1],"explanation":"Slide 29: Class selector được khai báo bắt đầu bằng dấu chấm (.).","source":"bo1"},{"id":"c6-q3","chapter":6,"difficulty":2,"type":"single","question":"Làm thế nào để áp dụng nhiều class cho cùng một thẻ HTML?","options":["<p class=\"class1, class2\">","<p class=\"class1 class2\">","<p class=\"class1; class2\">","<p class=\"class1+class2\">"],"correct":[1],"explanation":"Slide 29: Các class được ngăn cách bởi khoảng trắng. VD: <dl class=\"center bold\">.","source":"bo1"},{"id":"c6-q4","chapter":6,"difficulty":2,"type":"single","question":"Sự khác biệt cốt lõi giữa ID và Class trong CSS là gì?","options":["ID dùng dấu chấm, Class dùng dấu thăng","ID là duy nhất (chỉ dùng 1 lần cho 1 thẻ), Class có thể tái sử dụng cho nhiều thẻ","Class là duy nhất, ID có thể tái sử dụng","ID không thể định dạng bằng CSS"],"correct":[1],"explanation":"Slide 29: ID (định danh) mang tính duy nhất, Class dùng để nhóm nhiều thẻ có chung định dạng.","source":"bo1"},{"id":"c6-q5","chapter":6,"difficulty":2,"type":"single","question":"Trong CSS, `a:hover` có tác dụng gì?","options":["Áp dụng định dạng khi nhấn giữ chuột vào liên kết","Áp dụng định dạng cho liên kết chưa từng được nhấn","Áp dụng định dạng cho liên kết đã nhấn chuột","Áp dụng định dạng khi di chuyển chuột vào liên kết"],"correct":[3],"explanation":"Slide 30: a:hover là trạng thái di chuyển chuột vào link. a:visited là link đã nhấn, a:active là link đang nhấn giữ.","source":"bo1"},{"id":"c6-q6","chapter":6,"difficulty":2,"type":"single","question":"Trong CSS, để tự động tô màu nền cho các dòng CHẴN của bảng (tbody), ta dùng selector nào?","options":["tbody tr:nth-child(2n+1)","tbody tr:even","tbody tr:nth-child(2n)","tbody tr:odd"],"correct":[2],"explanation":"Slide 30: nth-child(2n) dùng cho dòng chẵn (even), nth-child(2n+1) dùng cho dòng lẻ (odd).","source":"bo1"},{"id":"c6-q7","chapter":6,"difficulty":2,"type":"single","question":"Which CSS property is used to change the mouse cursor to a pointing hand (ngón trỏ) when hovering over an element?","options":["cursor: pointer;","pointer: cursor;","mouse: pointer;","cursor: hand;"],"correct":[0],"explanation":"Slide 30: Thuộc tính cursor với giá trị pointer sẽ hiển thị biểu tượng bàn tay chỉ ngón trỏ.","source":"bo1"},{"id":"c6-q8","chapter":6,"difficulty":2,"type":"single","question":"Sự khác biệt giữa `div p` và `div > p` là gì?","options":["`div p` chọn tất cả thẻ p nằm trong div (mọi cấp), `div > p` chỉ chọn thẻ p là con trực tiếp của div","`div > p` chọn tất cả thẻ p nằm trong div, `div p` chỉ chọn con trực tiếp","Cả hai đều chọn giống hệt nhau","`div p` chỉ chọn con trực tiếp, `div > p` chọn mọi cấp"],"correct":[0],"explanation":"Slide 31: Dấu cách ( ) là Descendent Selector (chọn mọi cấp con). Dấu lớn hơn (>) là Child Selector (chỉ chọn cấp 1, con trực tiếp).","source":"bo1"},{"id":"c6-q9","chapter":6,"difficulty":1,"type":"single","question":"Ký hiệu nào đại diện cho Child Selector?","options":["+","~","Dấu cách (khoảng trắng)",">"],"correct":[3],"explanation":"Slide 31: parent > child { ... } là Child Selector.","source":"bo1"},{"id":"c6-q10","chapter":6,"difficulty":1,"type":"single","question":"Which CSS property controls the text size?","options":["text-style","text-size","font-style","font-size"],"correct":[3],"explanation":"Slide 32: Thuộc tính font-size dùng để thiết lập kích thước chữ.","source":"bo1"},{"id":"c6-q11","chapter":6,"difficulty":2,"type":"single","question":"Thuộc tính nào dùng để in đậm văn bản?","options":["text-weight: bold;","font-style: bold;","font-variant: bold;","font-weight: bold;"],"correct":[3],"explanation":"Slide 32: font-weight dùng để thiết lập độ đậm nhạt (normal, bold, bolder...).","source":"bo1"},{"id":"c6-q12","chapter":6,"difficulty":2,"type":"single","question":"Trong CSS, `background-repeat: no-repeat;` có tác dụng gì?","options":["Hình nền lặp lại vô tận","Hình nền chỉ hiển thị 1 lần, không lặp lại","Hình nền lặp lại theo chiều ngang","Hình nền lặp lại theo chiều dọc"],"correct":[1],"explanation":"Slide 32: background-repeat có các giá trị: repeat (mặc định), repeat-x, repeat-y, no-repeat (không lặp).","source":"bo1"},{"id":"c6-q13","chapter":6,"difficulty":2,"type":"single","question":"Which CSS property is used to hide an element but still leaves a space where it would have been?","options":["visibility: none;","display: hidden;","visibility: hidden;","display: none;"],"correct":[2],"explanation":"Slide 32: visibility: hidden làm ẩn phần tử nhưng vẫn chiếm không gian. display: none làm ẩn hoàn toàn và không chiếm không gian.","source":"bo1"},{"id":"c6-q14","chapter":6,"difficulty":2,"type":"multiple","question":"Những giá trị nào sau đây là hợp lệ cho thuộc tính `border-style`? (chọn nhiều đáp án)","options":["dashed","double","dotted","solid"],"correct":[0,1,2,3],"explanation":"Slide 32: border-style có các giá trị phổ biến: solid, dashed, dotted, double, groove, ridge, inset, outset.","source":"bo1"},{"id":"c6-q15","chapter":6,"difficulty":2,"type":"single","question":"Mô hình Box trong CSS bao gồm những thành phần nào (từ trong ra ngoài)?","options":["Padding -> Content -> Margin -> Border","Content -> Padding -> Border -> Margin","Margin -> Border -> Padding -> Content","Content -> Border -> Padding -> Margin"],"correct":[1],"explanation":"Slide 33: Thứ tự từ trong ra ngoài là Content, Padding (đệm), Border (viền), Margin (lề).","source":"bo1"},{"id":"c6-q16","chapter":6,"difficulty":3,"type":"single","question":"Cho đoạn CSS sau: `width: 250px; margin: 10px; padding: 20px; border: 5px solid #000;`. Tổng chiều rộng (Total width) của element này là bao nhiêu?","options":["300px","310px","320px","250px"],"correct":[2],"explanation":"Slide 33: Total width = width + (padding-left + padding-right) + (border-left + border-right) + (margin-left + margin-right) = 250 + (20*2) + (5*2) + (10*2) = 250 + 40 + 10 + 20 = 320px.","source":"bo1"},{"id":"c6-q17","chapter":6,"difficulty":2,"type":"single","question":"Khi viết `margin: 10px 20px;` thì giá trị margin-top và margin-right lần lượt là bao nhiêu?","options":["20px và 10px","20px và 20px","10px và 10px","10px và 20px"],"correct":[3],"explanation":"Slide 33: Với 2 giá trị: giá trị 1 áp dụng cho top & bottom, giá trị 2 áp dụng cho left & right. Vậy top=10px, right=20px.","source":"bo1"},{"id":"c6-q18","chapter":6,"difficulty":3,"type":"single","question":"Khi viết `padding: 5px 10px 15px 20px;` thì padding-bottom là bao nhiêu?","options":["10px","5px","15px","20px"],"correct":[2],"explanation":"Slide 33: Với 4 giá trị, thứ tự là: top - right - bottom - left. Vậy bottom = 15px.","source":"bo1"},{"id":"c6-q19","chapter":6,"difficulty":2,"type":"single","question":"Thuộc tính Margin trong CSS dùng để làm gì?","options":["Tạo khoảng trống bên ngoài đường viền (border) của element","Tạo khoảng trống giữa nội dung và đường viền của element","Quy định kích thước đường viền","Quy định kích thước nội dung"],"correct":[0],"explanation":"Slide 33: Margin là lề bên ngoài border. Padding là khoảng đệm bên trong, giữa content và border.","source":"bo1"},{"id":"c6-q20","chapter":6,"difficulty":3,"type":"single","question":"Phân biệt `padding` và `margin` trong Box Model?","options":["Padding là khoảng đệm bên trong (content đến border), Margin là lề bên ngoài (từ border trở ra)","Padding là lề bên ngoài, Margin là khoảng đệm bên trong","Cả hai đều là khoảng cách bên ngoài","Cả hai đều là khoảng cách bên trong"],"correct":[0],"explanation":"Slide 33: Padding nằm giữa Content và Border. Margin nằm ngoài Border.","source":"bo1"},{"id":"c6-q21","chapter":6,"difficulty":2,"type":"single","question":"Thuộc tính `display: inline;` sẽ làm cho element hiển thị như thế nào?","options":["Hiển thị dạng danh sách","Nằm cùng hàng với các element khác, chỉ chiếm bằng đúng nội dung của nó","Chiếm trọn một hàng riêng biệt","Ẩn hoàn toàn khỏi trang"],"correct":[1],"explanation":"Slide 33: Inline element (như span, a) chỉ chiếm 1 vùng trong hàng. Block element (như div, h1) chiếm trọn 1 hàng.","source":"bo1"},{"id":"c6-q22","chapter":6,"difficulty":2,"type":"single","question":"Thuộc tính `position: fixed;` có đặc điểm gì?","options":["Định vị cố định element trên màn hình, không bị di chuyển khi cuộn trang","Định vị tương đối so với vị trí ban đầu","Định vị theo parent gần nhất","Định vị mặc định theo luồng văn bản"],"correct":[0],"explanation":"Slide 33: fixed định vị cố định (như thanh menu luôn nằm trên cùng khi scroll).","source":"bo1"},{"id":"c6-q23","chapter":6,"difficulty":1,"type":"single","question":"Để mở công cụ cấu hình Snippet Template trong Visual Studio Code, ta dùng tổ hợp phím nào?","options":["Ctrl + Space","Ctrl + Shift + P","Alt + Shift + P","Ctrl + Shift + N"],"correct":[1],"explanation":"Slide 34: Ctrl + Shift + P để mở Command Palette, sau đó tìm 'snippet' -> 'Configure User Snippets'.","source":"bo1"},{"id":"c6-q24","chapter":6,"difficulty":2,"type":"single","question":"Khi tạo Snippet Template trong VS Code, định dạng file được sử dụng là gì?","options":["XML","HTML","YAML","JSON"],"correct":[3],"explanation":"Slide 34: VS Code sử dụng định dạng JSON để định nghĩa các Snippet Template.","source":"bo1"},{"id":"c6-q25","chapter":6,"difficulty":3,"type":"single","question":"Cho đoạn CSS sau: `p { text-align: center; color: red; }`. Thuộc tính nào sẽ được áp dụng cho thẻ p?","options":["Văn bản căn giữa và có màu xanh","Văn bản căn trái và có màu đỏ","Văn bản căn giữa và có màu đỏ","Văn bản in đậm và màu đỏ"],"correct":[2],"explanation":"Slide 32: text-align: center (căn giữa), color: red (màu đỏ).","source":"bo1"},{"id":"c6-q26","chapter":6,"difficulty":2,"type":"single","question":"Which CSS property sets the background color of an element?","options":["color","background-color","bgcolor","background-style"],"correct":[1],"explanation":"Slide 32: Thuộc tính background-color dùng để đổi màu nền.","source":"bo1"},{"id":"c6-q27","chapter":6,"difficulty":2,"type":"single","question":"Muốn thay đổi kiểu chữ (font chữ) cho một element, ta sử dụng thuộc tính nào?","options":["font-family","font-weight","text-family","font-style"],"correct":[0],"explanation":"Slide 32: font-family dùng để khai báo danh sách font chữ. font-style là in nghiêng, font-weight là in đậm.","source":"bo1"},{"id":"c6-q28","chapter":6,"difficulty":3,"type":"single","question":"Trong CSS, `a:visited` đại diện cho trạng thái nào của liên kết?","options":["Liên kết đã từng được nhấn chuột vào","Liên kết đang được nhấn giữ chuột","Liên kết chưa từng được nhấn","Liên kết đang có chuột di chuyển vào"],"correct":[0],"explanation":"Slide 30: link (chưa nhấn), visited (đã nhấn), hover (rê chuột), active (đang nhấn giữ).","source":"bo1"},{"id":"c6-q29","chapter":6,"difficulty":3,"type":"single","question":"Đoạn mã nào sau đây sẽ chọn thẻ `<p class=\"intro\">` nằm BÊN TRONG thẻ `<div>`?","options":["div ~ p.intro","div + p.intro","div p.intro","div > p.intro"],"correct":[2],"explanation":"Slide 31: Để chọn p có class intro nằm trong div (mọi cấp), dùng Descendant Selector: `div p.intro` hoặc `div .intro`.","source":"bo1"},{"id":"c6-q30","chapter":6,"difficulty":3,"type":"single","question":"Cho đoạn mã CSS sau: `.box { width: 100px; padding: 10px; border: 1px solid black; margin: 5px; }`. Tổng chiều cao (Total height) của box là bao nhiêu? (Giả sử chiều cao content tự động co giãn bằng 0)","options":["132px","120px","Không thể tính được vì thiếu thuộc tính height","100px"],"correct":[2],"explanation":"Slide 33: Box Model yêu cầu phải biết chiều cao content (height) mới tính được tổng chiều cao. Nếu không khai báo height, chiều cao sẽ phụ thuộc vào nội dung bên trong.","source":"bo1"},{"id":"c6-q31","chapter":6,"difficulty":2,"type":"single","question":"Để ẩn hoàn toàn một element và không chiếm không gian trên trang, ta dùng thuộc tính nào?","options":["display: hidden;","display: none;","visibility: hidden;","opacity: 0;"],"correct":[1],"explanation":"Slide 32: display: none ẩn hoàn toàn và xóa bỏ không gian. visibility: hidden ẩn nhưng vẫn giữ không gian.","source":"bo1"},{"id":"c6-q32","chapter":6,"difficulty":1,"type":"single","question":"Thuộc tính `float: right;` có tác dụng gì?","options":["Ẩn element","Đẩy element sang bên trái","Căn giữa element","Đẩy element sang bên phải, các element khác sẽ bao quanh bên trái"],"correct":[3],"explanation":"Slide 33: float dùng để đẩy element sang trái hoặc phải, các element text hoặc inline khác sẽ nằm bên cạnh.","source":"bo1"},{"id":"c6-q33","chapter":6,"difficulty":2,"type":"single","question":"Which CSS property is used to specify the indentation of the first line of a text?","options":["text-indent","padding-left","text-align","margin-left"],"correct":[0],"explanation":"Kiến thức bổ sung: text-indent dùng để thụt đầu dòng cho đoạn văn bản.","source":"bo1"},{"id":"c6-q34","chapter":6,"difficulty":3,"type":"single","question":"Cho HTML sau: `<div><p>Hello</p><span>World</span></div>`. Selector `div > *` sẽ chọn những element nào?","options":["Không chọn thẻ nào","Chỉ thẻ <span>","Chỉ thẻ <p>","Cả thẻ <p> và <span>"],"correct":[3],"explanation":"Slide 31: Dấu `*` đại diện cho tất cả các element. `div > *` chọn tất cả các element con trực tiếp của div (ở đây là p và span).","source":"bo1"},{"id":"c6-q35","chapter":6,"difficulty":2,"type":"single","question":"Thuộc tính `border: 2px dashed red;` tương đương với việc khai báo những thuộc tính nào?","options":["border-size: 2px; border-type: dashed; border-color: red;","border-width: 2px; border-line: dashed; border-color: red;","border-width: 2px; border-style: dashed; border-color: red;","border: 2px; style: dashed; color: red;"],"correct":[2],"explanation":"Slide 32: Border là thuộc tính viết tắt (shorthand) cho border-width, border-style và border-color.","source":"bo1"},{"id":"c7-q1","chapter":7,"difficulty":1,"type":"single","question":"Thẻ nào được sử dụng để tạo một Form (biểu mẫu) trong HTML?","options":["<textarea>","<input>","<fieldset>","<form>"],"correct":[3],"explanation":"Slide 35: Thẻ <form> là nơi chứa các thành phần nhập liệu. Các thẻ như <input> hay <textarea> là các control nằm bên trong Form.","source":"bo1"},{"id":"c7-q2","chapter":7,"difficulty":2,"type":"single","question":"Thuộc tính `action` trong thẻ `<form>` có tác dụng gì?","options":["Đặt tên cho Form để dễ quản lý","Xác định phương thức gửi dữ liệu (GET, POST...)","Xác định cửa sổ hiển thị kết quả","Chỉ định trang web (hoặc server) sẽ nhận và xử lý dữ liệu từ Form"],"correct":[3],"explanation":"Slide 35: action chỉ định trang web sẽ nhận xử lý dữ liệu từ FORM này khi có sự kiện click của button SUBMIT.","source":"bo1"},{"id":"c7-q3","chapter":7,"difficulty":2,"type":"single","question":"Phương thức (method) nào sau đây truyền dữ liệu công khai lên thanh địa chỉ URL và bị giới hạn bởi độ dài của URL?","options":["GET","POST","DELETE","PUT"],"correct":[0],"explanation":"Slide 35: GET truyền dữ liệu kèm theo URL, giới hạn khoảng 2048 bytes. POST truyền ngầm bên dưới và không giới hạn.","source":"bo1"},{"id":"c7-q4","chapter":7,"difficulty":2,"type":"single","question":"Which HTTP method is typically used to update an existing record on the server?","options":["DELETE","POST","GET","PUT"],"correct":[3],"explanation":"Slide 35: PUT thường được sử dụng để chỉnh sửa (cập nhật) dữ liệu từ Client gửi lên Server. DELETE dùng để xóa.","source":"bo1"},{"id":"c7-q5","chapter":7,"difficulty":2,"type":"single","question":"Thuộc tính `name` trong thẻ `<form>` dùng để làm gì?","options":["Chỉ định trang nhận dữ liệu","Không có tác dụng gì trong thẻ form","Chỉ định phương thức gửi dữ liệu","Đặt tên cho Form"],"correct":[3],"explanation":"Slide 35: Thuộc tính name dùng để đặt tên cho FORM.","source":"bo1"},{"id":"c7-q6","chapter":7,"difficulty":1,"type":"single","question":"Thẻ `<label>` dùng để làm gì?","options":["Tạo một nút bấm","Tạo một ô nhập văn bản","Tạo tiêu đề (nhãn) cho các control trong form","Tạo một danh sách chọn"],"correct":[2],"explanation":"Slide 36: <label> tạo tiêu đề cho các control trong form. Khi click vào label sẽ focus đến control tương ứng (thông qua thuộc tính for).","source":"bo1"},{"id":"c7-q7","chapter":7,"difficulty":2,"type":"single","question":"Trong thẻ `<label>`, thuộc tính `for` nhận giá trị là gì?","options":["class của control","id của control được gắn với label","name của form","value của control"],"correct":[1],"explanation":"Slide 36: Thuộc tính for nhận id của control gắn với label để khi click vào label sẽ focus đến control đó.","source":"bo1"},{"id":"c7-q8","chapter":7,"difficulty":1,"type":"single","question":"Which input type defines a password field?","options":["secret","password","hidden","text"],"correct":[1],"explanation":"Slide 36: type=\"password\" định nghĩa một Password Field (khi gõ sẽ được mã hóa thành các dấu chấm).","source":"bo1"},{"id":"c7-q9","chapter":7,"difficulty":2,"type":"single","question":"Để tạo một ô nhập văn bản nhiều dòng (TextArea), ta sử dụng thẻ nào?","options":["<textbox>","<textarea>","<input type=\"text\">","<input type=\"textarea\">"],"correct":[1],"explanation":"Slide 36: Thẻ <textarea> định nghĩa một vùng nhập văn bản nhiều dòng (với các thuộc tính rows, cols).","source":"bo1"},{"id":"c7-q10","chapter":7,"difficulty":2,"type":"single","question":"Thuộc tính `placeholder` trong thẻ `<input>` có tác dụng gì?","options":["Hiển thị dòng chữ gợi ý mờ trong ô nhập liệu","Thay đổi màu sắc của ô nhập liệu","Đặt giá trị mặc định cho ô nhập liệu","Bắt buộc người dùng phải nhập dữ liệu"],"correct":[0],"explanation":"Slide 36: placeholder hiển thị dòng chữ gợi ý. value là giá trị mặc định. required là bắt buộc nhập.","source":"bo1"},{"id":"c7-q11","chapter":7,"difficulty":2,"type":"single","question":"Để bắt buộc người dùng phải nhập dữ liệu vào một ô `<input>` trước khi submit form, ta dùng thuộc tính nào?","options":["must","validate","required","placeholder"],"correct":[2],"explanation":"Slide 36: Thuộc tính required bắt buộc người dùng phải nhập dữ liệu (giống như câu hỏi trong Quiz 3 của thầy).","source":"bo1"},{"id":"c7-q12","chapter":7,"difficulty":1,"type":"single","question":"Có mấy loại nút (button) cơ bản trên Form?","options":["4 loại: submit, reset, button, cancel","3 loại: submit, reset, button","2 loại: submit, button","1 loại: submit"],"correct":[1],"explanation":"Slide 36: Có 3 loại nút: submit (gửi dữ liệu), reset (đưa về mặc định), button (tự viết script xử lý).","source":"bo1"},{"id":"c7-q13","chapter":7,"difficulty":2,"type":"single","question":"Nút `<input type=\"reset\">` có chức năng gì?","options":["Gửi dữ liệu lên server","Xóa toàn bộ form khỏi trang","Đưa mọi dữ liệu trong form về trạng thái mặc định","Thực thi một đoạn javascript do người dùng viết"],"correct":[2],"explanation":"Slide 36: reset đưa mọi dữ liệu về trạng thái mặc định. submit tự động ra lệnh gửi dữ liệu.","source":"bo1"},{"id":"c7-q14","chapter":7,"difficulty":1,"type":"single","question":"Thẻ `<fieldset>` dùng để làm gì?","options":["Tạo một ô nhập văn bản","Tạo tiêu đề cho form","Nhóm các control lại với nhau trong một khung","Tạo một nút bấm"],"correct":[2],"explanation":"Slide 37: <fieldset> nhóm các control lại với nhau thành một khung viền.","source":"bo1"},{"id":"c7-q15","chapter":7,"difficulty":1,"type":"single","question":"Thẻ nào dùng để tạo tiêu đề (tên nhóm) cho thẻ `<fieldset>`?","options":["<caption>","<title>","<header>","<legend>"],"correct":[3],"explanation":"Slide 37: <legend> tạo tiêu đề nhóm nằm ngay trên viền của khung <fieldset>.","source":"bo1"},{"id":"c7-q16","chapter":7,"difficulty":2,"type":"single","question":"Sự khác biệt cơ bản giữa Checkbox và Radio Button là gì?","options":["Checkbox cho phép chọn nhiều lựa chọn cùng lúc, Radio Button chỉ cho chọn 1 lựa chọn","Checkbox dùng để nhập văn bản, Radio Button dùng để bấm","Cả hai đều chỉ cho chọn 1 lựa chọn","Checkbox chỉ cho chọn 1, Radio Button cho chọn nhiều"],"correct":[0],"explanation":"Slide 38: Checkbox cho phép chọn nhiều lựa chọn, Radio Button chỉ cho chọn một lựa chọn trong một nhóm.","source":"bo1"},{"id":"c7-q17","chapter":7,"difficulty":3,"type":"single","question":"Điều kiện quan trọng nhất để các nút Radio Button được xem là CÙNG MỘT NHÓM (chỉ được chọn 1)?","options":["Thuộc tính value của các thẻ input phải giống nhau","Thuộc tính name của các thẻ input phải giống nhau","Thuộc tính id của các thẻ input phải giống nhau","Các thẻ input phải nằm trong cùng một thẻ div"],"correct":[1],"explanation":"Slide 38: Các đối tượng cùng tên (name) thì thuộc cùng một nhóm. Nếu đặt cùng name, chỉ một Radio được chọn. Nếu khác name, chúng thuộc nhóm khác nhau.","source":"bo1"},{"id":"c7-q18","chapter":7,"difficulty":2,"type":"single","question":"Which input type defines a checkbox?","options":["radio","check","box","checkbox"],"correct":[3],"explanation":"Slide 38: Thuộc tính type=\"checkbox\" định nghĩa một ô checkbox.","source":"bo1"},{"id":"c7-q19","chapter":7,"difficulty":2,"type":"single","question":"Thuộc tính `checked` trong Checkbox và Radio Button có tác dụng gì?","options":["Làm mờ lựa chọn đó đi","Mặc định chọn sẵn lựa chọn đó khi trang web tải xong","Không cho phép người dùng thay đổi lựa chọn","Bắt buộc người dùng phải chọn lựa chọn này"],"correct":[1],"explanation":"Slide 38: Thuộc tính checked giúp mặc định được chọn sẵn.","source":"bo1"},{"id":"c7-q20","chapter":7,"difficulty":1,"type":"single","question":"Thẻ nào được sử dụng để tạo một Combo Box (danh sách thả xuống) trong HTML?","options":["<select>","<option>","<input type=\"dropdown\">","<combobox>"],"correct":[0],"explanation":"Slide 39: Thẻ <select> định nghĩa Combo Box. Thẻ <option> định nghĩa từng phần tử trong danh sách.","source":"bo1"},{"id":"c7-q21","chapter":7,"difficulty":2,"type":"single","question":"Để tạo một Listbox (danh sách hiển thị nhiều dòng và cho phép chọn nhiều), ta thêm thuộc tính nào vào thẻ `<select>`?","options":["size và selected","checkbox và size","multiple và disabled","multiple và size"],"correct":[3],"explanation":"Slide 39: Listbox có thêm 2 thuộc tính: size (số dòng hiển thị) và multiple (cho phép chọn nhiều).","source":"bo1"},{"id":"c7-q22","chapter":7,"difficulty":2,"type":"single","question":"Thẻ `<optgroup>` có tác dụng gì trong thẻ `<select>`?","options":["Chọn một option mặc định","Vô hiệu hóa toàn bộ danh sách","Tạo một option ẩn","Nhóm các option lại với nhau thành từng nhóm"],"correct":[3],"explanation":"Slide 40: <optgroup> nhóm các option lại với nhau. Thuộc tính label để đặt tên nhóm, disabled để không cho chọn cả nhóm.","source":"bo1"},{"id":"c7-q23","chapter":7,"difficulty":2,"type":"single","question":"Trong thẻ `<option>`, thuộc tính nào dùng để mặc định chọn sẵn một phần tử?","options":["default","active","checked","selected"],"correct":[3],"explanation":"Slide 39: Thuộc tính selected giúp option đó được mặc định chọn.","source":"bo1"},{"id":"c7-q24","chapter":7,"difficulty":2,"type":"single","question":"Thẻ `<input type=\"hidden\">` dùng để làm gì?","options":["Ẩn các nút bấm","Mã hóa mật khẩu","Ẩn toàn bộ Form","Lưu trữ giá trị ẩn mà không hiển thị ra trang web"],"correct":[3],"explanation":"Slide 40: hidden dùng lưu trữ giá trị ẩn, người dùng không nhìn thấy trên trang web nhưng dữ liệu vẫn được gửi đi.","source":"bo1"},{"id":"c7-q25","chapter":7,"difficulty":2,"type":"single","question":"Để người dùng chọn và tải file (upload) lên server, ta sử dụng thẻ `<input>` với type nào?","options":["document","file","image","upload"],"correct":[1],"explanation":"Slide 40: type=\"file\" dùng để upload file lên web. Hiển thị nút Choose File.","source":"bo1"},{"id":"c7-q26","chapter":7,"difficulty":3,"type":"single","question":"Cho đoạn mã: `<input type=\"number\" min=\"0\" max=\"10\" step=\"2\" value=\"6\">`. Người dùng có thể nhập giá trị nào sau đây?","options":["5","8","9","7"],"correct":[1],"explanation":"Slide 36: Input number với min=0, max=10, step=2, value=6. Các giá trị hợp lệ là 0, 2, 4, 6, 8, 10. Chỉ có 8 là hợp lệ trong các đáp án.","source":"bo1"},{"id":"c7-q27","chapter":7,"difficulty":3,"type":"single","question":"Trong đoạn mã: `<select name=\"traicay\" multiple size=\"5\">`, thuộc tính `size=\"5\"` có tác dụng gì?","options":["Giới hạn có 5 option trong danh sách","Đặt kích thước chữ là 5px","Hiển thị 5 dòng trong danh sách cùng lúc","Cho phép chọn tối đa 5 lựa chọn"],"correct":[2],"explanation":"Slide 39: size=\"số dòng\" quy định số dòng hiển thị cùng lúc của Listbox.","source":"bo1"},{"id":"c7-q28","chapter":7,"difficulty":3,"type":"single","question":"Which of the following HTML tags is used to create a multi-line text input control?","options":["<textarea>","<textbox>","<input type=\"multiline\">","<input type=\"text\">"],"correct":[0],"explanation":"Slide 36: Thẻ <textarea> định nghĩa vùng nhập văn bản nhiều dòng.","source":"bo1"},{"id":"c7-q29","chapter":7,"difficulty":2,"type":"single","question":"Để nhóm các nút Radio 'Giới tính' (Nam/Nữ) lại thành một nhóm, ta cần đặt thuộc tính name như thế nào?","options":["<input type=\"radio\" name=\"Nam\"> và <input type=\"radio\" name=\"Nu\">","<input type=\"radio\" value=\"gender\"> và <input type=\"radio\" value=\"gender\">","<input type=\"radio\" id=\"gender\"> và <input type=\"radio\" id=\"gender\">","<input type=\"radio\" name=\"gender\" value=\"Nam\"> và <input type=\"radio\" name=\"gender\" value=\"Nu\">"],"correct":[3],"explanation":"Slide 38: Để cùng nhóm, thuộc tính name phải giống nhau (ví dụ: name=\"gender\"). id có thể khác nhau.","source":"bo1"},{"id":"c7-q29b","chapter":7,"difficulty":2,"type":"single","question":"Trong thẻ `<input>`, thuộc tính nào dùng để thay đổi kiểu hiển thị của control (ví dụ: từ textbox sang checkbox)?","options":["format","kind","control","type"],"correct":[3],"explanation":"Slide 36: Thuộc tính type quyết định loại control (text, password, email, checkbox, radio, file, hidden...).","source":"bo1"},{"id":"c7-q30","chapter":7,"difficulty":3,"type":"single","question":"Cho đoạn mã sau: `<input type=\"email\" id=\"email\" name=\"email\" required>`. Phát biểu nào sau đây là ĐÚNG?","options":["Ô nhập liệu này sẽ tự động điền email của người dùng","Người dùng có thể nhập bất kỳ văn bản nào","Người dùng bắt buộc phải nhập đúng định dạng email thì mới được submit","Thuộc tính required không có tác dụng với type=\"email\""],"correct":[2],"explanation":"Slide 36: type=\"email\" sẽ kiểm tra định dạng email trước khi submit. Thuộc tính required bắt buộc phải nhập.","source":"bo1"},{"id":"c7-q31","chapter":7,"difficulty":2,"type":"multiple","question":"Những thuộc tính nào sau đây là của thẻ `<form>`? (chọn nhiều đáp án)","options":["checked","name","action","method"],"correct":[1,2,3],"explanation":"Slide 35: Các thuộc tính của thẻ form gồm: action, method, name, target. Thuộc tính checked dùng cho input/option.","source":"bo1"},{"id":"c7-q32","chapter":7,"difficulty":2,"type":"single","question":"Thẻ `<input>` là thẻ tự đóng (không cần thẻ đóng) hay cần thẻ đóng?","options":["Bắt buộc phải có thẻ </input>","Chỉ cần thẻ đóng khi dùng type=\"text\"","Tùy từng trường hợp","Thẻ tự đóng, không có thẻ </input>"],"correct":[3],"explanation":"Kiến thức tổng hợp: Thẻ <input> là thẻ đơn (empty tag), không có thẻ đóng trong HTML.","source":"bo1"},{"id":"c7-q33","chapter":7,"difficulty":2,"type":"single","question":"Để tạo một nút có chức năng tự viết mã JavaScript xử lý (không tự động submit form), ta dùng type nào?","options":["type=\"action\"","type=\"submit\"","type=\"button\"","type=\"reset\""],"correct":[2],"explanation":"Slide 36: type=\"button\" không có hành động mặc định, người lập trình tự gắn sự kiện (onclick) để xử lý.","source":"bo1"},{"id":"c7-q34","chapter":7,"difficulty":3,"type":"single","question":"Thuộc tính `disabled` trong thẻ `<optgroup>` có tác dụng gì?","options":["Không cho phép người dùng chọn bất kỳ option nào thuộc nhóm đó","Xóa toàn bộ nhóm option khỏi form","Tự động chọn option đầu tiên của nhóm","Ẩn toàn bộ nhóm option khỏi danh sách"],"correct":[0],"explanation":"Slide 40: disabled: không cho chọn (các option trong nhóm sẽ bị mờ và không click được).","source":"bo1"},{"id":"c7-q35","chapter":7,"difficulty":3,"type":"single","question":"Để gửi file từ Client lên Server, form phải có thuộc tính `enctype` là gì? (Kiến thức mở rộng thường đi kèm với type=\"file\")","options":["application/x-www-form-urlencoded","application/json","text/plain","multipart/form-data"],"correct":[3],"explanation":"Kiến thức bổ sung: Khi dùng <input type=\"file\">, thuộc tính enctype của <form> phải là multipart/form-data để truyền file qua HTTP POST.","source":"bo1"},{"id":"c8-q1","chapter":8,"difficulty":1,"type":"single","question":"JavaScript ban đầu được phát triển bởi hãng nào và với tên gọi là gì?","options":["Netscape với tên ECMAScript","Sun Microsystems với tên Java","Netscape với tên LiveScript","Microsoft với tên Jscript"],"correct":[2],"explanation":"Slide 41: Hãng Netscape đưa ra ngôn ngữ script có tên là LiveScript (1995), sau đó đổi tên thành JavaScript. Tên tiêu chuẩn là ECMAScript.","source":"bo1"},{"id":"c8-q2","chapter":8,"difficulty":1,"type":"single","question":"Đâu là cách nhúng trực tiếp mã JavaScript vào tài liệu HTML?","options":["Sử dụng thẻ <js> ... </js>","Sử dụng thẻ <style> ... </style>","Sử dụng thẻ <script> ... </script>","Sử dụng thẻ <javascript> ... </javascript>"],"correct":[2],"explanation":"Slide 41: Nhúng trực tiếp bằng thẻ <script type=\"text/javascript\"> ... </script>.","source":"bo1"},{"id":"c8-q3","chapter":8,"difficulty":1,"type":"single","question":"Để nhúng một file JavaScript bên ngoài vào tài liệu HTML, ta sử dụng cú pháp nào?","options":["<link rel=\"javascript\" href=\"file_javascript.js\">","<script src=\"file_javascript.js\"></script>","<script file=\"file_javascript.js\"></script>","<script href=\"file_javascript.js\"></script>"],"correct":[1],"explanation":"Slide 41: Nhúng từ file khác: <script src=\"file_javascript.js\"></script>.","source":"bo1"},{"id":"c8-q4","chapter":8,"difficulty":2,"type":"single","question":"Khi đặt đoạn script JavaScript trong thẻ <head>, đoạn script đó sẽ được thực thi khi nào?","options":["Thực thi khi người dùng click chuột vào trang","Thực thi ngay khi trang web được mở (trước khi hiển thị nội dung body)","Thực thi sau khi toàn bộ trang web đã tải xong","Không bao giờ thực thi"],"correct":[1],"explanation":"Slide 41: Đặt trong <head>, script thực thi ngay khi trang web được mở. Đặt trong <body>, script thực thi khi trang đang mở (sau khi các script ở head đã chạy).","source":"bo1"},{"id":"c8-q5","chapter":8,"difficulty":1,"type":"single","question":"JavaScript có phân biệt chữ hoa và chữ thường không?","options":["Chỉ phân biệt đối với từ khóa","Không, JavaScript không phân biệt","Có, JavaScript phân biệt chữ hoa chữ thường (case-sensitive)","Chỉ phân biệt đối với tên biến"],"correct":[2],"explanation":"Slide 43: JavaScript phân biệt chữ hoa, chữ thường. Ví dụ: hai biến Java và java là khác nhau.","source":"bo1"},{"id":"c8-q6","chapter":8,"difficulty":2,"type":"single","question":"Trong JavaScript, từ khóa nào được sử dụng để khai báo một biến?","options":["int","var","dim","let (trong ES6)"],"correct":[1],"explanation":"Slide 43: Dùng từ khóa var trước tên biến. (Slide cũng đề cập biến có thể không cần khai báo, nhưng var là cách chuẩn).","source":"bo1"},{"id":"c8-q7","chapter":8,"difficulty":2,"type":"single","question":"Trong JavaScript, kiểu dữ liệu `null` có ý nghĩa gì?","options":["Biến có giá trị bằng 0","Biến chưa được khai báo","Biến không có dữ liệu (giữ chỗ, không có giá trị hữu dụng)","Biến có giá trị chuỗi rỗng"],"correct":[2],"explanation":"Slide 43: Kiểu null chỉ có duy nhất một giá trị: null. Nó mang ý nghĩa là không có dữ liệu, khác với số 0 hay chuỗi rỗng.","source":"bo1"},{"id":"c8-q8","chapter":8,"difficulty":1,"type":"single","question":"Which of the following is NOT a primitive data type in JavaScript?","options":["Object","String","Boolean","Number"],"correct":[0],"explanation":"Slide 43: Các kiểu dữ liệu nguyên thủy gồm String, Number, Boolean, Undefined, Null. Object là kiểu dữ liệu tham chiếu (reference type).","source":"bo1"},{"id":"c8-q9","chapter":8,"difficulty":2,"type":"single","question":"Ký tự `\n` trong một chuỗi JavaScript có tác dụng gì?","options":["Xóa ký tự phía trước","Sang dòng mới (new line)","Tạo một khoảng tab","In ra dấu gạch chéo ngược"],"correct":[1],"explanation":"Slide 43: `\n` là ký tự đặc biệt (escape sequence) dùng để xuống dòng. `\t` là tab, `\b` là backspace.","source":"bo1"},{"id":"c8-q10","chapter":8,"difficulty":1,"type":"single","question":"Toán tử `%` trong JavaScript được gọi là gì và có tác dụng gì?","options":["Modulo (chia lấy nguyên), trả về phần nguyên","Modulus (chia lấy dư), trả về số dư của phép chia","Phần trăm (percent), tính tỷ lệ phần trăm","Nhân (multiply), nhân hai số"],"correct":[1],"explanation":"Slide 44: Toán tử % là Modulus (division remainder), ví dụ 5%2 = 1 (5 chia 2 dư 1).","source":"bo1"},{"id":"c8-q11","chapter":8,"difficulty":2,"type":"single","question":"Cho `x = 5`. Sau khi thực hiện `x++`, giá trị của x là bao nhiêu?","options":["5","4","Không thay đổi","6"],"correct":[3],"explanation":"Slide 44: Toán tử ++ (Increment) tăng giá trị biến lên 1 đơn vị. x = 5, x++ => x = 6.","source":"bo1"},{"id":"c8-q12","chapter":8,"difficulty":1,"type":"single","question":"Trong JavaScript, toán tử `==` và `===` khác nhau như thế nào?","options":["Cả hai đều so sánh giá trị","`==` so sánh giá trị (có ép kiểu), `===` so sánh cả giá trị và kiểu dữ liệu","`==` dùng để gán giá trị, `===` dùng để so sánh","`==` so sánh cả giá trị và kiểu, `===` chỉ so sánh giá trị"],"correct":[1],"explanation":"Kiến thức mở rộng (Slide 44 có bảng so sánh): `==` là equal to (so sánh giá trị, có thể ép kiểu), `===` là strictly equal (so sánh cả giá trị và kiểu dữ liệu).","source":"bo1"},{"id":"c8-q13","chapter":8,"difficulty":2,"type":"single","question":"Toán tử logic `&&` trả về kết quả `true` khi nào?","options":["Khi cả hai biểu thức đều sai","Khi ít nhất một trong hai biểu thức đúng","Khi một biểu thức đúng và một biểu thức sai","Khi cả hai biểu thức đều đúng (true)"],"correct":[3],"explanation":"Slide 44: Toán tử && (AND) trả về true khi cả hai vế đều true. Toán tử || (OR) trả về true khi ít nhất một vế true.","source":"bo1"},{"id":"c8-q14","chapter":8,"difficulty":2,"type":"single","question":"Toán tử ba ngôi (ternary operator) trong JavaScript có cú pháp như thế nào?","options":["condition ? value_if_false : value_if_true","condition ? value_if_true : value_if_false","condition : value_if_true ? value_if_false","value_if_true ? condition : value_if_false"],"correct":[1],"explanation":"Slide 44: Cú pháp: x > y ? return x : return y. Nếu điều kiện đúng trả về giá trị thứ nhất, sai trả về giá trị thứ hai.","source":"bo1"},{"id":"c8-q15","chapter":8,"difficulty":1,"type":"single","question":"Từ khóa nào được sử dụng để khai báo một hàm (function) trong JavaScript?","options":["func","def","void","function"],"correct":[3],"explanation":"Slide 45: Mỗi hàm do người dùng định nghĩa bắt đầu bằng từ khóa function.","source":"bo1"},{"id":"c8-q16","chapter":8,"difficulty":2,"type":"single","question":"Cú pháp khai báo hàm có đối số trong JavaScript là gì?","options":["function TenHam(thamso1, thamso2): { // body }","def TenHam(thamso1, thamso2) { // body }","function TenHam(thamso1, thamso2) => { // body }","function TenHam(thamso1, thamso2) { // body }"],"correct":[3],"explanation":"Slide 45: Cú pháp: function FunctionX(parameter 1, parameter 2,...) { // body of function }.","source":"bo1"},{"id":"c8-q17","chapter":8,"difficulty":2,"type":"single","question":"Một hàm trong JavaScript có thể trả về giá trị bằng cách sử dụng từ khóa nào?","options":["return","result","give","output"],"correct":[0],"explanation":"Slide 45: Sử dụng từ khóa return để trả về giá trị: return (value);","source":"bo1"},{"id":"c8-q18","chapter":8,"difficulty":2,"type":"single","question":"Hàm `eval()` trong JavaScript có chức năng gì?","options":["Đánh giá một chuỗi (thực thi chuỗi như mã JavaScript)","Kiểm tra một giá trị có phải là số không","Chuyển đổi số sang chuỗi","Chuyển đổi chuỗi sang số nguyên"],"correct":[0],"explanation":"Slide 46: eval(string) dùng để đánh giá/thực thi một chuỗi biểu thức JavaScript.","source":"bo1"},{"id":"c8-q19","chapter":8,"difficulty":2,"type":"single","question":"Hàm `isNaN()` trong JavaScript dùng để làm gì?","options":["Kiểm tra một chuỗi có rỗng không","Chuyển đổi một giá trị sang số","Kiểm tra xem một giá trị có phải là 'NaN' (Not a Number) hay không","Làm tròn một số"],"correct":[2],"explanation":"Slide 46: isNaN(testValue) trả về true nếu giá trị không phải là số, ngược lại trả về false.","source":"bo1"},{"id":"c8-q20","chapter":8,"difficulty":2,"type":"single","question":"Hàm nào chuyển đổi một chuỗi thành số nguyên trong JavaScript?","options":["Number()","String()","parseInt()","parseFloat()"],"correct":[2],"explanation":"Slide 46: parseInt() chuyển chuỗi sang số nguyên. parseFloat() chuyển sang số thực. Number() chuyển đối tượng sang số.","source":"bo1"},{"id":"c8-q21","chapter":8,"difficulty":1,"type":"single","question":"Cấu trúc điều kiện if trong JavaScript có cú pháp như thế nào?","options":["if (expression) do { statement }","if expression { statement }","if (expression) { statement }","if (expression) then { statement }"],"correct":[2],"explanation":"Slide 47: Cú pháp: if (<expression>) { <statement> }.","source":"bo1"},{"id":"c8-q22","chapter":8,"difficulty":2,"type":"single","question":"Trong cấu trúc switch, lệnh `break` có tác dụng gì?","options":["Tiếp tục thực hiện case tiếp theo","Bỏ qua case hiện tại và nhảy đến default","Thoát khỏi cấu trúc switch ngay lập tức","Khởi động lại switch"],"correct":[2],"explanation":"Slide 48: break dùng để thoát khỏi switch. Nếu thiếu break, chương trình sẽ tiếp tục thực hiện các case bên dưới (fall-through).","source":"bo1"},{"id":"c8-q23","chapter":8,"difficulty":2,"type":"single","question":"Trong cấu trúc switch, lệnh `default` có tác dụng gì?","options":["Thực hiện khi không có case nào khớp","Thực hiện khi tất cả các case đều khớp","Thực hiện đầu tiên trước khi kiểm tra case","Thực hiện khi có lỗi xảy ra"],"correct":[0],"explanation":"Slide 48: default là trường hợp mặc định, được thực thi nếu không có case nào khớp với biểu thức switch.","source":"bo1"},{"id":"c8-q24","chapter":8,"difficulty":2,"type":"single","question":"Sự khác biệt cơ bản giữa vòng lặp `while` và `do...while` là gì?","options":["Cả hai đều thực hiện ít nhất 1 lần","Cả hai đều kiểm tra điều kiện trước","`while` kiểm tra điều kiện trước, `do...while` thực hiện ít nhất 1 lần rồi mới kiểm tra điều kiện","`while` thực hiện ít nhất 1 lần, `do...while` kiểm tra trước"],"correct":[2],"explanation":"Slide 49, 50: while kiểm tra điều kiện trước (có thể không chạy lần nào). do...while thực hiện statement trước, sau đó mới kiểm tra điều kiện (chạy ít nhất 1 lần).","source":"bo1"},{"id":"c8-q25","chapter":8,"difficulty":2,"type":"single","question":"Trong vòng lặp for, biểu thức `Exp3` đóng vai trò gì?","options":["Biểu thức khởi tạo biến đếm","Biểu thức thoát khỏi vòng lặp","Biểu thức điều kiện để tiếp tục vòng lặp","Biểu thức điều khiển vòng lặp (thường là tăng/giảm biến đếm)"],"correct":[3],"explanation":"Slide 51: for (Exp1; Exp2; Exp3). Exp1 là khởi tạo, Exp2 là điều kiện, Exp3 là biểu thức điều khiển (bước nhảy).","source":"bo1"},{"id":"c8-q26","chapter":8,"difficulty":1,"type":"single","question":"Cú pháp của vòng lặp for trong JavaScript là gì?","options":["for (khởi_tạo, điều_kiện, bước_nhảy) { statement }","for (khởi_tạo; điều_kiện; bước_nhảy) { statement }","for (điều_kiện; khởi_tạo; bước_nhảy) { statement }","for (khởi_tạo; bước_nhảy; điều_kiện) { statement }"],"correct":[1],"explanation":"Slide 51: Cú pháp: for (Exp1; Exp2; Exp3) { statement }. Các phần được ngăn cách bởi dấu chấm phẩy.","source":"bo1"},{"id":"c8-q27","chapter":8,"difficulty":2,"type":"single","question":"Lệnh `continue` trong vòng lặp có tác dụng gì?","options":["Dừng chương trình","Thoát khỏi vòng lặp ngay lập tức","Khởi động lại vòng lặp từ đầu","Bỏ qua phần còn lại của vòng lặp hiện tại và tiếp tục vòng lặp tiếp theo"],"correct":[3],"explanation":"Slide 49, 50, 51: continue bỏ qua các câu lệnh còn lại trong lần lặp hiện tại và chuyển sang lần lặp tiếp theo. break thoát khỏi vòng lặp.","source":"bo1"},{"id":"c8-q28","chapter":8,"difficulty":3,"type":"single","question":"Cho đoạn mã: `var x = 10; var y = '10'; if (x == y) { alert('Bằng nhau'); }`. Kết quả hiển thị là gì?","options":["Hiển thị 'Bằng nhau' vì == so sánh cả kiểu","Không hiển thị gì vì x và y khác kiểu dữ liệu","Hiển thị 'Bằng nhau' vì == so sánh giá trị (có ép kiểu)","Lỗi cú pháp"],"correct":[2],"explanation":"Slide 44: Toán tử == so sánh giá trị sau khi ép kiểu. 10 == '10' trả về true. Nếu dùng === sẽ trả về false.","source":"bo1"},{"id":"c8-q29","chapter":8,"difficulty":3,"type":"single","question":"Đoạn mã sau in ra kết quả gì? `var a = 5; var b = 2; document.write(a % b);`","options":["1","0","2.5","2"],"correct":[0],"explanation":"Slide 44: Toán tử % là chia lấy dư. 5 chia 2 được 2 dư 1. Kết quả là 1.","source":"bo1"},{"id":"c8-q30","chapter":8,"difficulty":3,"type":"single","question":"Cho đoạn mã: `var i = 0; while (i < 3) { document.write(i); i++; }`. Kết quả in ra là gì?","options":["123","1234","012","0123"],"correct":[2],"explanation":"Slide 49: Vòng lặp while chạy khi i < 3. i bắt đầu từ 0, in ra 0, 1, 2. Khi i = 3 thì dừng.","source":"bo1"},{"id":"c8-q31","chapter":8,"difficulty":3,"type":"single","question":"Cho đoạn mã: `var i = 0; do { document.write(i); i++; } while (i < 0);`. Kết quả in ra là gì?","options":["Lỗi vô hạn","Không in gì cả","0","012"],"correct":[2],"explanation":"Slide 50: do...while thực hiện ít nhất 1 lần. i = 0, in ra 0, sau đó i = 1. Kiểm tra 1 < 0 sai nên dừng.","source":"bo1"},{"id":"c8-q32","chapter":8,"difficulty":3,"type":"single","question":"Cho đoạn mã: `var x = 5; switch(x) { case 5: document.write('Năm'); case 6: document.write('Sáu'); break; default: document.write('Khác'); }`. Kết quả là gì?","options":["NămSáu","Năm","Sáu","NămSáuKhác"],"correct":[0],"explanation":"Slide 48: Vì case 5 không có break nên sẽ thực hiện tiếp case 6 (fall-through). Kết quả in ra 'NămSáu' rồi gặp break dừng lại.","source":"bo1"},{"id":"c8-q33","chapter":8,"difficulty":3,"type":"single","question":"Đoạn mã sau cho kết quả gì? `var x = 10; var y = x++ + 5;` Giá trị của x và y lần lượt là:","options":["x = 10, y = 16","x = 11, y = 15","x = 11, y = 16","x = 10, y = 15"],"correct":[1],"explanation":"Slide 44: Toán tử ++ hậu tố (x++) trả về giá trị cũ của x (10) cho biểu thức, sau đó mới tăng x lên 1. Vậy y = 10 + 5 = 15, x = 11.","source":"bo1"},{"id":"c8-q34","chapter":8,"difficulty":3,"type":"single","question":"Cho đoạn mã: `var s = ''; for (var i = 1; i <= 3; i++) { s += i; }`. Kết quả của s là gì?","options":["'123'","'6'","'1234'","'012'"],"correct":[0],"explanation":"Slide 51: Vòng lặp for chạy i từ 1 đến 3. s += i tương đương s = s + i (nối chuỗi). Kết quả là '123'.","source":"bo1"},{"id":"c8-q35","chapter":8,"difficulty":1,"type":"single","question":"How do you write an IF statement in JavaScript?","options":["if i = 5 then { }","if (i == 5) then { }","if i == 5 then { }","if (i == 5) { }"],"correct":[3],"explanation":"Slide 47: Cú pháp if trong JavaScript là: if (điều_kiện) { câu_lệnh }.","source":"bo1"},{"id":"c8-q36","chapter":8,"difficulty":2,"type":"single","question":"How does a WHILE loop start?","options":["while i <= 10","while (i <= 10)","while i = 1 to 10","while (i <= 10; i++)"],"correct":[1],"explanation":"Slide 49: Cú pháp while: while (expression) { statement }. Không có phần khởi tạo và bước nhảy như for.","source":"bo1"},{"id":"c8-q37","chapter":8,"difficulty":2,"type":"single","question":"How does a FOR loop start?","options":["for (i = 0; i <= 5)","for (i <= 5; i++)","for i = 1 to 5","for (i = 0; i <= 5; i++)"],"correct":[3],"explanation":"Slide 51: Cú pháp for: for (khởi_tạo; điều_kiện; bước_nhảy) { statement }.","source":"bo1"},{"id":"c8-q38","chapter":8,"difficulty":2,"type":"single","question":"What is the correct way to write a JavaScript array? (Kiến thức mở rộng)","options":["var colors = 1 = ('red'), 2 = ('green');","var colors = 'red', 'green', 'blue';","var colors = ['red', 'green', 'blue'];","var colors = (1:'red', 2:'green', 3:'blue');"],"correct":[2],"explanation":"Kiến thức mở rộng: Mảng trong JavaScript được khai báo bằng dấu ngoặc vuông [] và các phần tử ngăn cách bởi dấu phẩy.","source":"bo1"},{"id":"c8-q39","chapter":8,"difficulty":2,"type":"multiple","question":"Trong JavaScript, những kiểu dữ liệu nào sau đây được coi là kiểu nguyên thủy (primitive)? (chọn nhiều đáp án)","options":["Number","Object","Boolean","String"],"correct":[0,2,3],"explanation":"Slide 43: Các kiểu nguyên thủy gồm String, Number, Boolean, Undefined, Null. Object là kiểu tham chiếu.","source":"bo1"},{"id":"c8-q40","chapter":8,"difficulty":2,"type":"multiple","question":"Những toán tử nào sau đây là toán tử so sánh (comparison operator) trong JavaScript? (chọn nhiều đáp án)","options":["!=","==","=",">="],"correct":[0,1,3],"explanation":"Slide 44: Toán tử so sánh gồm ==, !=, >, <, >=, <=. Dấu = là toán tử gán (assignment operator).","source":"bo1"},{"id":"c8-q41","chapter":8,"difficulty":3,"type":"single","question":"Đoạn mã sau có lỗi không? `var 1stName = 'John';`","options":["Có lỗi vì thiếu từ khóa var","Có lỗi vì chuỗi phải dùng nháy kép","Không lỗi, biến hợp lệ","Có lỗi vì tên biến không được bắt đầu bằng số"],"correct":[3],"explanation":"Kiến thức mở rộng (Slide 43): Tên biến trong JavaScript không được bắt đầu bằng chữ số. Phải bắt đầu bằng chữ cái, dấu gạch dưới _, hoặc dấu $.","source":"bo1"},{"id":"c8-q42","chapter":8,"difficulty":3,"type":"single","question":"Hàm `parseInt('123abc')` trả về kết quả gì?","options":["123","'123abc'","NaN","0"],"correct":[0],"explanation":"Slide 46: parseInt() sẽ phân tích chuỗi từ trái sang phải cho đến khi gặp ký tự không phải số. '123abc' trả về 123. Nếu chuỗi bắt đầu bằng chữ (vd 'abc123') sẽ trả về NaN.","source":"bo1"},{"id":"c9-q1","chapter":9,"difficulty":1,"type":"single","question":"Hàm nào trong JavaScript trả về vị trí xuất hiện ĐẦU TIÊN của một chuỗi con trong chuỗi gốc?","options":["search()","indexOf()","find()","lastIndexOf()"],"correct":[1],"explanation":"Slide 52: indexOf() trả về vị trí xuất hiện đầu tiên của chuỗi con. lastIndexOf() trả về vị trí cuối cùng.","source":"bo1"},{"id":"c9-q2","chapter":9,"difficulty":2,"type":"single","question":"Cho chuỗi `var str = \"time and tide wait for no man\";`. Hàm `str.lastIndexOf(\"an\")` trả về giá trị bao nhiêu?","options":["5","2","27","-1"],"correct":[2],"explanation":"Slide 52: lastIndexOf tìm vị trí cuối cùng của chuỗi \"an\". Trong chuỗi trên, \"an\" xuất hiện ở vị trí 27 (trong từ \"man\").","source":"bo1"},{"id":"c9-q3","chapter":9,"difficulty":2,"type":"single","question":"Hàm `search()` trong JavaScript khác gì so với `indexOf()`?","options":["Hàm search() không thể tìm chuỗi con","Hàm search() cho phép tìm kiếm bằng Regular Expression (biểu thức chính quy)","Hàm search() trả về vị trí cuối cùng, indexOf() trả về vị trí đầu tiên","Hàm search() phân biệt chữ hoa chữ thường, indexOf() thì không"],"correct":[1],"explanation":"Slide 52: search() tương tự indexOf nhưng cho phép tìm kiếm bằng Regular Expression. Ví dụ: str.search(/w3schools/i) để tìm không phân biệt hoa thường.","source":"bo1"},{"id":"c9-q4","chapter":9,"difficulty":2,"type":"single","question":"Hàm `substring(start, end)` và `slice(start, end)` khác nhau cơ bản ở điểm nào?","options":["Hàm substring() trả về mảng, hàm slice() trả về chuỗi","Cả hai hàm hoàn toàn giống nhau","Hàm substring() cho phép truyền tham số âm, hàm slice() thì không","Hàm slice() cho phép truyền tham số âm (đếm ngược từ cuối chuỗi), hàm substring() thì không"],"correct":[3],"explanation":"Slide 52: slice() hỗ trợ chỉ số âm (ví dụ: str.slice(-12) sẽ lấy từ vị trí 12 tính từ cuối chuỗi lên). substring() không hỗ trợ chỉ số âm.","source":"bo1"},{"id":"c9-q5","chapter":9,"difficulty":3,"type":"single","question":"Cho `var str = \"Apple, Banana, Kiwi\";`. Kết quả của `str.substr(7, 6)` là gì?","options":["\"Apple,\"","\"Banana,\"","\"Kiwi\"","\"Banana\""],"correct":[3],"explanation":"Slide 52: substr(start, length) lấy từ vị trí 7 (ký tự 'B') với độ dài 6 ký tự => \"Banana\".","source":"bo1"},{"id":"c9-q6","chapter":9,"difficulty":1,"type":"single","question":"Để tách một chuỗi thành một mảng các chuỗi con dựa trên một ký tự phân cách, ta sử dụng hàm nào?","options":["concat()","slice()","split()","join()"],"correct":[2],"explanation":"Slide 53: Hàm split() tách chuỗi thành mảng. Ví dụ: \"a,b,c\".split(\",\") => [\"a\",\"b\",\"c\"].","source":"bo1"},{"id":"c9-q7","chapter":9,"difficulty":2,"type":"single","question":"Hàm nào dùng để nối hai hoặc nhiều chuỗi lại với nhau?","options":["join()","merge()","concat()","append()"],"correct":[2],"explanation":"Slide 53: Hàm concat() dùng để nối chuỗi. Ngoài ra có thể dùng toán tử +.","source":"bo1"},{"id":"c9-q8","chapter":9,"difficulty":2,"type":"single","question":"Cho chuỗi `str = \"Please visit Microsoft and Microsoft!\";`. Để thay thế TẤT CẢ các từ \"Microsoft\" thành \"W3Schools\", ta viết lệnh như thế nào?","options":["str.replace(\"Microsoft\", \"W3Schools\")","str.replaceAll(\"Microsoft\", \"W3Schools\")","str.replace(/Microsoft/, \"W3Schools\")","str.replace(/Microsoft/g, \"W3Schools\")"],"correct":[3],"explanation":"Slide 53: Để thay thế tất cả, cần dùng Regular Expression với cờ g (global): /Microsoft/g. Nếu chỉ dùng replace(\"Microsoft\", ...) thì chỉ thay thế lần xuất hiện đầu tiên.","source":"bo1"},{"id":"c9-q9","chapter":9,"difficulty":2,"type":"single","question":"Cho `var str = \"Visit W3Schools\";`. Để tìm vị trí của \"w3schools\" mà KHÔNG phân biệt chữ hoa chữ thường, ta dùng lệnh nào?","options":["str.search(\"w3schools\")","str.search(/w3schools/g)","str.indexOf(\"w3schools\")","str.search(/w3schools/i)"],"correct":[3],"explanation":"Slide 52: Cờ i (case-insensitive) trong Regular Expression giúp tìm kiếm không phân biệt hoa thường.","source":"bo1"},{"id":"c9-q10","chapter":9,"difficulty":1,"type":"single","question":"Hàm nào chuyển đổi một chuỗi thành chữ IN HOA?","options":["upperCase()","toLowerCase()","toUpperCase()","toUpper()"],"correct":[2],"explanation":"Slide 53: toUpperCase() chuyển sang chữ hoa. toLowerCase() chuyển sang chữ thường.","source":"bo1"},{"id":"c9-q11","chapter":9,"difficulty":1,"type":"single","question":"Hàm `charAt(index)` trong JavaScript có tác dụng gì?","options":["Trả về vị trí của ký tự trong chuỗi","Trả về mã ASCII của ký tự","Trả về ký tự tại vị trí index trong chuỗi","Xóa ký tự tại vị trí index"],"correct":[2],"explanation":"Slide 53: charAt(0) trả về ký tự đầu tiên của chuỗi. Ví dụ: \"HELLO\".charAt(0) => \"H\".","source":"bo1"},{"id":"c9-q12","chapter":9,"difficulty":1,"type":"single","question":"Để thực hiện các phép tính toán học nâng cao (sin, cos, căn bậc 2, lũy thừa...), ta sử dụng đối tượng nào trong JavaScript?","options":["Number","Array","Date","Math"],"correct":[3],"explanation":"Slide 54: Đối tượng Math chứa các thuộc tính và phương thức cho phép tính toán học.","source":"bo1"},{"id":"c9-q13","chapter":9,"difficulty":2,"type":"single","question":"Kết quả của `Math.round(4.7)` là bao nhiêu?","options":["5","4.5","5.0","4"],"correct":[0],"explanation":"Slide 54: Math.round() làm tròn đến số nguyên gần nhất. 4.7 làm tròn thành 5. Math.round(4.4) làm tròn thành 4.","source":"bo1"},{"id":"c9-q14","chapter":9,"difficulty":2,"type":"single","question":"Sự khác biệt giữa `Math.ceil()` và `Math.floor()` là gì?","options":["Cả hai đều làm tròn đến số gần nhất","Cả hai đều trả về phần nguyên","Math.ceil() làm tròn XUỐNG, Math.floor() làm tròn LÊN","Math.ceil() làm tròn LÊN, Math.floor() làm tròn XUỐNG"],"correct":[3],"explanation":"Slide 54: Math.ceil(4.4) => 5 (làm tròn lên). Math.floor(4.7) => 4 (làm tròn xuống).","source":"bo1"},{"id":"c9-q15","chapter":9,"difficulty":2,"type":"single","question":"Kết quả của `Math.max(0, 150, 30, 20, -8, -200)` là gì?","options":["0","150","-200","30"],"correct":[1],"explanation":"Slide 54: Math.max() trả về giá trị lớn nhất trong các đối số. Giá trị lớn nhất ở đây là 150. Math.min() trả về -200.","source":"bo1"},{"id":"c9-q16","chapter":9,"difficulty":2,"type":"single","question":"Đối tượng `Date` trong JavaScript lưu trữ thời gian dưới dạng số mili giây tính từ mốc thời gian nào?","options":["1/1/1970 00:00:00","1/1/1900 00:00:00","1/1/2000 00:00:00","1/1/1980 00:00:00"],"correct":[0],"explanation":"Slide 54: Date lưu trữ thời gian theo số mili giây tính từ 1/1/1970 00:00:00.","source":"bo1"},{"id":"c9-q17","chapter":9,"difficulty":2,"type":"single","question":"Để lấy năm (4 chữ số) của một đối tượng Date, ta sử dụng phương thức nào?","options":["getDate()","getMonth()","getYear()","getFullYear()"],"correct":[3],"explanation":"Slide 54: getFullYear() trả về năm (bốn chữ số). getMonth() trả về tháng (0-11). getDate() trả về ngày trong tháng (1-31).","source":"bo1"},{"id":"c9-q18","chapter":9,"difficulty":3,"type":"single","question":"Phương thức `getMonth()` của đối tượng Date trả về giá trị trong khoảng nào?","options":["Từ 0 đến 11","Từ 1 đến 31","Từ 0 đến 31","Từ 1 đến 12"],"correct":[0],"explanation":"Slide 54: getMonth() trả về tháng từ 0 (tháng 1) đến 11 (tháng 12). Đây là lưu ý quan trọng khi lập trình với Date.","source":"bo1"},{"id":"c9-q19","chapter":9,"difficulty":1,"type":"single","question":"Cách khai báo một mảng trong JavaScript là gì?","options":["var arr = {1, 2, 3};","var arr = [1, 2, 3]; hoặc var arr = new Array();","var arr = (1, 2, 3);","var arr = <1, 2, 3>;"],"correct":[1],"explanation":"Slide 54: Có 2 cách khai báo mảng: dùng dấu ngoặc vuông [] hoặc dùng từ khóa new Array().","source":"bo1"},{"id":"c9-q20","chapter":9,"difficulty":2,"type":"single","question":"Hàm nào thêm một phần tử vào CUỐI mảng và trả về độ dài mới của mảng?","options":["shift()","unshift()","push()","pop()"],"correct":[2],"explanation":"Slide 54: push() thêm vào cuối mảng. pop() xóa phần tử cuối. unshift() thêm vào đầu. shift() xóa phần tử đầu.","source":"bo1"},{"id":"c9-q21","chapter":9,"difficulty":2,"type":"single","question":"Hàm nào xóa phần tử ĐẦU TIÊN của mảng và trả về phần tử đó?","options":["pop()","push()","shift()","unshift()"],"correct":[2],"explanation":"Slide 54: shift() xóa phần tử đầu tiên và trả về phần tử đó.","source":"bo1"},{"id":"c9-q22","chapter":9,"difficulty":1,"type":"single","question":"Để truy cập vào thuộc tính `name` của một đối tượng `car`, ta có thể viết như thế nào?","options":["car.name hoặc car[\"name\"]","car->name","car::name","car(name)"],"correct":[0],"explanation":"Slide 55: Truy cập thuộc tính: objectName.propertyName hoặc objectName[\"propertyName\"].","source":"bo1"},{"id":"c9-q23","chapter":9,"difficulty":2,"type":"single","question":"Trong một phương thức của đối tượng, từ khóa nào đại diện cho chính đối tượng đó?","options":["self","this","object","me"],"correct":[1],"explanation":"Slide 55: Từ khóa this được dùng để tham chiếu đến đối tượng hiện tại. Ví dụ: this.firstName + \" \" + this.lastName.","source":"bo1"},{"id":"c9-q24","chapter":9,"difficulty":2,"type":"single","question":"Đoạn mã sau khai báo một đối tượng có phương thức. Làm thế nào để gọi phương thức `fullName`?\n`var person = { firstName: \"John\", lastName: \"Doe\", fullName: function() { return this.firstName + \" \" + this.lastName; } };`","options":["fullName(person)","person->fullName()","person.fullName()","person.fullName"],"correct":[2],"explanation":"Slide 55: Để gọi phương thức, ta dùng cú pháp objectName.methodName().","source":"bo1"},{"id":"c9-q25","chapter":9,"difficulty":2,"type":"single","question":"Trong đoạn mã trên, `firstName` và `lastName` được gọi là gì của đối tượng `person`?","options":["Hàm (Functions)","Thuộc tính (Properties)","Biến toàn cục (Global variables)","Phương thức (Methods)"],"correct":[1],"explanation":"Slide 55: firstName, lastName, id là các thuộc tính (properties). fullName là phương thức (method).","source":"bo1"},{"id":"c9-q26","chapter":9,"difficulty":3,"type":"single","question":"Cho đoạn mã: `var str = \"SV1;Tèo Mộng Mơ;teo@uel.edu.vn\"; var arr = str.split(\";\");`. Giá trị của `arr[2]` là gì?","options":["\"Tèo Mộng Mơ\"","\"SV1\"","\";\"","\"teo@uel.edu.vn\""],"correct":[3],"explanation":"Slide 53: Hàm split(\";\") tách chuỗi thành mảng 3 phần tử: arr[0] = \"SV1\", arr[1] = \"Tèo Mộng Mơ\", arr[2] = \"teo@uel.edu.vn\".","source":"bo1"},{"id":"c9-q27","chapter":9,"difficulty":3,"type":"single","question":"Kết quả của đoạn mã sau là gì? `var str = \"Hello World\"; document.write(str.charAt(6));`","options":["\"W\"","\"o\"","\"H\"","\" \" (khoảng trắng)"],"correct":[0],"explanation":"Slide 53: charAt(6) lấy ký tự tại vị trí số 6 (tính từ 0). Chuỗi \"Hello World\" có H(0), e(1), l(2), l(3), o(4), khoảng trắng(5), W(6). Vậy kết quả là \"W\".","source":"bo1"},{"id":"c9-q28","chapter":9,"difficulty":3,"type":"single","question":"Đoạn mã sau in ra kết quả gì? `var x = [1, 2, 3]; x.push(4); document.write(x.length);`","options":["1","5","4","3"],"correct":[2],"explanation":"Slide 54: push(4) thêm phần tử 4 vào cuối mảng. Mảng trở thành [1, 2, 3, 4] có độ dài là 4.","source":"bo1"},{"id":"c9-q29","chapter":9,"difficulty":3,"type":"single","question":"Cho đối tượng `var car = { type: \"Fiat\", model: \"500\", color: \"white\" };`. Lệnh nào sau đây trả về giá trị \"500\"?","options":["car.model","car(\"model\")","car->model","car[model]"],"correct":[0],"explanation":"Slide 55: Truy cập thuộc tính bằng dấu chấm: car.model. Hoặc car[\"model\"] (có ngoặc kép).","source":"bo1"},{"id":"c9-q30","chapter":9,"difficulty":3,"type":"single","question":"Đoạn mã sau in ra kết quả gì? `var d = new Date(); document.write(d.getMonth());` (Giả sử tháng hiện tại là tháng 10)","options":["9","0","10","11"],"correct":[0],"explanation":"Slide 54: getMonth() trả về tháng từ 0-11. Tháng 10 tương ứng với giá trị 9. Đây là lỗi phổ biến của người mới lập trình.","source":"bo1"},{"id":"c9-q31","chapter":9,"difficulty":2,"type":"single","question":"Which method is used to remove the last element from an array in JavaScript?","options":["unshift()","shift()","pop()","push()"],"correct":[2],"explanation":"Slide 54: pop() xóa phần tử cuối cùng của mảng.","source":"bo1"},{"id":"c9-q32","chapter":9,"difficulty":3,"type":"single","question":"Đoạn mã sau cho kết quả là gì? `var str = \"Apple, Banana, Kiwi\"; document.write(str.substring(7, 13));`","options":["\"Apple,\"","\"Banana,\"","\"Banana\"","\"Kiwi\""],"correct":[2],"explanation":"Slide 52: substring(7, 13) lấy từ ký tự thứ 7 đến ký tự thứ 12 (13-1). Chuỗi \"Apple, Banana, Kiwi\": A(0)p(1)p(2)l(3)e(4),(5) (6)B(7)a(8)n(9)a(10)n(11)a(12). Kết quả: \"Banana\".","source":"bo1"},{"id":"c9-q33","chapter":9,"difficulty":2,"type":"single","question":"Hàm `Math.abs(-4.7)` trả về giá trị bao nhiêu?","options":["5","-5","4.7","-4.7"],"correct":[2],"explanation":"Slide 54: Math.abs() trả về giá trị tuyệt đối. abs(-4.7) = 4.7.","source":"bo1"},{"id":"c9-q34","chapter":9,"difficulty":2,"type":"single","question":"Làm thế nào để khai báo một mảng rỗng trong JavaScript?","options":["var arr = new Array[];","var arr = {};","var arr = [];","var arr = ();"],"correct":[2],"explanation":"Slide 54: Mảng rỗng được khai báo bằng []. Dấu {} dùng cho object.","source":"bo1"},{"id":"c9-q35","chapter":9,"difficulty":3,"type":"single","question":"Đoạn mã sau in ra kết quả gì? `var s = \"Hello\"; s = s.concat(\" \", \"World\"); document.write(s);`","options":["\"HelloWorld\"","\"Hello World\"","\"Hello World!\"","Lỗi cú pháp"],"correct":[1],"explanation":"Slide 53: concat() nối các chuỗi. \"Hello\".concat(\" \", \"World\") => \"Hello World\".","source":"bo1"},{"id":"c9-q36","chapter":9,"difficulty":3,"type":"single","question":"Cho đối tượng: `var person = { firstName: \"John\", lastName: \"Doe\", fullName: function() { return this.firstName + \" \" + this.lastName; } };`. Kết quả của `person.fullName()` là gì?","options":["\"John Doe\"","\"firstName lastName\"","\"undefined undefined\"","Lỗi vì thiếu this"],"correct":[0],"explanation":"Slide 55: Phương thức fullName trả về this.firstName + \" \" + this.lastName = \"John Doe\".","source":"bo1"},{"id":"c9-q37","chapter":9,"difficulty":3,"type":"single","question":"Trong JavaScript, để lấy ngày hiện tại của hệ thống (ví dụ: 15), ta dùng phương thức nào?","options":["getCurrentDate()","getDate()","getDay()","getToday()"],"correct":[1],"explanation":"Slide 54: getDate() trả về ngày trong tháng (1-31). getDay() trả về thứ trong tuần (0-6).","source":"bo1"},{"id":"c9-q38","chapter":9,"difficulty":2,"type":"single","question":"Để tách một chuỗi thành mảng dựa trên ký tự khoảng trắng, ta viết lệnh như thế nào?","options":["str.slice(\" \")","str.concat(\" \")","str.split(\"\")","str.split(\" \")"],"correct":[3],"explanation":"Slide 53: split(\" \") sẽ tách chuỗi tại mỗi khoảng trắng. split(\"\") sẽ tách thành từng ký tự.","source":"bo1"},{"id":"c10-q1","chapter":10,"difficulty":1,"type":"single","question":"HTML DOM là viết tắt của cụm từ nào?","options":["HTML Dynamic Object Model","HTML Data Object Model","HTML Document Oriented Model","HTML Document Object Model"],"correct":[3],"explanation":"Slide 56: HTML DOM = HTML Document Object Model.","source":"bo1"},{"id":"c10-q2","chapter":10,"difficulty":1,"type":"single","question":"Trong mô hình DOM, nút gốc (Root element) của một tài liệu HTML thường là thẻ nào?","options":["<head>","<html>","<body>","<document>"],"correct":[1],"explanation":"Slide 56: Nút gốc là <html>. Tất cả các nút còn lại trong DOM đều chứa trong <html>.","source":"bo1"},{"id":"c10-q3","chapter":10,"difficulty":2,"type":"single","question":"Trong cây DOM, nút <head> và nút <body> có mối quan hệ như thế nào?","options":["Là cha-con của nhau","Cả hai đều là nút gốc","Là anh em với nút <html>","Là hai nút con (children) của nút <html> và là anh em (siblings) của nhau"],"correct":[3],"explanation":"Slide 56: Nút <html> có hai nút con là <head> và <body>. Ngang cấp với nhau gọi là nút sibling (anh em).","source":"bo1"},{"id":"c10-q4","chapter":10,"difficulty":1,"type":"single","question":"Phương thức nào của đối tượng `document` dùng để tìm một phần tử HTML dựa vào thuộc tính id?","options":["document.getElementById(id)","document.getElementsByClassName(name)","document.getElementsByTagName(name)","document.querySelector(id)"],"correct":[0],"explanation":"Slide 57: document.getElementById(id) tìm element theo id.","source":"bo1"},{"id":"c10-q5","chapter":10,"difficulty":2,"type":"single","question":"Thuộc tính nào của HTML Element dùng để lấy hoặc gán nội dung văn bản có chứa các thẻ HTML bên trong?","options":["innerHTML","outerHTML","textContent","innerText"],"correct":[0],"explanation":"Slide 57: innerHTML trả về/thiết lập giá trị text có định dạng HTML. innerText chỉ trả về text thuần.","source":"bo1"},{"id":"c10-q6","chapter":10,"difficulty":2,"type":"single","question":"Làm thế nào để thay đổi giá trị thuộc tính `src` của một thẻ `<img>` thông qua DOM?","options":["img.src.set(\"new_image.png\")","img.attribute(\"src\", \"new_image.png\")","img.style.src = \"new_image.png\"","img.setAttribute(\"src\", \"new_image.png\")"],"correct":[3],"explanation":"Slide 58: Sử dụng phương thức setAttribute(\"tên_thuộc_tính\", \"giá_trị\") để thay đổi giá trị thuộc tính.","source":"bo1"},{"id":"c10-q7","chapter":10,"difficulty":2,"type":"single","question":"Để tạo mới một phần tử HTML bằng JavaScript, ta sử dụng phương thức nào?","options":["document.createElement(tagName)","document.newElement(tagName)","document.createNode(tagName)","document.addElement(tagName)"],"correct":[0],"explanation":"Slide 59: Sử dụng document.createElement(\"tag\") để tạo mới một HTML element.","source":"bo1"},{"id":"c10-q8","chapter":10,"difficulty":2,"type":"single","question":"Sau khi tạo mới một element, để thêm nó vào một element cha (holder) trên cây DOM, ta dùng phương thức nào?","options":["parentElement.appendChild(newElement)","parentElement.addChild(newElement)","parentElement.push(newElement)","parentElement.insertNode(newElement)"],"correct":[0],"explanation":"Slide 59: Sử dụng appendChild(node) để thêm nút con vào nút cha.","source":"bo1"},{"id":"c10-q9","chapter":10,"difficulty":2,"type":"single","question":"Để xóa một nút con khỏi cây DOM, ta sử dụng phương thức nào?","options":["parentElement.pop(childNode)","childNode.remove()","parentElement.removeChild(childNode)","parentElement.deleteChild(childNode)"],"correct":[2],"explanation":"Slide 61: Sử dụng removeChild(node) của nút cha để xóa nút con.","source":"bo1"},{"id":"c10-q10","chapter":10,"difficulty":1,"type":"single","question":"XML là viết tắt của cụm từ nào?","options":["EXternal Markup Language","EXtensible Markup Logic","EXtra Markup Language","EXtensible Markup Language"],"correct":[3],"explanation":"Slide 62: XML = EXtensible Markup Language (Ngôn ngữ đánh dấu mở rộng).","source":"bo1"},{"id":"c10-q11","chapter":10,"difficulty":2,"type":"single","question":"Mục đích chính của XML là gì?","options":["Lưu trữ và trao đổi dữ liệu","Định dạng CSS cho trang web","Hiển thị dữ liệu lên trình duyệt","Tạo giao diện người dùng"],"correct":[0],"explanation":"Slide 62: HTML dùng để hiển thị dữ liệu, XML dùng để lưu trữ và trao đổi dữ liệu.","source":"bo1"},{"id":"c10-q12","chapter":10,"difficulty":2,"type":"single","question":"Phát biểu nào sau đây là ĐÚNG về cú pháp XML?","options":["XML có thể có nhiều thẻ root","Giá trị thuộc tính không cần đặt trong dấu nháy","XML không cần thẻ đóng","Thẻ XML có phân biệt chữ hoa chữ thường"],"correct":[3],"explanation":"Slide 62: Tên thẻ XML phân biệt chữ hoa/thường. Mọi thẻ phải có thẻ đóng. Phải có duy nhất 1 thẻ root. Giá trị thuộc tính phải đặt trong nháy.","source":"bo1"},{"id":"c10-q13","chapter":10,"difficulty":2,"type":"single","question":"Trong XML, ký tự `<` (nhỏ hơn) được biểu diễn bằng mã nào?","options":["&gt;","&amp;","&apos;","&lt;"],"correct":[3],"explanation":"Slide 62: `<` là `&lt;` (less than). `>` là `&gt;` (greater than). `&` là `&amp;`.","source":"bo1"},{"id":"c10-q14","chapter":10,"difficulty":1,"type":"single","question":"Cách viết ghi chú (comment) trong tài liệu XML là gì?","options":["# Nội dung ghi chú","// Nội dung ghi chú","<!-- Nội dung ghi chú -->","/* Nội dung ghi chú */"],"correct":[2],"explanation":"Slide 62: Comment trong XML giống hệt HTML: <!-- comment -->.","source":"bo1"},{"id":"c10-q15","chapter":10,"difficulty":2,"type":"single","question":"Để chuyển một chuỗi văn bản XML thành một đối tượng XML Document trong JavaScript, ta sử dụng đối tượng nào?","options":["DOMParser","XMLHttpRequest","JSONParser","XMLSerializer"],"correct":[0],"explanation":"Slide 63: Sử dụng `new DOMParser()` và phương thức `parseFromString(text, \"text/xml\")`.","source":"bo1"},{"id":"c10-q16","chapter":10,"difficulty":3,"type":"single","question":"Cho `xmlDoc` là một đối tượng XML Document. Làm thế nào để lấy giá trị text của thẻ `<title>` đầu tiên?","options":["xmlDoc.querySelector(\"title\").text","xmlDoc.getElement(\"title\").value","xmlDoc.getElementsByTagName(\"title\").innerHTML","xmlDoc.getElementsByTagName(\"title\")[0].childNodes[0].nodeValue"],"correct":[3],"explanation":"Slide 63: Truy cập XML giống như DOM: `getElementsByTagName(\"tag\")[index].childNodes[0].nodeValue`.","source":"bo1"},{"id":"c10-q17","chapter":10,"difficulty":1,"type":"single","question":"AJAX là viết tắt của cụm từ nào?","options":["Asynchronous JavaScript and XML","Asynchronous Java and XML","Automatic JavaScript and XML","Advanced JavaScript and XML"],"correct":[0],"explanation":"Slide 65: AJAX = Asynchronous JavaScript and XML.","source":"bo1"},{"id":"c10-q18","chapter":10,"difficulty":2,"type":"single","question":"Đối tượng cốt lõi nào của JavaScript được sử dụng để thực hiện các yêu cầu AJAX?","options":["AjaxRequest","XMLHttpRequest","HttpRequest","FetchRequest"],"correct":[1],"explanation":"Slide 65: Đối tượng cốt lõi là XMLHttpRequest (hoặc ActiveXObject với IE6).","source":"bo1"},{"id":"c10-q19","chapter":10,"difficulty":2,"type":"single","question":"Để khởi tạo một đối tượng AJAX trên các trình duyệt hiện đại, ta viết mã như thế nào?","options":["var xhr = new XMLHttpRequest;","var xhr = new XMLHttpRequest();","var xhr = XMLHttpRequest();","var xhr = new ActiveXObject(\"Microsoft.XMLHTTP\");"],"correct":[1],"explanation":"Slide 65: Khởi tạo bằng từ khóa new: var xhr = new XMLHttpRequest();","source":"bo1"},{"id":"c10-q20","chapter":10,"difficulty":2,"type":"single","question":"Phương thức `open()` của đối tượng XMLHttpRequest nhận những tham số nào?","options":["url, data, true","url, method, async","method, url, async","method, data, async"],"correct":[2],"explanation":"Slide 65: Cú pháp: xhr.open(method, url, async). (VD: xhr.open(\"GET\", \"data.xml\", true)).","source":"bo1"},{"id":"c10-q21","chapter":10,"difficulty":2,"type":"single","question":"Trong AJAX, trạng thái `readyState == 4` có ý nghĩa gì?","options":["Đã nhận được yêu cầu","Đang kết nối tới server","Yêu cầu đã hoàn tất và dữ liệu đã sẵn sàng để xử lý","Đang xử lý yêu cầu"],"correct":[2],"explanation":"Slide 65: readyState = 4 nghĩa là request finished and response is ready.","source":"bo1"},{"id":"c10-q22","chapter":10,"difficulty":2,"type":"single","question":"Để kiểm tra một yêu cầu AJAX đã thành công và dữ liệu đã sẵn sàng, ta kiểm tra điều kiện nào?","options":["xhr.readyState == 4 && xhr.status == 404","xhr.readyState == 3 && xhr.status == 200","xhr.readyState == 4 && xhr.status == 200","xhr.readyState == 200 && xhr.status == 4"],"correct":[2],"explanation":"Slide 65: Trạng thái 200 là \"OK\". Điều kiện chuẩn: readyState == 4 && status == 200.","source":"bo1"},{"id":"c10-q23","chapter":10,"difficulty":3,"type":"single","question":"Thuộc tính nào của đối tượng XMLHttpRequest dùng để lấy dữ liệu phản hồi từ server dưới định dạng XML?","options":["responseXML","responseText","responseData","responseJSON"],"correct":[0],"explanation":"Slide 65: responseXML trả về dữ liệu dạng XML. responseText trả về dữ liệu dạng chuỗi (string).","source":"bo1"},{"id":"c10-q24","chapter":10,"difficulty":3,"type":"single","question":"Cho đoạn mã: `var p = document.getElementById(\"demo\"); p.innerHTML = \"<b>Hello</b>\";`. Kết quả hiển thị trên trình duyệt là gì?","options":["Chữ Hello in đậm","Chữ Hello bình thường","Chuỗi ký tự \"<b>Hello</b>\"","Lỗi cú pháp"],"correct":[0],"explanation":"Slide 57: innerHTML sẽ biên dịch các thẻ HTML bên trong chuỗi. Do đó <b>Hello</b> sẽ hiển thị chữ Hello in đậm.","source":"bo1"},{"id":"c10-q25","chapter":10,"difficulty":3,"type":"single","question":"Khi muốn thêm một dòng (tr) mới vào bảng (table) bằng DOM, ta cần thực hiện thao tác nào trước tiên?","options":["Tạo thẻ tr bằng document.createElement(\"tr\")","Gọi hàm document.appendChild(\"tr\")","Gán giá trị innerHTML cho bảng","Không cần làm gì, trình duyệt tự thêm"],"correct":[0],"explanation":"Slide 60: Bước 1 là tạo element bằng createElement(\"tr\"), sau đó tạo các td con, nối td vào tr, cuối cùng nối tr vào tbody.","source":"bo1"},{"id":"c10-q26","chapter":10,"difficulty":3,"type":"single","question":"Trong đoạn mã xóa dòng của bảng: `tbody.removeChild(this.parentElement.parentElement);`. Đối tượng `this` ở đây đại diện cho gì?","options":["Thẻ <tr>","Thẻ <td>","Thẻ <tbody>","Thẻ <img> (icon xóa) đang được click"],"correct":[3],"explanation":"Slide 61: `this` là thẻ img đang được click. `this.parentElement` là thẻ td, `.parentElement` của td là thẻ tr. Vậy ta đang xóa thẻ tr khỏi tbody.","source":"bo1"},{"id":"c10-q27","chapter":10,"difficulty":2,"type":"single","question":"Để lấy danh sách tất cả các thẻ `<p>` trong một trang HTML, ta sử dụng lệnh nào?","options":["document.getElementById(\"p\")","document.querySelectorAll(\"#p\")","document.getElementsByTagName(\"p\")","document.getElementsByClassName(\"p\")"],"correct":[2],"explanation":"Slide 57: getElementsByTagName(\"tag_name\") tìm tất cả các element theo tên thẻ.","source":"bo1"},{"id":"c10-q28","chapter":10,"difficulty":3,"type":"single","question":"Trong kỹ thuật AJAX, nếu `xhr.status == 404`, điều này có nghĩa là gì?","options":["Kết nối bị từ chối","Không tìm thấy trang hoặc file yêu cầu (Page not found)","Yêu cầu đã thành công","Server gặp lỗi nội bộ"],"correct":[1],"explanation":"Slide 65: status 200: \"OK\", 404: \"Page not found\".","source":"bo1"},{"id":"c10-q29","chapter":10,"difficulty":3,"type":"single","question":"Which method is used to send an AJAX request to the server?","options":["xhr.send()","xhr.get()","xhr.open()","xhr.request()"],"correct":[0],"explanation":"Slide 65: Sau khi gọi open(), phải gọi send() để gửi request. Nếu là POST, có thể truyền dữ liệu vào send(string).","source":"bo1"},{"id":"c10-q30","chapter":10,"difficulty":2,"type":"single","question":"Trong mô hình DOM, nút lá (leaf node) là gì?","options":["Là nút gốc của cây","Là nút có nhiều con nhất","Là nút không có nút con nào","Là nút chứa thuộc tính"],"correct":[2],"explanation":"Slide 56: Nút lá không có nút con.","source":"bo1"},{"id":"c10-q31","chapter":10,"difficulty":2,"type":"single","question":"Phương thức `document.write(text)` trong DOM có tác dụng gì?","options":["Xóa toàn bộ nội dung trang web","Tạo một file text mới","Ghi dữ liệu vào cơ sở dữ liệu","Xuất dữ liệu text ra trình duyệt"],"correct":[3],"explanation":"Slide 57: document.write(text) dùng để xuất dữ liệu ra trình duyệt.","source":"bo1"},{"id":"c10-q32","chapter":10,"difficulty":3,"type":"single","question":"Cho đoạn mã: `var xhr = new XMLHttpRequest(); xhr.open(\"GET\", \"data.xml\", false);`. Tham số `false` có ý nghĩa gì?","options":["Đóng kết nối ngay lập tức","Không gửi yêu cầu đi","Yêu cầu được xử lý bất đồng bộ (Asynchronous)","Yêu cầu được xử lý đồng bộ (Synchronous)"],"correct":[3],"explanation":"Slide 65: Tham số async: true (asynchronous - bất đồng bộ) hoặc false (synchronous - đồng bộ).","source":"bo1"},{"id":"c10-q33","chapter":10,"difficulty":2,"type":"single","question":"Để lấy toàn bộ nội dung văn bản bên trong một thẻ HTML (bỏ qua các thẻ HTML con), ta dùng thuộc tính nào?","options":["innerHTML","innerText","textContent","outerText"],"correct":[1],"explanation":"Slide 57: innerText chỉ lấy phần text hiển thị, không lấy các thẻ HTML bên trong. (innerHTML lấy cả thẻ HTML).","source":"bo1"},{"id":"c10-q34","chapter":10,"difficulty":2,"type":"single","question":"Trong XML, thẻ gốc (root element) có đặc điểm gì?","options":["Có thể có nhiều thẻ gốc trong một file XML","Là thẻ duy nhất bao bọc toàn bộ các thẻ khác trong tài liệu XML","Là thẻ nằm ở cuối tài liệu","Không được phép chứa thuộc tính"],"correct":[1],"explanation":"Slide 62: XML document phải có duy nhất một thẻ root.","source":"bo1"},{"id":"c10-q35","chapter":10,"difficulty":3,"type":"single","question":"Để thêm một thẻ `<td>` vào thẻ `<tr>` trong mô hình DOM, ta thực hiện như thế nào?","options":["Tạo thẻ td bằng createElement(\"td\"), sau đó gọi tr.appendChild(td)","Gán td.innerHTML = tr","Tạo thẻ td bằng createElement(\"td\"), sau đó gọi td.appendChild(tr)","Tạo thẻ tr bằng createElement(\"tr\"), sau đó gọi tr.appendChild(td)"],"correct":[0],"explanation":"Slide 60: Mối quan hệ cha-con trong DOM: tr là cha, td là con. Do đó phải gọi tr.appendChild(td).","source":"bo1"},{"id":"c10-q36","chapter":10,"difficulty":2,"type":"single","question":"Which of the following is true about XML tags?","options":["XML tags are not case-sensitive","XML tags are case-sensitive","XML tags must be written in uppercase","XML tags must be written in lowercase"],"correct":[1],"explanation":"Slide 62: Tên thẻ trong XML phân biệt chữ hoa và chữ thường (case-sensitive).","source":"bo1"},{"id":"c10-q37","chapter":10,"difficulty":3,"type":"single","question":"Khi dùng AJAX, nếu ta dùng `xhr.responseText` thay vì `xhr.responseXML`, kết quả nhận được sẽ là gì?","options":["Một chuỗi văn bản chứa toàn bộ nội dung file XML","Một đối tượng JSON","Một mảng các phần tử","Một đối tượng XML Document"],"correct":[0],"explanation":"Slide 65: responseText trả về dữ liệu dạng chuỗi (string). Muốn xử lý như XML thì phải dùng responseXML hoặc dùng DOMParser để parse chuỗi đó.","source":"bo1"},{"id":"c10-q38","chapter":10,"difficulty":3,"type":"single","question":"Trong biểu thức `xhr.onreadystatechange = function() { ... }`, hàm được gán sẽ được gọi khi nào?","options":["Mỗi khi thuộc tính readyState thay đổi giá trị","Chỉ khi readyState == 4","Ngay khi hàm open() được gọi","Chỉ khi status == 200"],"correct":[0],"explanation":"Slide 65: onreadystatechange lưu một hàm sẽ được gọi tự động mỗi khi thuộc tính readyState thay đổi (từ 0 đến 4).","source":"bo1"},{"id":"c11-q1","chapter":11,"difficulty":1,"type":"single","question":"JSON là viết tắt của cụm từ nào?","options":["Java Standard Object Notation","JavaScript Object Notation","JavaScript Oriented Notation","Java Syntax Object Notation"],"correct":[1],"explanation":"Slide 67: JSON (JavaScript Object Notation).","source":"bo1"},{"id":"c11-q2","chapter":11,"difficulty":2,"type":"single","question":"JSON được xây dựng dựa trên hai cấu trúc chính nào?","options":["Hàm (Function) và Biến (Variable)","Bảng (Table) và Cột (Column)","Tập hợp cặp name/value (Object) và Tập hợp danh sách các giá trị (Array)","Tập hợp các thẻ (Tags) và Thuộc tính (Attributes)"],"correct":[2],"explanation":"Slide 67: JSON dựa trên 2 cấu trúc: Tập hợp cặp name/value (Object) và Tập hợp danh sách các giá trị (Array).","source":"bo1"},{"id":"c11-q3","chapter":11,"difficulty":2,"type":"single","question":"Tiêu chuẩn của JSON được định nghĩa dựa trên ngôn ngữ JavaScript vào năm nào?","options":["1995","2000","1999","2010"],"correct":[2],"explanation":"Slide 67: JSON được định nghĩa theo ngôn ngữ JavaScript, tiêu chuẩn ECMA-262 năm 1999.","source":"bo1"},{"id":"c11-q4","chapter":11,"difficulty":2,"type":"single","question":"So sánh cơ bản giữa HTML và JSON?","options":["Cả hai đều là ngôn ngữ đánh dấu (Markup Language)","Cả hai đều dùng để hiển thị giao diện","HTML dùng để lưu trữ, JSON dùng để hiển thị","HTML dùng để hiển thị dữ liệu, JSON dùng để lưu trữ và trao đổi dữ liệu"],"correct":[3],"explanation":"Slide 67: HTML hiển thị dữ liệu. JSON dùng để lưu trữ và trao đổi dữ liệu. (Lưu ý: JSON không phải là Markup Language như XML).","source":"bo1"},{"id":"c11-q5","chapter":11,"difficulty":1,"type":"single","question":"Cặp dấu ngoặc nào được sử dụng để bao bọc một đối tượng JSON Object?","options":["< >","{ }","[ ]","( )"],"correct":[1],"explanation":"Slide 67: JSON Object được bao trong cặp “{}”. JSON Array được bao trong cặp “[]”.","source":"bo1"},{"id":"c11-q6","chapter":11,"difficulty":2,"type":"single","question":"Trong JSON Object, các cặp name/value được phân tách với nhau bằng dấu gì?","options":["Dấu chấm (.)","Dấu phẩy (,)","Dấu hai chấm (:)","Dấu chấm phẩy (;)"],"correct":[1],"explanation":"Slide 67: Các cặp name/value được chia cách nhau bởi dấu phẩy (,). (Lưu ý: Slide gốc của thầy có lỗi gõ nhầm thành dấu ';', nhưng mã ví dụ ở slide 8 thầy dùng dấu ',').","source":"bo1"},{"id":"c11-q7","chapter":11,"difficulty":2,"type":"single","question":"Trong JSON Object, name (tên thuộc tính) BẮT BUỘC phải được đặt trong dấu gì?","options":["Dấu ngoặc vuông ([ ])","Không cần dấu nháy","Dấu nháy đơn (' ')","Dấu nháy kép (\" \")"],"correct":[3],"explanation":"Slide 67: Cú pháp là \"string\": value. Do đó tên thuộc tính phải là chuỗi và đặt trong nháy kép.","source":"bo1"},{"id":"c11-q8","chapter":11,"difficulty":2,"type":"single","question":"Which data type is NOT supported as a value in a JSON object?","options":["Boolean","Function","String","Null"],"correct":[1],"explanation":"Slide 67: Value trong JSON có thể là chuỗi, số, true-false, null, object hoặc array. JSON không hỗ trợ function (hàm).","source":"bo1"},{"id":"c11-q9","chapter":11,"difficulty":1,"type":"single","question":"Cặp dấu ngoặc nào được sử dụng để bao bọc một mảng JSON Array?","options":["{ }","( )","[ ]","< >"],"correct":[2],"explanation":"Slide 67: JSON Array được bao trong cặp “[]”.","source":"bo1"},{"id":"c11-q10","chapter":11,"difficulty":2,"type":"single","question":"Đặc điểm của các phần tử trong một JSON Array là gì?","options":["Có thứ tự (Ordered)","Bắt buộc phải là chuỗi","Không có thứ tự (Unordered)","Bắt buộc phải là số"],"correct":[0],"explanation":"Slide 67: JSON Array là tập hợp danh sách các giá trị có thứ tự (ordered list).","source":"bo1"},{"id":"c11-q11","chapter":11,"difficulty":2,"type":"single","question":"Trong một JSON Array, các phần tử con có thể là loại dữ liệu nào?","options":["Tất cả các loại: số, chuỗi, true/false, null, object, thậm chí là một mảng khác","Chỉ được là số","Chỉ được là chuỗi","Chỉ được là object"],"correct":[0],"explanation":"Slide 67: Mỗi phần tử con có thể là một giá trị đơn lẻ như: số, chuỗi, true-false, null hoặc một object khác, thậm chí có thể là một mảng.","source":"bo1"},{"id":"c11-q12","chapter":11,"difficulty":2,"type":"single","question":"Cho đối tượng JSON sau: `var user = {\"first_name\": \"Duy Thanh\", \"last_name\": \"Trần\"};`. Lệnh nào dùng để lấy giá trị \"Duy Thanh\"?","options":["user.first_name","user[first_name]","user(first_name)","user->first_name"],"correct":[0],"explanation":"Slide 67: Để truy xuất thuộc tính của JSON Object, ta dùng dấu chấm: objectName.propertyName. Ví dụ: user.first_name.","source":"bo1"},{"id":"c11-q13","chapter":11,"difficulty":3,"type":"single","question":"Cho mảng JSON sau: `var arr = [10, 20, 30, 40];`. Lệnh `arr[2]` trả về giá trị bao nhiêu?","options":["10","20","30","40"],"correct":[2],"explanation":"Slide 67: Mảng trong JSON (và JavaScript) đánh số thứ tự từ 0. arr[0]=10, arr[1]=20, arr[2]=30.","source":"bo1"},{"id":"c11-q14","chapter":11,"difficulty":3,"type":"single","question":"Cho cấu trúc JSON lồng nhau:\n`var data = { \"Sanphams\": [ {\"MaSP\": \"sp_1\", \"TenSP\": \"DELL\"}, {\"MaSP\": \"sp_2\", \"TenSP\": \"HP\"} ] };`\nLệnh nào sau đây lấy được tên sản phẩm \"HP\"?","options":["data.Sanphams.TenSP[1]","data[1].Sanphams.TenSP","data.Sanphams[0].TenSP","data.Sanphams[1].TenSP"],"correct":[3],"explanation":"Slide 67: data.Sanphams là mảng. Phần tử thứ 2 là data.Sanphams[1]. Thuộc tính TenSP của nó là data.Sanphams[1].TenSP.","source":"bo1"},{"id":"c11-q15","chapter":11,"difficulty":2,"type":"single","question":"Trong JavaScript, hàm nào dùng để chuyển đổi một chuỗi định dạng JSON thành đối tượng (Object)?","options":["JSON.parse()","JSON.stringify()","JSON.toObject()","JSON.convert()"],"correct":[0],"explanation":"Kiến thức mở rộng (thường đi kèm với JSON trong thực tế): JSON.parse() dùng để parse chuỗi thành object. JSON.stringify() dùng để chuyển object thành chuỗi JSON.","source":"bo1"},{"id":"c11-q16","chapter":11,"difficulty":2,"type":"single","question":"Khi muốn gửi một đối tượng JavaScript lên server dưới dạng chuỗi JSON, ta dùng hàm nào?","options":["JSON.stringify()","JSON.parse()","JSON.toString()","JSON.encode()"],"correct":[0],"explanation":"Kiến thức mở rộng: JSON.stringify() chuyển đối tượng thành chuỗi JSON.","source":"bo1"},{"id":"c11-q17","chapter":11,"difficulty":2,"type":"multiple","question":"Đâu là những giá trị HỢP LỆ (valid) của một thuộc tính trong JSON? (chọn nhiều đáp án)","options":["Số (Number)","Chuỗi (String)","Mảng (Array)","Hàm (Function)"],"correct":[0,1,2],"explanation":"Slide 67: JSON hỗ trợ chuỗi, số, true/false, null, object, array. Không hỗ trợ hàm (function) hay undefined.","source":"bo1"},{"id":"c11-q18","chapter":11,"difficulty":3,"type":"single","question":"Đoạn mã sau có lỗi không?\n`var sv = { 'name': 'Tèo', 'age': 20 };`","options":["Có lỗi vì tuổi phải là chuỗi","Có lỗi vì tên thuộc tính (name, age) phải được đặt trong nháy kép (\" \")","Có lỗi vì thiếu dấu chấm phẩy ở cuối","Không lỗi, nháy đơn hay nháy kép đều được"],"correct":[1],"explanation":"Slide 67: Trong JSON chuẩn, tên thuộc tính (key) BẮT BUỘC phải đặt trong nháy kép. Tuy nhiên, trong JavaScript object thuần, nháy đơn vẫn hợp lệ. Nhưng nếu xét theo chuẩn JSON, đây là lỗi.","source":"bo1"},{"id":"c11-q19","chapter":11,"difficulty":1,"type":"single","question":"JSON có phụ thuộc vào ngôn ngữ lập trình không?","options":["JSON chỉ là một phần của HTML","Có, JSON chỉ chạy được trong JavaScript","Có, JSON chỉ chạy được trong Java","Không, JSON là định dạng văn bản độc lập ngôn ngữ (tương thích C, C++, C#, Java, JS, Python...)"],"correct":[3],"explanation":"Slide 67: JSON tương thích với hầu hết các ngôn ngữ C, C++, C#, Java, JavaScript, Perl, Python...","source":"bo1"},{"id":"c11-q20","chapter":11,"difficulty":3,"type":"single","question":"Cho đoạn mã:\n`var user = { \"id\": \"1001\", \"info\": { \"age\": 20, \"gender\": \"male\" } };`\nLàm thế nào để lấy được giá trị \"male\"?","options":["user.info.gender","user[1].gender","user.info[1]","user.gender"],"correct":[0],"explanation":"Slide 67: Truy xuất thuộc tính lồng nhau bằng cách nối tiếp các dấu chấm: user.info.gender.","source":"bo1"},{"id":"c11-q21","chapter":11,"difficulty":3,"type":"single","question":"Khi duyệt qua một mảng JSON Array trong JavaScript, cấu trúc nào thường được sử dụng nhất?","options":["Câu lệnh switch","Câu lệnh if","Vòng lặp for","Hàm alert()"],"correct":[2],"explanation":"Slide 67: Để duyệt qua các phần tử của JSON Array (thường chứa các object), ta dùng vòng lặp for (hoặc forEach).","source":"bo1"},{"id":"c11-q22","chapter":11,"difficulty":2,"type":"single","question":"Which of the following is the correct syntax for a JSON array of strings?","options":["(\"Apple\", \"Banana\", \"Orange\")","{\"Apple\", \"Banana\", \"Orange\"}","<\"Apple\", \"Banana\", \"Orange\">","[\"Apple\", \"Banana\", \"Orange\"]"],"correct":[3],"explanation":"Slide 67: JSON Array được bao bởi [], các phần tử là chuỗi đặt trong nháy kép và phân tách bằng dấu phẩy.","source":"bo1"},{"id":"c11-q23","chapter":11,"difficulty":2,"type":"single","question":"Khẳng định nào sau đây là ĐÚNG về JSON?","options":["JSON là định dạng nhẹ hơn, dễ đọc và dễ phân tích cú pháp hơn XML","JSON chỉ hỗ trợ dữ liệu có cấu trúc dạng bảng","JSON không thể trao đổi dữ liệu qua mạng","JSON không thể lưu trữ dữ liệu phân cấp"],"correct":[0],"explanation":"Slide 67: JSON là định dạng văn bản đơn giản, nhẹ hơn và dễ parse hơn so với XML.","source":"bo1"},{"id":"c11-q24","chapter":11,"difficulty":3,"type":"single","question":"Cho mảng sau: `var dm = { \"Sanphams\": [ {\"MaSP\": \"sp_1\"}, {\"MaSP\": \"sp_2\"} ] };`. Thuộc tính `dm.Sanphams.length` trả về giá trị bao nhiêu?","options":["3","1","2","0"],"correct":[2],"explanation":"Slide 67: dm.Sanphams là một mảng có 2 phần tử object. Do đó length = 2.","source":"bo1"},{"id":"c11-q25","chapter":11,"difficulty":2,"type":"single","question":"Sự khác biệt cơ bản nhất giữa JSON Object và JSON Array là gì?","options":["Object dùng cặp [] và chứa danh sách, Array dùng cặp {} và chứa key/value","Object dùng cặp {} và chứa các cặp key/value, Array dùng cặp [] và chứa danh sách các giá trị có thứ tự","Cả hai đều dùng cặp {}","Cả hai đều dùng cặp []"],"correct":[1],"explanation":"Slide 67: Object dùng `{}`, chứa cặp name/value. Array dùng `[]`, chứa danh sách giá trị có thứ tự.","source":"bo1"},{"id":"qz-1-01","chapter":2,"difficulty":2,"type":"single","question":"[Quiz 1] Khi mua tên miền ta cần quan tâm tới những vấn đề nào?","options":["Tên ngắn; Gợi nhớ; Dễ đọc; Không gây nhầm lẫn; Thể hiện được tên công ty hoặc nhãn hiệu; Nên mua dạng \"bao vây\" tên miền để tránh bị nhái thương hiệu","Tên ngắn; Gợi nhớ; Dễ đọc; Không gây nhầm lẫn; Băng thông mạnh","Tên ngắn; Gợi nhớ; Dễ đọc; Thể hiện được tên công ty hoặc nhãn hiệu của công ty","Tên ngắn; Băng thông mạnh; Gợi nhớ; Dễ đọc; Không gây nhầm lẫn; Thể hiện được tên công ty"],"correct":[0],"explanation":"Băng thông là tiêu chí khi thuê hosting, không phải khi mua tên miền. Phương án đúng là phương án đầy đủ nhất, có cả ý mua \"bao vây\" tên miền.","source":"quiz"},{"id":"qz-1-02","chapter":1,"difficulty":1,"type":"single","question":"[Quiz 1] Nói tới localhost thường ta nói tới địa chỉ IP nào?","options":["1.0.0.127","127.0.0.1","127.0.0.10","127.1.1.0"],"correct":[1],"explanation":"localhost là địa chỉ loopback 127.0.0.1, trỏ về chính máy đang dùng.","source":"quiz"},{"id":"qz-1-03","chapter":1,"difficulty":1,"type":"single","question":"[Quiz 1] Ghép tên miền cấp 1 với ý nghĩa: .com: A, .edu: B, .net: C, .int: D, .org: E","options":["A: công ty thương mại; B: trường học, tổ chức giáo dục; C: các mạng (network); D: tổ chức quốc tế; E: các tổ chức khác","A: các mạng; B: trường học; C: công ty thương mại; D: tổ chức quốc tế; E: các tổ chức khác","A: tổ chức quốc tế; B: trường học; C: các mạng; D: công ty thương mại; E: các tổ chức khác","A: trường học; B: các mạng; C: công ty thương mại; D: các tổ chức khác; E: tổ chức quốc tế"],"correct":[0],"explanation":".com = commercial, .edu = education, .net = network, .int = international organizations, .org = other organizations.","source":"quiz"},{"id":"qz-1-04","chapter":1,"difficulty":1,"type":"single","question":"[Quiz 1] WWW là gì?","options":["WWW là viết tắt của Word Wid Wed: là tập hợp các web site trên mạng internet","WWW là viết tắt của World Why Web: là tập hợp các web site trên mạng internet","WWW là viết tắt của Wall Wide Web: là tập hợp các web site trên mạng internet","WWW là viết tắt của World Wide Web: là tập hợp các web site trên mạng internet"],"correct":[3],"explanation":"Đề thầy hay đánh lừa bằng cách viết sai chính tả cụm từ viết tắt. Đáp án đúng: World Wide Web.","source":"quiz"},{"id":"qz-1-05","chapter":1,"difficulty":2,"type":"single","question":"[Quiz 1] Web server là gì?","options":["Web Server là máy phục vụ web. Thường các Website viết bằng ASP C# được cấu hình trên Apache Tomcat","Web Server là máy phục vụ truyền tải file. Thường các Website viết bằng ASP C# được cấu hình trên IIS","Web Server là máy phục vụ truyền tải file. Thường các Website viết bằng ASP C# được cấu hình trên Apache Tomcat","Web Server là máy phục vụ web. Thường các Website viết bằng ASP C# được cấu hình trên Internet Information Services (IIS)"],"correct":[3],"explanation":"Cần đúng cả 2 ý: Web Server là máy phục vụ web (máy truyền file là FTP Server), và ASP/C# chạy trên IIS của Microsoft (Apache Tomcat dành cho Java).","source":"quiz"},{"id":"qz-1-06","chapter":1,"difficulty":1,"type":"single","question":"[Quiz 1] Web Browser là gì?","options":["Là máy phục vụ web chạy trên máy chủ (server) dùng để hiển thị trang web","Phần mềm chạy trên máy chủ (server) dùng để hiển thị trang web và giúp khai thác dịch vụ web","Phần mềm chạy trên máy khách (client) dùng để hiển thị trang web và giúp khai thác dịch vụ web","Là máy phục vụ web chạy trên máy khách (client) dùng để hiển thị trang web"],"correct":[2],"explanation":"Browser là PHẦN MỀM, chạy ở phía CLIENT.","source":"quiz"},{"id":"qz-1-07","chapter":1,"difficulty":2,"type":"single","question":"[Quiz 1] Web tĩnh là gì?","options":["Tương tác với người duyệt web mạnh; Sử dụng nhiều ngôn ngữ để lập trình; Thường phải viết nhiều mã lệnh; Không nhận thông tin phản hồi từ người dùng","Tương tác với người duyệt web yếu; Sử dụng HTML để thiết kế; Dùng FrontPage, Notepad; Nhận thông tin phản hồi từ người dùng","Dễ phát triển; Tương tác với người duyệt web yếu; Sử dụng ngôn ngữ HTML để thiết kế; Thường dùng công cụ trực quan như FrontPage, Notepad; Không nhận thông tin phản hồi từ người dùng","Khó phát triển; Tương tác mạnh; Sử dụng nhiều ngôn ngữ lập trình; Viết nhiều mã lệnh; Nhận thông tin phản hồi từ người dùng"],"correct":[2],"explanation":"Web tĩnh: dễ làm, chỉ HTML, tương tác yếu, KHÔNG nhận phản hồi. Phương án D sai ở ý cuối.","source":"quiz"},{"id":"qz-1-08","chapter":1,"difficulty":2,"type":"single","question":"[Quiz 1] Máy chủ (Server) là:","options":["Máy tính chuyên cung cấp tài nguyên, dịch vụ cho máy tính khác; Thường cài phần mềm chuyên dụng; Cấu hình cao, hoạt động ổn định; Có thể dùng cho một hay nhiều mục đích","Máy tính chuyên cung cấp tài nguyên, dịch vụ cho máy khác và BẮT BUỘC phải kết nối internet; ...","Máy tính rất đắt tiền, cung cấp các dịch vụ cho các máy khác; Thường cài phần mềm chuyên dụng; Cấu hình cao; Dùng cho một hay nhiều mục đích","Máy tính chuyên cung cấp tài nguyên cho máy khác TRONG CÙNG MỘT CÔNG TY và các máy này phải có kết nối internet; ..."],"correct":[0],"explanation":"Định nghĩa máy chủ không dựa vào giá tiền, không bắt buộc kết nối internet (có thể chạy trong mạng LAN), và không giới hạn trong một công ty.","source":"quiz"},{"id":"qz-1-09","chapter":1,"difficulty":2,"type":"single","question":"[Quiz 1] Web động là gì?","options":["Khó phát triển; Tương tác với người duyệt web mạnh; Sử dụng nhiều ngôn ngữ khác nhau để lập trình; Thường phải viết nhiều mã lệnh; Nhận thông tin phản hồi từ người dùng","Dễ phát triển; Tương tác yếu; Sử dụng HTML; Dùng FrontPage, Notepad; Không nhận thông tin phản hồi","Khó phát triển; Tương tác với người duyệt web yếu; Sử dụng nhiều ngôn ngữ để lập trình; Viết nhiều mã lệnh; Nhận thông tin phản hồi","Khó phát triển; Tương tác mạnh; Sử dụng nhiều ngôn ngữ để lập trình; Viết nhiều mã lệnh; Không nhận thông tin phản hồi từ người dùng"],"correct":[0],"explanation":"Web động: khó làm, tương tác MẠNH, nhiều ngôn ngữ, NHẬN phản hồi từ người dùng. Cần đúng cả 5 ý.","source":"quiz"},{"id":"qz-1-10","chapter":1,"difficulty":2,"type":"single","question":"[Quiz 1] Chọn định nghĩa đúng về HTTP","options":["HTTP (HyperText Transfer Protocol – Giao thức truyền tải siêu văn bản): chuyển nội dung một trang web vào trình duyệt cho người truy cập xem","HTTP (HyperText Transfer Procedure – Giao thức truyền tải siêu văn bản): chuyển nội dung một trang web vào trình duyệt","HTTP (HighText Transfer Protocol – Giao thức truyền văn bản trên mạng): chuyển nội dung một trang web vào trình duyệt","HTTP (HyperText Transfer Protocol – Giao thức truyền tải siêu văn bản): chuyển nội dung một text file vào trình duyệt"],"correct":[0],"explanation":"Chú ý từng chữ: HyperText (không phải HighText), Protocol (không phải Procedure), và chuyển nội dung TRANG WEB (không phải text file).","source":"quiz"},{"id":"qz-1-11","chapter":1,"difficulty":2,"type":"single","question":"[Quiz 1] Chọn định nghĩa đúng về HTTPS","options":["HTTPS (Hypertext Transfer Protocol Secure): kết hợp giữa HTTP và giao thức bảo mật SSL hay TLS, dùng trong các giao dịch nhạy cảm","HTTPS (Hypertext Transfer Procedure Secure): kết hợp giữa HTTP và giao thức bảo mật SSL hay TLS","HTTPS (Hypertext Transmission Protocol Secure): kết hợp giữa HTTP và giao thức bảo mật SSL hay TLS","HTTPS (Hypertext Transfer Procedure Security): kết hợp giữa HTTP và giao thức bảo mật SSL hay TLS"],"correct":[0],"explanation":"Tên đầy đủ: Hypertext Transfer Protocol Secure.","source":"quiz"},{"id":"qz-1-12","chapter":2,"difficulty":1,"type":"single","question":"[Quiz 1] Khi thiết kế website không nên có trang \"dead-end\". Ý nghĩa của trang \"dead-end\" là gì?","options":["Trang quảng cáo","Trang thông báo lỗi","Trang chủ của website","Trang không có khả năng đi đến các trang khác"],"correct":[3],"explanation":"Dead-end (trang cụt) là trang không có liên kết đi tiếp, người dùng phải bấm Back của trình duyệt.","source":"quiz"},{"id":"qz-1-13","chapter":2,"difficulty":2,"type":"single","question":"[Quiz 1] Khi thuê hosting ta cần quan tâm tới vấn đề gì?","options":["Hệ điều hành; Dung lượng; Băng thông; Ngôn ngữ hỗ trợ; Hệ quản trị CSDL hỗ trợ; Internet cáp quang","Dễ nhớ tên miền; Dung lượng không giới hạn; Băng thông; Ngôn ngữ hỗ trợ; Hệ quản trị CSDL hỗ trợ; Email POP3","Hệ điều hành; Dung lượng; Băng thông; Ngôn ngữ hỗ trợ; Hệ quản trị CSDL hỗ trợ; Email POP3","Hệ điều hành; Dung lượng; Băng thông; Ngôn ngữ lập trình hỗ trợ; Email POP3"],"correct":[2],"explanation":"Dễ nhớ là tiêu chí của tên miền; Internet cáp quang là đường truyền của mình chứ không phải tiêu chí hosting; phương án D thiếu Hệ quản trị CSDL.","source":"quiz"},{"id":"qz-1-14","chapter":2,"difficulty":1,"type":"single","question":"[Quiz 1] Nếu cơ sở dữ liệu là SQL Server thì nên mua Hosting loại nào?","options":["Linux hosting","Windows hosting","Loại nào cũng được","MAC hosting"],"correct":[1],"explanation":"SQL Server (và ASP.NET) là sản phẩm của Microsoft nên chạy trên Windows hosting.","source":"quiz"},{"id":"qz-1-15","chapter":2,"difficulty":2,"type":"single","question":"[Quiz 1] Sitemap là gì?","options":["Dùng để tổ chức các khối thông tin phức hợp; Là hệ thống dễ dàng di chuyển qua Website khác; Gần với mô hình thế giới thực; Dễ hình dung tổ chức website","Dùng để tổ chức các khối thông tin bất kỳ; Là hệ thống thông dụng nhất; Gần với mô hình thế giới thực; Dễ di chuyển qua trang web khác","Dùng để tổ chức các khối thông tin phức hợp; Là hệ thống được dùng thông dụng nhất; Dễ hình dung tổ chức website; Dễ di chuyển qua website khác","Dùng để tổ chức các khối thông tin phức hợp; Là hệ thống được dùng thông dụng nhất; Gần với mô hình tổ chức thế giới thực; Dễ hình dung tổ chức website"],"correct":[3],"explanation":"Sitemap (cấu trúc phân cấp) tổ chức thông tin phức hợp, thông dụng nhất, gần thế giới thực, dễ hình dung. Ý \"di chuyển qua website khác\" là bẫy.","source":"quiz"},{"id":"qz-2-01","chapter":3,"difficulty":1,"type":"single","question":"[Quiz 2] HTML là:","options":["HTML viết tắt từ HyperText Machine Language, còn gọi là ngôn ngữ đánh dấu siêu văn bản","HTML viết tắt từ Hyper Transfer Markup Language, còn gọi là ngôn ngữ đánh dấu siêu văn bản","HTML viết tắt từ HyperText Make up Language, còn gọi là ngôn ngữ đánh dấu siêu văn bản","HTML viết tắt từ HyperText Markup Language, còn gọi là ngôn ngữ đánh dấu siêu văn bản, ngôn ngữ cơ bản nhất để xây dựng các trang web"],"correct":[3],"explanation":"HyperText Markup Language.","source":"quiz"},{"id":"qz-2-02","chapter":3,"difficulty":3,"type":"single","question":"[Quiz 2] Để tạo mục lục: A. HTML (1. Thẻ là gì, 2. Cách dùng ul và ol, 3. Cách cấu hình UTF-8), B. CSS (4. Inline css, 5. Internal css, 6. External css), C. Javascript (7. Tham chiếu javascript, 8. Tạo hàm, 9. Xử lý sự kiện). Số thứ tự 1 đến 9 chạy LIÊN TỤC qua các nhóm. Ta làm như thế nào?","options":["\n```\n<ul type=A>\n<li>HTML</li>\n  <ul type=1> ...3 mục... </ul>\n<li>CSS</li>\n  <ul type=1 start=\"4\"> ...3 mục... </ul>\n<li>Javascript</li>\n  <ul type=1 start=\"7\"> ...3 mục... </ul>\n</ul>\n```","\n```\n<ol type=A>\n<li>HTML</li>\n  <ol type=1 position=\"1\"> ...3 mục... </ol>\n<li>CSS</li>\n  <ol type=1 position=\"4\"> ...3 mục... </ol>\n<li>Javascript</li>\n  <ol type=1 position=\"7\"> ...3 mục... </ol>\n</ol>\n```","\n```\n<ol type=A>\n<li>HTML</li>\n  <ol type=1> ...3 mục... </ol>\n<li>CSS</li>\n  <ol type=1 start=\"4\"> ...3 mục... </ol>\n<li>Javascript</li>\n  <ol type=1 start=\"7\"> ...3 mục... </ol>\n</ol>\n```","\n```\n<ol type=A>\n<li>HTML</li>\n  <ol type=1> ...3 mục... </ol>\n<li>CSS</li>\n  <ol type=1> ...3 mục... </ol>\n<li>Javascript</li>\n  <ol type=1> ...3 mục... </ol>\n</ol>\n```"],"correct":[2],"explanation":"Muốn đánh số tiếp tục từ 4, 7 phải dùng thuộc tính start của <ol>. Không có thuộc tính position; <ul> không đánh số.","source":"quiz"},{"id":"qz-2-03","chapter":3,"difficulty":1,"type":"single","question":"[Quiz 2] Để tạo mục lục có dấu chấm tròn đặc (disc) trước Chương 1, Chương 2, Chương 3, cấu trúc HTML nào đúng?","options":["\n```\n<ul type=disc>\n<li>Chương 1</li>\n<li>Chương 2</li>\n<li>Chương 3</li>\n</ul>\n```","\n```\n<ul type=circle>\n<li>Chương 1</li>\n<li>Chương 2</li>\n<li>Chương 3</li>\n</ul>\n```","\n```\n<ol type=disc>\n<li>Chương 1</li>\n<li>Chương 2</li>\n<li>Chương 3</li>\n</ol>\n```","\n```\n<ul type=square>\n<li>Chương 1</li>\n<li>Chương 2</li>\n<li>Chương 3</li>\n</ul>\n```"],"correct":[0],"explanation":"Ký hiệu dạng nút là danh sách không thứ tự <ul>. disc = chấm tròn đặc, circle = tròn rỗng, square = vuông. <ol> không có type=disc.","source":"quiz"},{"id":"qz-2-04","chapter":3,"difficulty":1,"type":"single","question":"[Quiz 2] Phần mở rộng của một file web tĩnh thường là:","options":["Chỉ .html",".html và .xml",".html và .htm",".htm và .xml"],"correct":[2],"explanation":"Trang web tĩnh lưu với đuôi .html hoặc .htm. File .xml dùng để lưu trữ dữ liệu.","source":"quiz"},{"id":"qz-2-05","chapter":3,"difficulty":2,"type":"single","question":"[Quiz 2] Tạo danh sách đề mục có diễn giải: \"Cà phê:\" (gồm Cà phê đen đá, Cà phê sữa đá...) và \"Trà sữa:\" (gồm Trà sữa thường...). Cấu trúc nào đúng?","options":["\n```\n<dt>\n  <dt><b>Cà phê:</b></dt>\n    <dl>-Cà phê đen đá</dl>\n    <dl>-Cà phê sữa đá</dl>\n  <dt><b>Trà sữa:</b></dt>\n    <dl>-Trà sữa thường</dl>\n</dt>\n```","\n```\n<dt>\n  <dl><b>Cà phê:</b></dl>\n    <dd>-Cà phê đen đá</dd>\n    <dd>-Cà phê sữa đá</dd>\n  <dl><b>Trà sữa:</b></dl>\n    <dd>-Trà sữa thường</dd>\n</dt>\n```","\n```\n<dl>\n  <dt><b>Cà phê:</b></dt>\n    <dd>-Cà phê đen đá</dd>\n    <dd>-Cà phê sữa đá</dd>\n  <dt><b>Trà sữa:</b></dt>\n    <dd>-Trà sữa thường</dd>\n</dl>\n```","\n```\n<dl>\n  <dt><b>Cà phê:</b></dt>\n    <li>-Cà phê đen đá</li>\n    <li>-Cà phê sữa đá</li>\n  <dt><b>Trà sữa:</b></dt>\n    <li>-Trà sữa thường</li>\n</dl>\n```"],"correct":[2],"explanation":"<dl> bao ngoài, <dt> là thuật ngữ/đề mục, <dd> là phần diễn giải. <li> chỉ dùng trong <ol>/<ul>.","source":"quiz"},{"id":"qz-2-06","chapter":3,"difficulty":1,"type":"single","question":"[Quiz 2] Để tạo một liên kết, khi click vào thì mở website của Khoa HTTT http://is.uel.edu.vn, ta làm như thế nào?","options":["<link href=\"http://is.uel.edu.vn\">Khoa Hệ Thống Thông Tin</link>","<a link=\"http://is.uel.edu.vn\">Khoa Hệ Thống Thông Tin</a>","<a src=\"http://is.uel.edu.vn\">Khoa Hệ Thống Thông Tin</a>","<a href=\"http://is.uel.edu.vn\">Khoa Hệ Thống Thông Tin</a>"],"correct":[3],"explanation":"Thẻ <a> dùng thuộc tính href. src là của <img>/<script>; <link> dùng để nhúng CSS.","source":"quiz"},{"id":"qz-2-07","chapter":3,"difficulty":1,"type":"single","question":"[Quiz 2] Từ trang home.html tạo liên kết mở trang gioithieu.html ở MỘT CỬA SỔ MỚI:","options":["<a link=\"gioithieu.html\" target=\"_blank\">Giới thiệu</a>","<a link=\"gioithieu.html\" target=\"_self\">Giới thiệu</a>","<a href=\"gioithieu.html\" target=\"_blank\">Giới thiệu</a>","<a href=\"gioithieu.html\" target=\"_self\">Giới thiệu</a>"],"correct":[2],"explanation":"_blank mở cửa sổ/tab mới; _self mở thay thế trang hiện tại.","source":"quiz"},{"id":"qz-2-08","chapter":3,"difficulty":1,"type":"single","question":"[Quiz 2] Từ trang home.html tạo liên kết mở trang gioithieu.html THAY THẾ trang home.html:","options":["<a src=\"gioithieu.html\" target=\"_self\">Giới thiệu</a>","<a href=\"gioithieu.html\" target=\"_blank\">Giới thiệu</a>","<a href=\"gioithieu.html\" target=\"_self\">Giới thiệu</a>","<a src=\"gioithieu.html\" target=\"_blank\">Giới thiệu</a>"],"correct":[2],"explanation":"target=\"_self\" (mặc định) mở trang mới ngay trong cửa sổ hiện hành.","source":"quiz"},{"id":"qz-2-09","chapter":3,"difficulty":2,"type":"single","question":"[Quiz 2] Thẻ a có thể:","options":["Liên kết tới trang hiện hành; Liên kết với nhiều file Json; Liên kết đến website; Liên kết nhiều file XML","Liên kết tới một phần khác trong cùng trang; Liên kết với một hoặc nhiều tập tin CSS; Liên kết đến website; Liên kết đến một hoặc nhiều mã lệnh javascript","Liên kết tới cơ sở dữ liệu; Liên kết với một phần trong trang khác; Liên kết đến website; Liên kết đến API Restful","Liên kết tới một phần khác trong cùng trang; Liên kết tới một phần nằm trong trang khác; Liên kết đến địa chỉ website hay trang cụ thể; Liên kết đến địa chỉ Email"],"correct":[3],"explanation":"4 cấp độ của thẻ a: bookmark trong cùng trang, bookmark trang khác, website/trang web, và mailto: email. Nhúng CSS dùng <link>, nhúng JS dùng <script>.","source":"quiz"},{"id":"qz-2-10","chapter":3,"difficulty":1,"type":"single","question":"[Quiz 2] Chỉ dẫn DOCTYPE trong một tài liệu HTML là gì?","options":["Cho biết phiên bản của trình duyệt. Với trình duyệt thế hệ thứ 5 khai báo là <!DOCTYPE html>","Cho biết phiên bản của Web Server. Với Server thế hệ thứ 5 khai báo là <!DOCTYPE html>","Cho biết phiên bản HTML. Với HTML5, phần này được khai báo đơn giản là <!DOCTYPE html>","Cho biết phiên bản HTML. Với phiên bản Chrome 5 khai báo là <!DOCTYPE html>"],"correct":[2],"explanation":"DOCTYPE khai báo phiên bản HTML; HTML5 dùng <!DOCTYPE html>.","source":"quiz"},{"id":"qz-2-11","chapter":3,"difficulty":1,"type":"single","question":"[Quiz 2] Các thẻ .......... được đặt trong phần head, dùng để chứa thông tin về trang web như mô tả, từ khóa, tác giả... Giá trị trong các thẻ này không hiển thị trên trình duyệt.","options":["link","meta","script","info"],"correct":[1],"explanation":"<meta name=\"description\">, <meta name=\"keywords\">, <meta name=\"author\"> chứa thông tin mô tả trang.","source":"quiz"},{"id":"qz-2-12","chapter":3,"difficulty":1,"type":"single","question":"[Quiz 2] Để khai báo Web dùng Tiếng Việt có dấu ta dùng:","options":["<meta charset=\"UTF-8\">","<script charset=\"UTF-8\">","<unicode charset=\"UTF-8\">","<link charset=\"UTF-8\">"],"correct":[0],"explanation":"Bảng mã UTF-8 được khai báo bằng thẻ meta trong head.","source":"quiz"},{"id":"qz-2-13","chapter":3,"difficulty":2,"type":"single","question":"[Quiz 2] Khi nhấn liên kết trên điện thoại, trình duyệt mở chương trình gọi điện để người dùng thực hiện cuộc gọi. Mã nào đúng?","options":["<a href=\"tel:1234567890\">Gọi điện</a>","<a href=\"dial:1234567890\">Gọi điện</a>","<a href=\"call:1234567890\">Gọi điện</a>","<a href=\"phone:1234567890\">Gọi điện</a>"],"correct":[0],"explanation":"Giao thức tel: mở ứng dụng gọi điện, tương tự mailto: mở ứng dụng email.","source":"quiz"},{"id":"qz-2-14","chapter":4,"difficulty":3,"type":"single","question":"[Quiz 2] Cho mã HTML (thẻ tfoot được viết TRƯỚC tbody):\n```\n<table border=\"1\">\n  <thead><tr><th>Cột 1</th><th>Cột 2</th></tr></thead>\n  <tfoot><tr><td>Footer 1</td><td>Footer 2</td></tr></tfoot>\n  <tbody><tr><td>Nội dung 1</td><td>Nội dung 2</td></tr></tbody>\n</table>\n```\nKết quả hiển thị là gì?","options":["Sai vì các trình duyệt hiện nay không còn hỗ trợ tfoot, tbody","Bảng hiển thị theo thứ tự trong mã: tiêu đề, Footer, rồi Nội dung","Bảng hiển thị theo thứ tự: dòng tiêu đề, dòng Nội dung, dòng Footer ở cuối cùng","Sai HTML vì thẻ tfoot phải để bên dưới thẻ tbody, trình duyệt báo lỗi"],"correct":[2],"explanation":"Trình duyệt luôn vẽ thead ở trên, tfoot ở dưới cùng bất kể vị trí viết trong mã. HTML cũng không báo lỗi cú pháp.","source":"quiz"},{"id":"qz-2-15","chapter":3,"difficulty":1,"type":"single","question":"[Quiz 2] Cho cấu trúc: <p style=\"font-size: 30px\">Xin chào</p>. Phát biểu nào đúng?","options":["p là giá trị thiết lập khung dữ liệu; style là giá trị định trị; font-size: 30px là các biến truyền; Xin chào là nội dung bổ sung cho style","p là thuộc tính; style là thẻ; font-size: 30px là giá trị của thuộc tính style; Xin chào là nội dung trong thẻ p","p là thẻ định nghĩa đoạn văn; style là tên thuộc tính; font-size: 30px là giá trị của thuộc tính style; Xin chào là nội dung nằm trong thẻ p","p là thẻ đóng; style là tên thuộc tính; font-size: 30px là giá trị của thuộc tính style; Xin chào là nội dung trong thẻ p"],"correct":[2],"explanation":"Cấu trúc thẻ: <tên_thẻ tên_thuộc_tính=\"giá trị\">nội dung</tên_thẻ>.","source":"quiz"},{"id":"qz-2-16","chapter":3,"difficulty":2,"type":"single","question":"[Quiz 2] Trang product.html muốn mở trang productdetail.html và nhảy NGAY tới hạng mục 3 (HTML5). Làm thế nào?","options":["Ở trang 1: <a href=\"productdetail.html#detail3\">Hạng mục 3</a>. Ở trang 2: định nghĩa id cho hạng mục 3 là detail3","Ở trang 1: <a href=\"product.html#detail3\">Hạng mục 3</a>. Ở trang 2: định nghĩa name cho hạng mục 3 là detail3","Ở trang 1: <a href=\"detail3\">Hạng mục 3</a>. Ở trang 2: định nghĩa name cho hạng mục 3 là detail3","Ở trang 1: <a href=\"#detail3\">Hạng mục 3</a>. Ở trang 2: định nghĩa id cho hạng mục 3 là detail3"],"correct":[0],"explanation":"Bookmark sang trang khác: href=\"tên_trang.html#id\". HTML5 dùng id (không dùng name) để đánh dấu vị trí. href=\"#detail3\" chỉ nhảy trong cùng trang.","source":"quiz"},{"id":"qz-2-17","chapter":4,"difficulty":2,"type":"single","question":"[Quiz 2] Thẻ table có các thuộc tính:","options":["title: tiêu đề bảng; border; width, height; spacing: khoảng cách giữa 2 ô; padding: khoảng cách đến nội dung; bgcolor; background","width, height; align: left, right, center, justify; valign: top, middle, bottom; colspan: trộn cột; rowspan: trộn dòng; nowrap","caption: tiêu đề bảng; border: đường viền (0 là không viền); width, height; cellspacing: khoảng cách giữa 2 ô; cellpadding: khoảng cách từ viền ô đến nội dung; bgcolor: màu nền; background: ảnh nền","width, height; align: top, middle, bottom; valign: left, right, center, justify; colspan: trộn dòng; rowspan: trộn cột; nowrap"],"correct":[2],"explanation":"Đây là thuộc tính của <table>. Phương án D là thuộc tính của <td>/<th> (câu tiếp theo). Tên đúng là cellspacing/cellpadding chứ không phải spacing/padding.","source":"quiz"},{"id":"qz-2-18","chapter":4,"difficulty":2,"type":"single","question":"[Quiz 2] Thẻ td, th có các thuộc tính:","options":["width, height; align: top, middle, bottom; valign: left, right, center, justify; colspan: trộn dòng; rowspan: trộn cột; nowrap","title: tiêu đề; border; width, height; spacing; padding; textcolor; background","caption: tiêu đề; border; width, height; cellspacing; cellpadding; bgcolor; background","width, height; align: left, right, center, justify; valign: top, middle, bottom; colspan=\"n\": trộn cột; rowspan=\"n\": trộn dòng; nowrap: không tự xuống dòng"],"correct":[3],"explanation":"align là căn ngang (left/right/center/justify), valign là căn dọc (top/middle/bottom). colspan trộn CỘT, rowspan trộn DÒNG.","source":"quiz"},{"id":"qz-2-19","chapter":4,"difficulty":3,"type":"single","question":"[Quiz 2] Tạo bảng: dòng tiêu đề nền vàng gồm STT, Mã, Tên (mỗi ô cao 2 dòng) và Điểm (rộng 3 cột); dòng tiêu đề thứ 2 nền xanh lá gồm Toán, Lý, Hóa; dòng dữ liệu: 1, SV1, Tèo, 8, 9, 7. Mã nào đúng?","options":["\n```\n<table border=\"1\">\n<tr style=\"background-color:yellow\">\n  <th rowspan=\"2\">STT</th><th rowspan=\"2\">Mã</th>\n  <th rowspan=\"2\">Tên</th><th colspan=\"3\">Điểm</th>\n</tr>\n<tr bgColor=\"green\"><th>Toán</th><th>Lý</th><th>Hóa</th></tr>\n<tr><td>1</td><td>SV1</td><td>Tèo</td><td>8</td><td>9</td><td>7</td></tr>\n</table>\n```","\n```\n<table border=\"1\">\n<tr style=\"background-color:yellow\">\n  <th rowspan=\"2\">STT</th><th rowspan=\"2\">Mã</th>\n  <th rowspan=\"2\">Tên</th><th colspan=\"3\">Điểm</th>\n</tr>\n<tr bgColor=\"green\"><th>Toán</th><th>Lý</th><th>Hóa</th></tr>\n<tr><th>1</th><th>SV1</th><th>Tèo</th><th>8</th><th>9</th><th>7</th></tr>\n</table>\n```","\n```\n<table border=\"1\">\n<tr style=\"background-color:yellow\">\n  <th colspan=\"2\">STT</th><th colspan=\"2\">Mã</th>\n  <th colspan=\"2\">Tên</th><th colspan=\"3\">Điểm</th>\n</tr>\n<tr bgColor=\"green\"><th>Toán</th><th>Lý</th><th>Hóa</th></tr>\n<tr><td>1</td><td>SV1</td><td>Tèo</td><td>8</td><td>9</td><td>7</td></tr>\n</table>\n```","\n```\n<table border=\"1\">\n<tr style=\"background-color:yellow\">\n  <th rowspan=\"2\">STT</th><th rowspan=\"2\">Mã</th>\n  <th rowspan=\"2\">Tên</th><th colspan=\"3\">Điểm</th>\n</tr>\n<tr background-color=\"green\"><th>Toán</th><th>Lý</th><th>Hóa</th></tr>\n<tr><td>1</td><td>SV1</td><td>Tèo</td><td>8</td><td>9</td><td>7</td></tr>\n</table>\n```"],"correct":[0],"explanation":"STT, Mã, Tên cao 2 dòng nên dùng rowspan=\"2\"; Điểm rộng 3 cột nên colspan=\"3\". background-color không phải thuộc tính HTML (phải viết trong style hoặc dùng bgColor). Dữ liệu dùng <td>, không phải <th> (th làm chữ đậm, căn giữa).","source":"quiz"},{"id":"qz-2-22","chapter":3,"difficulty":1,"type":"single","question":"[Quiz 2] Thẻ p và thẻ br khác nhau như thế nào?","options":["Thẻ p: khai báo một đoạn văn bản, chèn một ký tự xuống dòng và một dòng trống. Thẻ br: tạo đoạn văn mới","Thẻ p: khai báo một đoạn văn bản, chèn một ký tự xuống dòng. Thẻ br: tạo dòng mới và một ký tự xuống dòng","Thẻ br: khai báo một đoạn văn bản, chèn ký tự xuống dòng và một dòng trống. Thẻ p: tạo dòng mới và một ký tự xuống dòng","Thẻ p: khai báo một đoạn văn bản, chèn một ký tự xuống dòng và một dòng trống. Thẻ br: tạo dòng mới và một ký tự xuống dòng"],"correct":[3],"explanation":"<p> tạo đoạn văn (xuống dòng + có khoảng trống trên dưới). <br> chỉ ngắt dòng, không tạo khoảng trống.","source":"quiz"},{"id":"qz-2-23","chapter":3,"difficulty":1,"type":"single","question":"[Quiz 2] Lệnh nào sau đây dùng để ghi chú trong HTML?","options":["/* ghi chú ở đây */","<!-- Ghi chú ở đây -->","<comment ghi chú ở đây />","//Ghi chú ở đây"],"correct":[1],"explanation":"HTML: <!-- -->. CSS: /* */. JavaScript: // hoặc /* */.","source":"quiz"},{"id":"qz-2-24","chapter":3,"difficulty":2,"type":"single","question":"[Quiz 2] Kết quả mong muốn: chữ \"Thông báo\" có nền đỏ CHỈ VỪA ĐÚNG chữ, xuống dòng là câu \"Hôm nay bạn cần chọn đáp án đúng\" có nền vàng KÉO DÀI HẾT chiều ngang. Mã nào đúng?","options":["\n```\n<div>\n  <span style=\"bgColor:red\">Thông báo</span>\n  <div style=\"bg-color:yellow\">Hôm nay bạn cần chọn đáp án đúng</div>\n</div>\n```","\n```\n<div>\n  <div style=\"background:red\">Thông báo</div>\n  <span style=\"background-color:yellow\">Hôm nay bạn cần chọn đáp án đúng</span>\n</div>\n```","\n```\n<div>\n  <span style=\"background:red\">Thông báo</span>\n  <div style=\"background-color:yellow\">Hôm nay bạn cần chọn đáp án đúng</div>\n</div>\n```","\n```\n<div>\n  <div style=\"background:red\">Thông báo</div>\n  <div style=\"background-color:yellow\">Hôm nay bạn cần chọn đáp án đúng</div>\n</div>\n```"],"correct":[2],"explanation":"<span> là inline (nền chỉ bao quanh nội dung), <div> là block (chiếm trọn hàng). bgColor/bg-color không phải thuộc tính CSS.","source":"quiz"},{"id":"qz-2-25","chapter":3,"difficulty":2,"type":"single","question":"[Quiz 2] Kết quả mong muốn: \"Thông báo\" nền đỏ và câu \"Hôm nay bạn cần chọn đáp án đúng\" nền vàng, CẢ HAI đều là thanh kéo dài hết chiều ngang, mỗi thanh một dòng. Mã nào đúng?","options":["\n```\n<div>\n  <div style=\"background:red\">Thông báo</div>\n  <span style=\"background-color:yellow\">Hôm nay bạn cần chọn đáp án đúng</span>\n</div>\n```","\n```\n<div>\n  <span style=\"background:red\">Thông báo</span>\n  <div style=\"background-color:yellow\">Hôm nay bạn cần chọn đáp án đúng</div>\n</div>\n```","\n```\n<div>\n  <span style=\"background:red\">Thông báo</span>\n  <span style=\"background-color:yellow\">Hôm nay bạn cần chọn đáp án đúng</span>\n</div>\n```","\n```\n<div>\n  <div style=\"background:red\">Thông báo</div>\n  <div style=\"background-color:yellow\">Hôm nay bạn cần chọn đáp án đúng</div>\n</div>\n```"],"correct":[3],"explanation":"Cả hai thanh kéo dài hết chiều ngang nên cả hai phải là block element <div>.","source":"quiz"},{"id":"qz-2-26","chapter":3,"difficulty":2,"type":"single","question":"[Quiz 2] Dùng thẻ nav tạo menu: Khoa HTTT | Google | Visual Studio, nhấn vào thì mở website tương ứng; bên dưới có dòng nền vàng với chữ \"Chú ý:\" in đậm. Mã nào đúng?","options":["\n```\n<nav>\n  <a href=\"https://is.uel.edu.vn\">Khoa HTTT</a> |\n  <a href=\"http://google.com\">Google</a> |\n  <a href=\"https://visualstudio.microsoft.com\">Visual Studio</a>\n</nav>\n<p style=\"bg-Color:yellow\">Chú ý: nav không hỗ trợ IE 8 trở xuống</p>\n```","\n```\n<nav>\n  <a src=\"https://is.uel.edu.vn\">Khoa HTTT</a> |\n  <a src=\"http://google.com\">Google</a> |\n  <a src=\"https://visualstudio.microsoft.com\">Visual Studio</a>\n</nav>\n<p style=\"background:yellow\"><b>Chú ý:</b> nav không hỗ trợ IE 8 trở xuống</p>\n```","\n```\n<nav>\n  <a href=\"https://is.uel.edu.vn\">Khoa HTTT</a> |\n  <a href=\"http://google.com\">Google</a> |\n  <a href=\"https://visualstudio.microsoft.com\">Visual Studio</a>\n</nav>\n<p style=\"background:yellow\"><strong>Chú ý:</strong> nav không hỗ trợ IE 8 trở xuống</p>\n```","\n```\n<nav>\n  <a src=\"https://is.uel.edu.vn\">Khoa HTTT</a> |\n  <a src=\"http://google.com\">Google</a> |\n  <a src=\"https://visualstudio.microsoft.com\">Visual Studio</a>\n</nav>\n<p style=\"background:yellow\"><strong>Chú ý:</strong> nav không hỗ trợ IE 8 trở xuống</p>\n```"],"correct":[2],"explanation":"Liên kết phải dùng href (src không có tác dụng với <a>). bg-Color không phải thuộc tính CSS, đồng thời phương án đó thiếu chữ in đậm.","source":"quiz"},{"id":"qz-2-27","chapter":3,"difficulty":2,"type":"single","question":"[Quiz 2] Cho 5 chữ UEL: thứ 1 không định dạng; thứ 2 in nghiêng; thứ 3 in đậm + in nghiêng + gạch chân; thứ 4 in đậm; thứ 5 in đậm + gạch chân. Mã nào đúng?","options":["\n```\nUEL\n<i>UEL</i>\n<b><u><i>UEL</i></u></b>\n<b>UEL</b>\n<b><u>UEL</u></b>\n```","\n```\nUEL\n<i>UEL</i>\n<b><i><u>UEL</i></u></b>\n<b>UEL</b>\n<b><i>UEL</i></b>\n```","\n```\nUEL\n<i>UEL<i/>\n<b><u><i>UEL<i/><u/><b/>\n<b>UEL<b/>\n<b><u>UEL<u/><b/>\n```","\n```\nUEL\n<i>UEL</i>\n<b><u><i>UEL</u></i></b>\n<b>UEL</b>\n<b><u>UEL</u></b>\n```"],"correct":[0],"explanation":"Thẻ mở sau phải đóng trước (lồng đúng thứ tự). Thẻ đóng là </i>, không phải <i/>. Phương án C sai ở chữ thứ 5 (in nghiêng thay vì gạch chân).","source":"quiz"},{"id":"qz-2-28","chapter":3,"difficulty":2,"type":"multiple","question":"[Quiz 2] Lệnh nào tương đương với lệnh: <b><u><i>Học HTML không khó</i></u></b> (chọn nhiều đáp án)","options":["<b><u><i>Học HTML không khó<i/><u/><b/>","<u><b><i>Học HTML không khó</i></b></u>","<b><i><u>Học HTML không khó</u></i></b>","<i><u><b>Học HTML không khó</b></u></i>"],"correct":[1,2,3],"explanation":"Thứ tự lồng các thẻ định dạng không quan trọng, miễn là lồng đúng (mở sau đóng trước). Phương án dùng <i/> là thẻ đóng sai cú pháp.","source":"quiz"},{"id":"qz-2-29","chapter":3,"difficulty":2,"type":"single","question":"[Quiz 2] Hiển thị: \"Phương trình bậc 2: ax² + bx + c = 0\" (số 2 nằm trên) và \"O₂ + H₂ = H²O\" (O₂, H₂ có số 2 nằm dưới, H²O có số 2 nằm trên). Mã nào đúng?","options":["ax<sub>2</sub>+bx+c=0 ... O<sup>2</sup>+H<sup>2</sup>=H<sub>2</sub>O","ax<supscript>2</supscript>+bx+c=0 ... O<subscript>2</subscript>+H<subscript>2</subscript>=H<supscript>2</supscript>O","ax<subscript>2</subscript>+bx+c=0 ... O<supscript>2</supscript>+H<supscript>2</supscript>=H<subscript>2</subscript>O","ax<sup>2</sup>+bx+c=0 ... O<sub>2</sub>+H<sub>2</sub>=H<sup>2</sup>O"],"correct":[3],"explanation":"<sup> = superscript (chỉ số trên, số mũ), <sub> = subscript (chỉ số dưới). Không có thẻ <supscript>/<subscript>.","source":"quiz"},{"id":"qz-2-30","chapter":3,"difficulty":1,"type":"single","question":"[Quiz 2] Định dạng chuỗi \"Hello World\" có font chữ tahoma, kích thước 15, màu đỏ:","options":["<font name=\"tahoma\" size=\"15\" color=\"red\">Hello World</font>","<font face=\"tahoma\" size=\"15\" color=\"red\">Hello World</font>","<font name=\"tahoma\" size=\"15\" text-color=\"red\">Hello World</font>","<font face=\"tahoma\" height=\"15\" text-color=\"red\">Hello World</font>"],"correct":[1],"explanation":"Thẻ font có 3 thuộc tính: face (kiểu chữ), size (cỡ chữ), color (màu).","source":"quiz"},{"id":"qz-2-31","chapter":3,"difficulty":1,"type":"single","question":"[Quiz 2] Hiển thị hình \"h1.png\" có chiều cao 100, chiều rộng 200:","options":["<img src=\"h1.png\" height=\"100\" width=\"200\"></img>","<photo link=\"h1.png\" height=\"100\" width=\"200\"></photo>","<photo src=\"h1.png\" height=\"100\" width=\"200\"></photo>","<img link=\"h1.png\" height=\"100\" width=\"200\"></img>"],"correct":[0],"explanation":"Thẻ hình là <img>, đường dẫn hình là thuộc tính src.","source":"quiz"},{"id":"qz-2-32","chapter":3,"difficulty":2,"type":"single","question":"[Quiz 2] Chọn câu trả lời đúng:","options":["HTML dùng các thuộc tính (attributes) để định dạng hiển thị. Trình duyệt thường không báo lỗi cú pháp HTML","HTML dùng các Element để định dạng hiển thị. Trình duyệt sẽ thông báo lỗi nếu viết sai cú pháp và không chạy được","HTML dùng các thẻ (tags) để định dạng hiển thị. Nếu viết sai cú pháp HTML trình duyệt sẽ báo lỗi và tắt chương trình","HTML dùng các thẻ (tags) để định dạng cách hiển thị dữ liệu. Trình duyệt thường không báo lỗi cú pháp HTML; viết sai chỉ dẫn đến hiển thị không đúng dự định"],"correct":[3],"explanation":"HTML dùng thẻ (tag). Trình duyệt bỏ qua lỗi cú pháp, chỉ hiển thị sai.","source":"quiz"},{"id":"qz-2-33","chapter":3,"difficulty":1,"type":"single","question":"[Quiz 2] Khi chọn mã màu, RGB đại diện cho những thông số nào?","options":["R là red, G là grey, B là brown","R là red, G là green, B là blue","R là red, G là gray, B là blond","R là read, G là green, B là brown"],"correct":[1],"explanation":"RGB = Red, Green, Blue.","source":"quiz"},{"id":"qz-2-34","chapter":3,"difficulty":1,"type":"single","question":"[Quiz 2] Mã màu thập lục phân từ 00 đến FF, các giá trị được quy định:","options":["Thấp nhất 000000 là màu trắng, cao nhất FFFFFF là màu đen","Thấp nhất 000000 là màu green, cao nhất FFFFFF là màu blue","Thấp nhất 000000 là màu red, cao nhất FFFFFF là màu blue","Thấp nhất 000000 là màu đen, cao nhất FFFFFF là màu trắng"],"correct":[3],"explanation":"Không có ánh sáng (0,0,0) là đen; đủ cả 3 màu tối đa (255,255,255) là trắng.","source":"quiz"},{"id":"qz-2-35","chapter":3,"difficulty":2,"type":"single","question":"[Quiz 2] Từ mã thập lục phân #FF00FF, chuyển qua cách viết rgb như thế nào?","options":["rgb(255,0,255)","rgb(0,0,255)","rgb(0,255,255)","rgb(0,255,0)"],"correct":[0],"explanation":"FF = 255 (Red), 00 = 0 (Green), FF = 255 (Blue).","source":"quiz"},{"id":"qz-2-36","chapter":3,"difficulty":2,"type":"single","question":"[Quiz 2] Từ mã thập lục phân #88FF00, chuyển qua cách viết rgb như thế nào?","options":["rgb(0,255,136)","rgb(136,0,255)","rgb(136,255,0)","rgb(255,0,255)"],"correct":[2],"explanation":"88 hệ 16 = 8×16 + 8 = 136; FF = 255; 00 = 0. Thứ tự giữ nguyên R, G, B.","source":"quiz"},{"id":"qz-2-37","chapter":3,"difficulty":1,"type":"single","question":"[Quiz 2] HTML hỗ trợ trình bày các đề mục dạng nút hay đánh số thứ tự:","options":["LI trình bày đề mục dạng thứ tự; DL trình bày đề mục dạng các nút","OL trình bày đề mục dạng thứ tự (số hoặc ký tự); UL trình bày đề mục dạng các nút","OL trình bày đề mục dạng các nút; UL trình bày đề mục dạng thứ tự","LI trình bày đề mục dạng các nút; DL trình bày đề mục dạng thứ tự"],"correct":[1],"explanation":"OL = Ordered List (có thứ tự), UL = Unordered List (dạng nút).","source":"quiz"},{"id":"qz-2-38","chapter":3,"difficulty":1,"type":"single","question":"[Quiz 2] Để tạo mục lục đánh số 1. Chương 1, 2. Chương 2, 3. Chương 3, cấu trúc HTML nào đúng?","options":["<dl type=1><li>Chương 1</li><li>Chương 2</li><li>Chương 3</li></dl>","<ul type=1><li>Chương 1</li><li>Chương 2</li><li>Chương 3</li></ul>","<ul><li>Chương 1</li><li>Chương 2</li><li>Chương 3</li></ul>","<ol><li>Chương 1</li><li>Chương 2</li><li>Chương 3</li></ol>"],"correct":[3],"explanation":"Danh sách đánh số dùng <ol>, mặc định type=\"1\".","source":"quiz"},{"id":"qz-2-40","chapter":3,"difficulty":2,"type":"single","question":"[Quiz 2] Để tạo mục lục A. HTML (1, 2, 3), B. CSS (1, 2, 3), C. Javascript (1, 2, 3), mỗi nhóm con đánh số lại từ 1, ta làm như thế nào?","options":["\n```\n<dl type=A>\n<li>HTML</li>\n  <dl type=1> ...3 mục... </dl>\n<li>CSS</li>\n  <dl type=1> ...3 mục... </dl>\n<li>Javascript</li>\n  <dl type=1> ...3 mục... </dl>\n</dl>\n```","\n```\n<ol type=A>\n<li>HTML</li>\n  <ol type=1> ...3 mục... </ol>\n<li>CSS</li>\n  <ol type=1> ...3 mục... </ol>\n<li>Javascript</li>\n  <ol type=1> ...3 mục... </ol>\n</ol>\n```","\n```\n<ul type=A>\n<li>HTML</li>\n  <ul type=1> ...3 mục... </ul>\n<li>CSS</li>\n  <ul type=1> ...3 mục... </ul>\n<li>Javascript</li>\n  <ul type=1> ...3 mục... </ul>\n</ul>\n```","\n```\n<ol type=A>\n<li>HTML</li>\n  <dl type=1> ...3 mục... </dl>\n<li>CSS</li>\n  <dl type=1> ...3 mục... </dl>\n<li>Javascript</li>\n  <dl type=1> ...3 mục... </dl>\n</ol>\n```"],"correct":[1],"explanation":"Đánh số A, B, C và 1, 2, 3 đều là danh sách có thứ tự <ol> với thuộc tính type. So sánh với câu dùng start=\"4\" khi muốn số chạy liên tục.","source":"quiz"},{"id":"qz-3-01","chapter":8,"difficulty":1,"type":"single","question":"[Quiz 3] TypeScript được phát triển bởi ai?","options":["Mozilla","Google","Microsoft","Facebook"],"correct":[2],"explanation":"Slide 41 liệt kê TypeScript (Microsoft) trong các ngôn ngữ script thông dụng.","source":"quiz"},{"id":"qz-3-02","chapter":7,"difficulty":2,"type":"single","question":"[Quiz 3] Which input type defines a slider control?","options":["controls","range","slider","search"],"correct":[1],"explanation":"<input type=\"range\" min=\"1\" max=\"11\" value=\"9\"> tạo thanh trượt (slide 36).","source":"quiz"},{"id":"qz-3-03","chapter":8,"difficulty":1,"type":"single","question":"[Quiz 3] Kết quả của đoạn mã TypeScript sau là gì?\n```\nlet message: string = \"Hello, TypeScript!\";\nconsole.log(message);\n```","options":["Lỗi biên dịch","\"Hello, TypeScript!\"","undefined","null"],"correct":[1],"explanation":"Biến kiểu string được gán chuỗi hợp lệ nên in ra chuỗi đó.","source":"quiz"},{"id":"qz-3-04","chapter":6,"difficulty":1,"type":"single","question":"[Quiz 3] What is the correct CSS syntax for making all the <p> elements bold?","options":["<p style=\"text-size:bold;\">","p {font-weight:bold;}","<p style=\"font-size:bold;\">","p {text-size:bold;}"],"correct":[1],"explanation":"In đậm dùng font-weight. Đề nói \"all the <p> elements\" nên dùng selector p trong CSS.","source":"quiz"},{"id":"qz-3-05","chapter":3,"difficulty":1,"type":"single","question":"[Quiz 3] Để trình bày các đề mục với dạng nút ta sử dụng thẻ:","options":["<DL>","<OL>","<UL>","<LI>"],"correct":[2],"explanation":"UL = danh sách dạng nút (bullet).","source":"quiz"},{"id":"qz-3-06","chapter":6,"difficulty":1,"type":"single","question":"[Quiz 3] How do you select an element with id 'demo'?","options":["#demo","demo",".demo","*demo"],"correct":[0],"explanation":"# cho id, . cho class.","source":"quiz"},{"id":"qz-3-08","chapter":3,"difficulty":2,"type":"single","question":"[Quiz 3] Which HTML element is used to display a scalar measurement within a range?","options":["<gauge>","<measure>","<range>","<meter>"],"correct":[3],"explanation":"<meter value=\"0.6\">60%</meter> hiển thị giá trị đo trong một khoảng. HTML không có thẻ <gauge>, <measure>, <range>.","source":"quiz"},{"id":"qz-3-09","chapter":3,"difficulty":1,"type":"single","question":"[Quiz 3] The HTML <canvas> element is used to:","options":["manipulate data in MySQL","create draggable elements","draw graphics","display database records"],"correct":[2],"explanation":"<canvas> là vùng vẽ đồ họa bằng JavaScript.","source":"quiz"},{"id":"qz-3-10","chapter":6,"difficulty":1,"type":"single","question":"[Quiz 3] How do you select elements with class name 'test'?","options":["*test","#test","test",".test"],"correct":[3],"explanation":"Selector class bắt đầu bằng dấu chấm.","source":"quiz"},{"id":"qz-3-11","chapter":5,"difficulty":1,"type":"single","question":"[Quiz 3] Which CSS property controls the text size?","options":["text-size","font-size","font-style","text-style"],"correct":[1],"explanation":"font-size điều khiển cỡ chữ; font-style là in nghiêng.","source":"quiz"},{"id":"qz-3-12","chapter":6,"difficulty":2,"type":"single","question":"[Quiz 3] Tạo danh sách không thứ tự Cà phê, Ca cao, Khoai tây chiên với ký hiệu đầu dòng là hình \"h1.png\" (cùng cấp file html):","options":["\n```\n<ul style=\"list-style-image:url('h1.png')\">\n  <li>Cà phê</li>\n  <li>Ca cao</li>\n  <li>Khoai tây chiên</li>\n</ul>\n```","\n```\n<ul style=\"image:url('h1.png')\">\n  <li>Cà phê</li>\n  <li>Ca cao</li>\n  <li>Khoai tây chiên</li>\n</ul>\n```","\n```\n<dt style=\"list-style-image:url('h1.png')\">\n  <li>Cà phê</li>\n  <li>Ca cao</li>\n  <li>Khoai tây chiên</li>\n</dt>\n```","\n```\n<ul style=\"list-style-image:url('h1.png')\">\n  <dt>Cà phê</dt>\n  <dt>Ca cao</dt>\n  <dt>Khoai tây chiên</dt>\n</ul>\n```"],"correct":[0],"explanation":"Thuộc tính CSS list-style-image:url(...) đặt trên <ul>, các mục vẫn là <li>.","source":"quiz"},{"id":"qz-3-13","chapter":6,"difficulty":1,"type":"single","question":"[Quiz 3] What is the default value of the position property?","options":["absolute","static","relative","fixed"],"correct":[1],"explanation":"Slide 33: static là định vị mặc định.","source":"quiz"},{"id":"qz-3-15","chapter":3,"difficulty":1,"type":"single","question":"[Quiz 3] Which HTML attribute specifies an alternate text for an image, if the image cannot be displayed?","options":["alt","longdesc","src","title"],"correct":[0],"explanation":"alt hiển thị khi không tải được hình; title hiện tooltip khi rê chuột.","source":"quiz"},{"id":"qz-3-16","chapter":3,"difficulty":1,"type":"single","question":"[Quiz 3] Thẻ h dùng để làm gì và có bao nhiêu cấp độ?","options":["Định dạng dòng văn bản theo phân cấp đề mục. Kích thước ký tự TĂNG DẦN từ 1 đến 6. Sau mỗi thẻ, văn bản tự động xuống dòng","Định dạng đoạn văn bản. Kích thước nhỏ dần từ 1 đến 6. Sau mỗi thẻ không tự xuống dòng, phải dùng br","Định dạng đoạn văn bản. Kích thước tăng dần từ 1 đến 5. Sau mỗi thẻ không tự xuống dòng, phải dùng br","Định dạng dòng văn bản theo phân cấp đề mục. Kích thước ký tự NHỎ DẦN từ 1 đến 6. Sau mỗi thẻ, văn bản tự động xuống dòng"],"correct":[3],"explanation":"h1 lớn nhất, h6 nhỏ nhất; heading là block element nên tự xuống dòng.","source":"quiz"},{"id":"qz-3-17","chapter":3,"difficulty":2,"type":"single","question":"[Quiz 3] Chọn đáp án đúng:","options":["&nbsp tạo khoảng trắng; &lt tạo dấu lớn hơn; &gt tạo dấu nhỏ hơn; &quot tạo dấu ngoặc đơn","&nbsp; tạo khoảng trắng; &lt; tạo dấu lớn hơn; &gt; tạo dấu lớn hơn; &quot; tạo dấu ngoặc kép","&nbsp tạo khoảng trắng; &lt tạo dấu nhỏ hơn; &gt tạo dấu lớn hơn; &quot tạo dấu ngoặc kép","&nbsp; tạo khoảng trắng; &lt; tạo dấu nhỏ hơn; &gt; tạo dấu lớn hơn; &quot; tạo dấu ngoặc kép"],"correct":[3],"explanation":"Mã ký tự đặc biệt phải có dấu chấm phẩy cuối. lt = less than (<), gt = greater than (>), quot = quotation (\").","source":"quiz"},{"id":"qz-3-18","chapter":5,"difficulty":1,"type":"single","question":"[Quiz 3] Which HTML attribute is used to define inline styles?","options":["font","class","styles","style"],"correct":[3],"explanation":"Inline CSS viết trong thuộc tính style của thẻ.","source":"quiz"},{"id":"qz-3-20","chapter":4,"difficulty":2,"type":"single","question":"[Quiz 3] Tạo bảng 3x3 (rộng 150, cao 100) có hình chữ thập: ô giữa nền vàng, 4 ô trên-dưới-trái-phải của ô giữa nền xanh lá, 4 ô góc để trống. Mã nào đúng?","options":["\n```\n<table border=\"1\" width=\"150\" height=\"100\">\n<tr><td></td><td bgColor=\"green\"></td><td></td></tr>\n<tr><td bgColor=\"green\"></td><td bgColor=\"yellow\"></td><td bgColor=\"green\"></td></tr>\n<tr><td></td><td bgColor=\"green\"></td><td></td></tr>\n</table>\n```","\n```\n<table border=\"1\" width=\"150\" height=\"100\">\n<tr><td></td><td style=\"bgColor:green\"></td><td></td></tr>\n<tr><td style=\"bgColor:green\"></td><td style=\"bgColor:yellow\"></td><td style=\"bgColor:green\"></td></tr>\n<tr><td></td><td style=\"bgColor:green\"></td><td></td></tr>\n</table>\n```","\n```\n<table border=\"1\" width=\"150\" height=\"100\">\n<tr><td></td><td background-color=\"green\"></td><td></td></tr>\n<tr><td background-color=\"green\"></td><td background-color=\"yellow\"></td><td background-color=\"green\"></td></tr>\n<tr><td></td><td background-color=\"green\"></td><td></td></tr>\n</table>\n```","\n```\n<table border=\"1\" width=\"150\" height=\"100\">\n<tr><td></td><td backgroundColor=\"green\"></td><td></td></tr>\n<tr><td backgroundColor=\"green\"></td><td backgroundColor=\"yellow\"></td><td backgroundColor=\"green\"></td></tr>\n<tr><td></td><td backgroundColor=\"green\"></td><td></td></tr>\n</table>\n```"],"correct":[0],"explanation":"Thuộc tính HTML của ô là bgColor. background-color chỉ hợp lệ bên trong style=\"...\"; bgColor không phải thuộc tính CSS.","source":"quiz"},{"id":"qz-3-21","chapter":7,"difficulty":1,"type":"single","question":"[Quiz 3] In HTML, which attribute is used to specify that an input field must be filled out?","options":["placeholder","formvalidate","required","validate"],"correct":[2],"explanation":"required bắt buộc nhập trước khi submit.","source":"quiz"},{"id":"qz-3-23","chapter":3,"difficulty":2,"type":"single","question":"[Quiz 3] Which HTML element is used to specify a header for a document or section?","options":["<section>","<head>","<top>","<header>"],"correct":[3],"explanation":"<header> là phần đầu hiển thị của trang/khu vực. <head> chứa thông tin meta, không hiển thị.","source":"quiz"},{"id":"qz-3-24","chapter":6,"difficulty":2,"type":"single","question":"[Quiz 3] How do you make each word in a text start with a capital letter?","options":["transform:capitalize","text-transform:capitalize","You can't do that with CSS","text-style:capitalize"],"correct":[1],"explanation":"text-transform nhận capitalize, uppercase, lowercase.","source":"quiz"},{"id":"qz-3-25","chapter":5,"difficulty":1,"type":"single","question":"[Quiz 3] Phát biểu nào dưới đây đúng với cú pháp của CSS?","options":["p { center:text-align; color:red}","p {text-align:center; color:red}","p {text-align:center; red:color }","p { color:red, text-align:center}"],"correct":[1],"explanation":"selector {property: value; property: value}. Các cặp ngăn cách bằng dấu chấm phẩy, không dùng dấu phẩy.","source":"quiz"},{"id":"qz-3-26","chapter":5,"difficulty":1,"type":"single","question":"[Quiz 3] What does CSS stand for?","options":["Colorful Style Sheets","Cascading Style Sheets","Computer Style Sheets","Creative Style Sheets"],"correct":[1],"explanation":"CSS = Cascading Style Sheets.","source":"quiz"},{"id":"qz-3-27","chapter":4,"difficulty":3,"type":"single","question":"[Quiz 3] Index.html chia 2 khung trên/dưới: khung trên cao 30 chứa Menu.html, khung dưới chứa trang nội dung (mặc định gioithieu.html). Bấm menu Trang chủ, Giới thiệu, Liên hệ thì trang tương ứng mở ở khung dưới. Cấu trúc nào đúng?","options":["\n```\nMenu.html:\n<a href=\"TrangChu.html\" name=\"main\">Trang chủ</a>|\n<a href=\"GioiThieu.html\" name=\"main\">Giới thiệu</a>|\n<a href=\"LienHe.html\" name=\"main\">Liên Hệ</a>\nIndex.html:\n<frameset rows=\"30;100%\" frameborder=\"no\">\n  <frame src=\"menu.html\" target=\"main\"></frame>\n  <frame src=\"gioithieu.html\" name=\"main\"></frame>\n</frameset>\n```","\n```\nMenu.html:\n<a href=\"TrangChu.html\" target=\"main\">Trang chủ</a>|\n<a href=\"GioiThieu.html\" target=\"main\">Giới thiệu</a>|\n<a href=\"LienHe.html\" target=\"main\">Liên Hệ</a>\nIndex.html:\n<frameset rows=\"30,100%\" frameborder=\"no\">\n  <frame src=\"menu.html\" name=\"main\"></frame>\n  <frame src=\"gioithieu.html\" target=\"main\"></frame>\n</frameset>\n```","\n```\nMenu.html:\n<a href=\"TrangChu.html\" target=\"main\">Trang chủ</a>|\n<a href=\"GioiThieu.html\" target=\"main\">Giới thiệu</a>|\n<a href=\"LienHe.html\" target=\"main\">Liên Hệ</a>\nIndex.html:\n<frameset rows=\"30;100%\" frameborder=\"no\">\n  <Iframe src=\"menu.html\" target=\"main\"></Iframe>\n  <Iframe src=\"gioithieu.html\" name=\"main\"></Iframe>\n</frameset>\n```","\n```\nMenu.html:\n<a href=\"TrangChu.html\" target=\"main\">Trang chủ</a>|\n<a href=\"GioiThieu.html\" target=\"main\">Giới thiệu</a>|\n<a href=\"LienHe.html\" target=\"main\">Liên Hệ</a>\nIndex.html:\n<frameset rows=\"30,100%\" frameborder=\"no\">\n  <frame src=\"menu.html\" target=\"main\"></frame>\n  <frame src=\"gioithieu.html\" name=\"main\"></frame>\n</frameset>\n```"],"correct":[3],"explanation":"Khung đích phải được đặt name=\"main\", và liên kết trong menu dùng target=\"main\". Giá trị rows ngăn cách bằng dấu phẩy. Trong frameset dùng <frame>, không dùng <iframe>.","source":"quiz"},{"id":"qz-3-28","chapter":8,"difficulty":2,"type":"single","question":"[Quiz 3] Đoạn mã TypeScript sau sẽ báo lỗi gì?\n```\nlet isDone: boolean = \"true\";\n```","options":["Lỗi logic","Lỗi kiểu dữ liệu","Lỗi cú pháp","Không có lỗi"],"correct":[1],"explanation":"Biến khai báo kiểu boolean nhưng được gán chuỗi \"true\" (có dấu nháy) nên TypeScript báo lỗi kiểu dữ liệu.","source":"quiz"},{"id":"qz-3-29","chapter":6,"difficulty":2,"type":"single","question":"[Quiz 3] Cho đoạn code sau, chọn câu trả lời phù hợp:\n```\n<style type=\"text/css\">\n  p { color:blue; }\n  #mau { color:red; }\n</style>\n...\n<p class=\"mau\">chào mừng k10406</p>\n```","options":["Đoạn lệnh này sai","Nội dung của thẻ p sẽ là màu xanh","Nội dung của thẻ p là màu đen mặc định của trình duyệt","Nội dung của thẻ p sẽ là màu đỏ"],"correct":[1],"explanation":"#mau là selector ID nhưng thẻ p dùng class=\"mau\" nên không khớp. Chỉ còn quy tắc p {color:blue} được áp dụng.","source":"quiz"},{"id":"qz-3-30","chapter":3,"difficulty":2,"type":"single","question":"[Quiz 3] Một thẻ (tag) thường có 3 hoặc 4 phần: <ten_the tên_TT1=\"giá_trị1\">Noi dung</ten_the>. Phát biểu nào đúng?","options":["Tên thẻ: nhận dạng chức năng của thẻ; Thuộc tính: nhận biết dữ liệu được hiển thị như thế nào; Giá trị của thuộc tính; Hoặc có thêm thành phần con giữa tag mở và tag đóng","Thuộc tính: nhận dạng chức năng của thẻ; Tên thẻ: nhận biết dữ liệu hiển thị như thế nào; Giá trị thuộc tính; Hoặc chứa các thành phần khác","Tên thẻ: thiết lập sự kiện cho từng chức năng; Thuộc tính: nhận biết dữ liệu hiển thị như thế nào; Giá trị thuộc tính; Thành phần con","Tên thẻ: nhận dạng chức năng; Thuộc tính: để điều hướng người dùng; Giá trị thuộc tính; Thành phần con giữa tag mở và đóng"],"correct":[0],"explanation":"Tên thẻ cho biết chức năng (p là đoạn văn, img là hình...), thuộc tính quy định cách hiển thị dữ liệu.","source":"quiz"},{"id":"qz-3-31","chapter":8,"difficulty":1,"type":"single","question":"[Quiz 3] TypeScript là gì?","options":["Một siêu bộ (superset) mở rộng của JavaScript","Một ngôn ngữ lập trình hoàn toàn mới","Một phần mềm IDE","Một framework JavaScript"],"correct":[0],"explanation":"TypeScript bổ sung kiểu dữ liệu tĩnh cho JavaScript và biên dịch ra JavaScript.","source":"quiz"},{"id":"qz-3-32","chapter":6,"difficulty":2,"type":"single","question":"[Quiz 3] How do you display a border like this: top = 10px, bottom = 5px, left = 20px, right = 1px?","options":["border-width:10px 5px 20px 1px;","border-width:10px 20px 5px 1px;","border-width:10px 1px 5px 20px;","border-width:5px 20px 10px 1px;"],"correct":[2],"explanation":"Thứ tự 4 giá trị theo chiều kim đồng hồ: top, right, bottom, left = 10px 1px 5px 20px.","source":"quiz"},{"id":"qz-3-33","chapter":3,"difficulty":1,"type":"single","question":"[Quiz 3] What is the correct HTML for inserting an image?","options":["<img src=\"image.gif\" alt=\"MyImage\">","<image src=\"image.gif\" alt=\"MyImage\">","<img href=\"image.gif\" alt=\"MyImage\">","<img alt=\"MyImage\">image.gif</img>"],"correct":[0],"explanation":"Thẻ img với thuộc tính src.","source":"quiz"},{"id":"qz-3-34","chapter":5,"difficulty":1,"type":"single","question":"[Quiz 3] Which is the correct CSS syntax?","options":["{body;color:black;}","body:color=black;","{body:color=black;}","body {color: black;}"],"correct":[3],"explanation":"selector { property: value; }","source":"quiz"},{"id":"qz-3-35","chapter":5,"difficulty":2,"type":"single","question":"[Quiz 3] Độ ưu tiên của 3 loại CSS sau theo thứ tự TĂNG DẦN:","options":["Inline Style Sheet, Embedding Style Sheet, External Style Sheet","External Style Sheet, Inline Style Sheet, Embedding Style Sheet","Inline Style Sheet, External Style Sheet, Embedding Style Sheet","External Style Sheet, Embedding (Internal) Style Sheet, Inline Style Sheet"],"correct":[3],"explanation":"Inline cao nhất, External thấp nhất (khi External được link trước Internal). Đề hỏi TĂNG DẦN nên đọc từ thấp lên cao.","source":"quiz"},{"id":"qz-3-36","chapter":3,"difficulty":1,"type":"single","question":"[Quiz 3] Cấu trúc chung của một trang Web tĩnh:","options":["\n```\n<html>\n<head>\n  <meta charset=\"UTF-8\">\n  <title>Đây là tiêu đề của trang web</title>\n</head>\n<content>\n  Đây là nội dung chính của trang Web\n</content>\n</html>\n```","\n```\n<html>\n<title>\n  <meta charset=\"UTF-8\">\n  <head>Đây là tiêu đề của trang web</head>\n</title>\n<body>\n  Đây là nội dung chính của trang Web\n</body>\n</html>\n```","\n```\n<html>\n<head>\n  <meta charset=\"UTF-8\">\n  <title>Đây là tiêu đề của trang web</title>\n</head>\n<body>\n  Đây là nội dung chính của trang Web\n</body>\n</html>\n```","\n```\n<html>\n<hed>\n  <meta charset=\"UTF-8\">\n  <title>Đây là tiêu đề của trang web</title>\n</hed>\n<body>\n  Đây là nội dung chính của trang Web\n</body>\n</html>\n```"],"correct":[2],"explanation":"html bao ngoài; head chứa meta và title; body chứa nội dung hiển thị.","source":"quiz"},{"id":"qz-3-37","chapter":6,"difficulty":1,"type":"single","question":"[Quiz 3] How do you display hyperlinks without an underline?","options":["a {underline:none;}","a {text-decoration:no-underline;}","a {decoration:no-underline;}","a {text-decoration:none;}"],"correct":[3],"explanation":"text-decoration: none bỏ gạch chân (Bài tập 35, 59).","source":"quiz"},{"id":"qz-3-38","chapter":5,"difficulty":1,"type":"single","question":"[Quiz 3] How do you insert a comment in a CSS file?","options":["/* this is a comment */","' this is a comment","// this is a comment //","// this is a comment"],"correct":[0],"explanation":"CSS chỉ có một kiểu ghi chú /* */.","source":"quiz"},{"id":"qz-3-39","chapter":3,"difficulty":2,"type":"single","question":"[Quiz 3] The HTML global attribute \"contenteditable\" is used to:","options":["Return the position of the first found occurrence of content inside a string","Specify a context menu for an element","Update content from the server","Specify whether the content of an element should be editable or not"],"correct":[3],"explanation":"<p contenteditable=\"true\"> cho phép người dùng sửa trực tiếp nội dung trên trang.","source":"quiz"},{"id":"qz-3-40","chapter":5,"difficulty":1,"type":"single","question":"[Quiz 3] Lựa chọn kiểu khai báo CSS đúng nhất cho cú pháp sau:\n```\n<style type=\"text/css\">\n  .tieude { color:blue; }\n</style>\n```","options":["Browser default","Internal Style Sheet","External Style Sheet","Inline Style Sheet"],"correct":[1],"explanation":"CSS viết trong thẻ <style> của trang là Internal (Embedding) Style Sheet.","source":"quiz"},{"id":"bs-c1-01","chapter":1,"difficulty":2,"type":"single","question":"(Bài tập 7) Cho URL: https://tranduythanh.com/html-css-javascript/?id=113. Protocol, domain và parameter lần lượt là:","options":["https | tranduythanh.com/html-css-javascript | ?id","tranduythanh.com | html-css-javascript | id","https:// | html-css-javascript | 113","https | tranduythanh.com | id=113"],"correct":[3],"explanation":"Protocol là https; domain là tranduythanh.com; phần sau dấu ? là tham số (parameter) id=113. html-css-javascript là đường dẫn (path).","source":"bosung"},{"id":"bs-c1-02","chapter":1,"difficulty":2,"type":"single","question":"Chạy file bằng Live Server trong VS Code, trình duyệt mở địa chỉ http://127.0.0.1:5500/Exercise9/Home.html. Con số 127.0.0.1 và 5500 lần lượt là gì?","options":["Địa chỉ IP của nhà cung cấp hosting và dung lượng hosting","Địa chỉ IP của server UEL và mã số bài tập","Địa chỉ IP localhost (máy của mình) và cổng (port) mà Live Server đang chạy","Địa chỉ IPv6 và số lượng người truy cập tối đa"],"correct":[2],"explanation":"127.0.0.1 là localhost. Số sau dấu hai chấm trong URL là port; Live Server mặc định dùng cổng 5500.","source":"bosung"},{"id":"bs-c1-03","chapter":1,"difficulty":2,"type":"single","question":"(Bài tập 10) Một website triển khai trên IIS có các file: Home.html, Login.html, index.html, About.html. Chưa cấu hình Default Document. Khi gõ địa chỉ website mà không ghi tên trang, IIS hiển thị trang nào?","options":["Báo lỗi vì không có trang chủ","index.html","Login.html","Home.html"],"correct":[1],"explanation":"IIS mặc định tìm các trang: Default.htm, Default.asp, Default.aspx, index.htm, index.html, iisstart.htm. Muốn Home.html hay Login.html làm trang chủ phải thêm vào Default Document.","source":"bosung"},{"id":"bs-c1-04","chapter":1,"difficulty":2,"type":"single","question":"(Bài tập 10) Máy của bạn có IP 192.168.100.3, đã cấu hình IIS với Application alias là hello. Một máy khác trong CÙNG mạng LAN muốn xem website thì gõ địa chỉ nào?","options":["http://localhost/hello","http://192.168.100.3/hello","http://127.0.0.1/hello","http://hello/192.168.100.3"],"correct":[1],"explanation":"localhost/127.0.0.1 luôn trỏ về chính máy đang gõ, nên máy khác phải dùng IP thật của máy bạn (xem bằng lệnh ipconfig).","source":"bosung"},{"id":"bs-c1-05","chapter":1,"difficulty":1,"type":"single","question":"(Bài tập 10) Để xem địa chỉ IP của máy tính mình trên Windows, ta mở cửa sổ cmd và gõ lệnh nào?","options":["ping localhost","ipconfig","ifconfig /all","getip"],"correct":[1],"explanation":"Windows + R, gõ cmd, rồi gõ ipconfig để xem IPv4 Address.","source":"bosung"},{"id":"bs-c1-06","chapter":1,"difficulty":2,"type":"single","question":"(Bài tập 10) Trong IIS, mục đích chính của việc tạo Application Pool riêng cho từng ứng dụng web là gì?","options":["Cô lập các ứng dụng: lỗi ở Application Pool này không ảnh hưởng ứng dụng ở Application Pool khác","Tăng dung lượng ổ cứng cho website","Tự động mua tên miền cho website","Chuyển website từ web tĩnh sang web động"],"correct":[0],"explanation":"Mỗi Application Pool chạy trong tiến trình riêng nên giúp cách ly và bảo mật ứng dụng.","source":"bosung"},{"id":"bs-c1-07","chapter":1,"difficulty":2,"type":"single","question":"(Bài tập 5) Một cửa hàng nội thất ở Việt Nam muốn làm website bán hàng online. Nhóm tên miền nào phù hợp nhất để mua (và mua \"bao vây\")?","options":[".com, .vn, .com.vn",".org, .int",".edu, .edu.vn",".net, .gov.vn"],"correct":[0],"explanation":".com dành cho thương mại; .vn và .com.vn cho doanh nghiệp tại Việt Nam. .edu dành cho giáo dục, .int cho tổ chức quốc tế, .gov cho chính phủ.","source":"bosung"},{"id":"bs-c2-01","chapter":2,"difficulty":2,"type":"single","question":"Website bán hàng viết bằng PHP và dùng cơ sở dữ liệu MySQL thì thường thuê loại hosting nào?","options":["Windows hosting bắt buộc","MAC hosting","Linux hosting","Không cần hosting, chỉ cần tên miền"],"correct":[2],"explanation":"PHP và MySQL chạy tốt và rẻ trên Linux hosting. Nếu dùng ASP.NET và SQL Server thì chọn Windows hosting.","source":"bosung"},{"id":"bs-c2-02","chapter":2,"difficulty":1,"type":"single","question":"Trong quy trình thiết lập website, bước nằm ngay SAU bước \"Thuê chỗ hosting\" là gì?","options":["Thiết kế website","Mua tên miền","Xác định yêu cầu","Duy trì, bảo trì"],"correct":[0],"explanation":"1. Xác định yêu cầu, 2. Mua tên miền, 3. Thuê hosting, 4. Thiết kế website, 5. Đưa vào hoạt động, 6. Duy trì bảo trì.","source":"bosung"},{"id":"bs-c3-01","chapter":3,"difficulty":2,"type":"single","question":"Đoạn mã sau hiển thị như thế nào?\n```\n<ol type=\"a\" start=\"3\">\n  <li>Ghế sofa</li>\n  <li>Bàn trà</li>\n</ol>\n```","options":["3. Ghế sofa và 4. Bàn trà","c. Ghế sofa và d. Bàn trà","a. Ghế sofa và b. Bàn trà","C. Ghế sofa và D. Bàn trà"],"correct":[1],"explanation":"type=\"a\" đánh số bằng chữ thường; start=\"3\" bắt đầu từ ký tự thứ 3 là c.","source":"bosung"},{"id":"bs-c3-02","chapter":3,"difficulty":2,"type":"single","question":"Đoạn mã <ol type=\"I\" start=\"4\"> chứa 3 thẻ <li>. Ký hiệu đánh số của 3 mục lần lượt là:","options":["IV, V, VI","I, II, III","4, 5, 6","D, E, F"],"correct":[0],"explanation":"type=\"I\" là số La Mã in hoa; start=\"4\" nên bắt đầu từ IV.","source":"bosung"},{"id":"bs-c3-03","chapter":3,"difficulty":2,"type":"single","question":"Trình duyệt hiển thị đoạn mã sau như thế nào?\n```\n<p>Xin      chào\ncác      bạn</p>\n```","options":["Xin chào các bạn (trên một dòng, mỗi chữ cách một khoảng trắng)","Giữ nguyên nhiều khoảng trắng và xuống dòng như trong mã","Xin chào trên dòng 1, các bạn trên dòng 2","Báo lỗi vì có nhiều khoảng trắng liên tiếp"],"correct":[0],"explanation":"HTML gộp nhiều khoảng trắng và dấu xuống dòng thành 1 khoảng trắng. Muốn giữ nguyên phải dùng &nbsp;, <br/> hoặc thẻ <pre>.","source":"bosung"},{"id":"bs-c3-04","chapter":3,"difficulty":2,"type":"single","question":"Muốn trang web hiển thị NGUYÊN VĂN dòng chữ <br/> (để dạy học) chứ không ngắt dòng, ta viết:","options":["\"<br/>\"","<br/>","&gt;br/&lt;","&lt;br/&gt;"],"correct":[3],"explanation":"&lt; hiển thị dấu <, &gt; hiển thị dấu >. Viết thẳng <br/> thì trình duyệt hiểu là thẻ ngắt dòng.","source":"bosung"},{"id":"bs-c3-05","chapter":3,"difficulty":3,"type":"single","question":"Cấu trúc thư mục: web/pages/sanpham.html và web/images/ghe.png. Trong sanpham.html, thẻ img nào hiển thị đúng hình?","options":["<img src=\"images/ghe.png\">","<img src=\"../images/ghe.png\">","<img src=\"..images/ghe.png\">","<img src=\"/pages/images/ghe.png\">"],"correct":[1],"explanation":"sanpham.html nằm trong thư mục pages nên phải lùi ra web/ bằng ../ rồi mới vào images/.","source":"bosung"},{"id":"bs-c3-06","chapter":3,"difficulty":2,"type":"single","question":"File web/index.html muốn liên kết tới web/pages/lienhe.html. Thẻ a nào đúng?","options":["<a src=\"pages/lienhe.html\">Liên hệ</a>","<a href=\"lienhe.html\">Liên hệ</a>","<a href=\"../pages/lienhe.html\">Liên hệ</a>","<a href=\"pages/lienhe.html\">Liên hệ</a>"],"correct":[3],"explanation":"index.html và thư mục pages cùng nằm trong web/, nên chỉ cần đi vào pages/.","source":"bosung"},{"id":"bs-c3-07","chapter":3,"difficulty":1,"type":"single","question":"(Bài tập 15 Beethoven) Dùng HÌNH mũi tên next.png làm liên kết sang trang SecondMovement.html. Mã nào đúng?","options":["<img src=\"next.png\"><a href=\"SecondMovement.html\"></a>","<a href=\"SecondMovement.html\"><img src=\"next.png\" alt=\"Trang sau\"></a>","<a src=\"SecondMovement.html\"><img href=\"next.png\"></a>","<img src=\"next.png\" href=\"SecondMovement.html\">"],"correct":[1],"explanation":"Đặt thẻ img nằm BÊN TRONG thẻ a thì hình trở thành liên kết. Thẻ img không có thuộc tính href.","source":"bosung"},{"id":"bs-c3-08","chapter":3,"difficulty":3,"type":"single","question":"(Bài tập 19 Expo) Tạo Image Map: vùng chữ nhật trên hình campus.jpg liên kết tới Bryd.html. Mã nào đúng?","options":["\n```\n<img src=\"campus.jpg\" map=\"#campus\">\n<map name=\"campus\">\n  <a shape=\"rect\" coords=\"10,10,120,80\" href=\"Bryd.html\"></a>\n</map>\n```","\n```\n<img src=\"campus.jpg\" usemap=\"#campus\">\n<map name=\"campus\">\n  <area shape=\"rect\" coords=\"10,10,120,80\" href=\"Bryd.html\">\n</map>\n```","\n```\n<img src=\"campus.jpg\" usemap=\"#campus\">\n<map name=\"campus\">\n  <area shape=\"rect\" coords=\"10,10,120,80\" src=\"Bryd.html\">\n</map>\n```","\n```\n<img src=\"campus.jpg\" usemap=\"campus\">\n<map id=\"khuvuc\">\n  <area shape=\"rect\" coords=\"10,10,120,80\" href=\"Bryd.html\">\n</map>\n```"],"correct":[1],"explanation":"img dùng usemap=\"#tên\" trỏ tới <map name=\"tên\">; mỗi vùng là thẻ <area> có shape, coords và href.","source":"bosung"},{"id":"bs-c3-09","chapter":3,"difficulty":1,"type":"single","question":"(Bài tập 23) Muốn tạo bảng chữ (text table) bằng phím Spacebar và Enter mà trình duyệt giữ nguyên khoảng trắng, xuống dòng, ta đặt nội dung trong thẻ nào?","options":["<p>","<pre>","<div>","<span>"],"correct":[1],"explanation":"Thẻ <pre> (preformatted) giữ nguyên khoảng trắng và dấu xuống dòng như khi gõ.","source":"bosung"},{"id":"bs-c3-10","chapter":3,"difficulty":2,"type":"single","question":"Cuối trang có liên kết \"Về đầu trang\" để nhảy lên tiêu đề <h1> ở đầu cùng trang (HTML5). Mã nào đúng?","options":["<h1 id=\"top\">RoomCraft</h1> ... <a href=\"#top\">Về đầu trang</a>","<h1 id=\"#top\">RoomCraft</h1> ... <a href=\"##top\">Về đầu trang</a>","<h1 class=\"top\">RoomCraft</h1> ... <a href=\".top\">Về đầu trang</a>","<h1 id=\"top\">RoomCraft</h1> ... <a href=\"top\">Về đầu trang</a>"],"correct":[0],"explanation":"HTML5 đặt id cho đích, và href=\"#id\" (có dấu #) để nhảy tới. Giá trị id không chứa dấu #.","source":"bosung"},{"id":"bs-c3-11","chapter":3,"difficulty":2,"type":"single","question":"Đoạn mã <b>Web <i>Kinh</i> Doanh</b> hiển thị như thế nào?","options":["Chữ Web in đậm, chữ Kinh in nghiêng, chữ Doanh bình thường","Chỉ chữ Kinh in nghiêng, các chữ khác bình thường","Báo lỗi vì thẻ i nằm trong thẻ b","Cả 3 chữ in đậm, riêng chữ Kinh vừa đậm vừa nghiêng"],"correct":[3],"explanation":"Mọi nội dung nằm giữa <b> và </b> đều đậm; chữ Kinh còn nằm trong <i> nên thêm nghiêng.","source":"bosung"},{"id":"bs-c3-12","chapter":3,"difficulty":2,"type":"single","question":"Màu rgb(0, 128, 255) viết theo mã Hexa là:","options":["#8000FF","#0080FF","#FF8000","#00FF80"],"correct":[1],"explanation":"0 = 00, 128 = 80 (8×16), 255 = FF. Giữ đúng thứ tự R, G, B.","source":"bosung"},{"id":"bs-c3-13","chapter":3,"difficulty":1,"type":"single","question":"(Bài tập 14) Dùng hình nen.jpg trong thư mục hinh làm HÌNH NỀN cho cả trang. Mã nào đúng?","options":["<body background=\"hinh/nen.jpg\">","<body src=\"hinh/nen.jpg\">","<body bgcolor=\"hinh/nen.jpg\">","<img background=\"hinh/nen.jpg\">"],"correct":[0],"explanation":"Thuộc tính background của body là hình nền; bgcolor là màu nền.","source":"bosung"},{"id":"bs-c3-14","chapter":3,"difficulty":2,"type":"single","question":"Đoạn mã <img src=\"sofa.jpg\" align=\"right\" width=\"200\"> đặt trước một đoạn văn dài. Kết quả là:","options":["Hình bị lật ngược sang phải","Hình nằm giữa trang, chữ nằm phía dưới hình","Hình nằm bên trái, chữ bao quanh bên phải","Hình nằm bên phải, đoạn văn chạy bao quanh phía bên trái hình"],"correct":[3],"explanation":"align=\"right\" đẩy hình sang phải và văn bản bao quanh hình.","source":"bosung"},{"id":"bs-c3-15","chapter":3,"difficulty":2,"type":"single","question":"Đoạn mã sau có lỗi gì?\n```\n<p>Giá: 100 <b>USD</p></b>\n```","options":["Thẻ b không được đặt trong thẻ p","Không có lỗi gì","Trình duyệt báo lỗi cú pháp và không hiển thị trang","Thẻ b mở sau nhưng lại đóng sau thẻ p (lồng sai thứ tự); trình duyệt không báo lỗi nhưng có thể hiển thị không như ý"],"correct":[3],"explanation":"Thẻ mở sau phải đóng trước: <p>... <b>USD</b></p>. HTML không báo lỗi cú pháp, chỉ hiển thị sai.","source":"bosung"},{"id":"bs-c3-16","chapter":3,"difficulty":1,"type":"single","question":"Muốn khi rê chuột vào hình thì hiện chữ \"Ghế gỗ sồi\", ta thêm thuộc tính nào cho img?","options":["tooltip=\"Ghế gỗ sồi\"","name=\"Ghế gỗ sồi\"","title=\"Ghế gỗ sồi\"","alt=\"Ghế gỗ sồi\""],"correct":[2],"explanation":"title hiển thị tooltip khi rê chuột; alt hiển thị khi hình không tải được.","source":"bosung"},{"id":"bs-c4-01","chapter":4,"difficulty":2,"type":"single","question":"Bảng có 3 cột. Dòng 2 viết: <td rowspan=\"2\">X</td><td>Y</td><td>Z</td>. Dòng 3 cần bao nhiêu thẻ <td> để bảng đủ 3 cột, không bị lệch?","options":["3","1","2","4"],"correct":[2],"explanation":"Ô X đã kéo xuống chiếm cột 1 của dòng 3, nên dòng 3 chỉ còn 2 ô.","source":"bosung"},{"id":"bs-c4-02","chapter":4,"difficulty":3,"type":"single","question":"Thời khóa biểu có 6 cột (cột Buổi + T2...T6). Buổi Sáng gồm 2 dòng: ô \"Sáng\" có rowspan=\"2\", ô \"Trống\" ở cột T4 cũng có rowspan=\"2\". Dòng THỨ HAI của buổi sáng phải viết bao nhiêu thẻ <td>?","options":["5","6","4","3"],"correct":[2],"explanation":"Dòng 1 buổi sáng có 6 ô. Dòng 2 bị ô Sáng (cột 1) và ô Trống (cột T4) chiếm sẵn, nên chỉ còn 4 ô cho T2, T3, T5, T6.","source":"bosung"},{"id":"bs-c4-03","chapter":4,"difficulty":3,"type":"single","question":"Thời khóa biểu 6 cột (Buổi, T2, T3, T4, T5, T6). Dòng đầu buổi Chiều viết:\n```\n<tr>\n  <td rowspan=\"2\">Chiều</td>\n  <td>&nbsp;</td>\n  <td>&nbsp;</td>\n  <td>&nbsp;</td>\n  <td rowspan=\"2\" style=\"background-color:#009900\">Trống</td>\n  <td>&nbsp;</td>\n</tr>\n```\nÔ \"Trống\" màu xanh nằm ở cột nào?","options":["T3","T4","T5","T6"],"correct":[2],"explanation":"Đếm từ trái: Chiều (cột 1), 3 ô trống là T2, T3, T4, ô thứ 5 là T5.","source":"bosung"},{"id":"bs-c4-04","chapter":4,"difficulty":2,"type":"single","question":"Trong bảng điểm (slide 18), dòng tiêu đề thứ hai chỉ có 2 thẻ <th> là Python và Java OOP. Vì sao?","options":["Vì dòng thứ hai bị lỗi, cần thêm 3 thẻ th trống","Vì #, Student ID, Student Name đã có rowspan=\"2\" chiếm chỗ, còn Score có colspan=\"2\" chừa 2 ô cho Python và Java OOP","Vì thẻ th chỉ được dùng tối đa 2 lần trong một dòng","Vì Score có rowspan=\"2\""],"correct":[1],"explanation":"rowspan kéo ô xuống dòng dưới; colspan mở rộng ô sang phải. Python và Java OOP nằm dưới ô Score.","source":"bosung"},{"id":"bs-c4-05","chapter":4,"difficulty":3,"type":"single","question":"Cho đoạn colgroup (slide 19) cho bảng 5 cột #, Product Id, Product Name, Unit Price, VAT:\n```\n<colgroup>\n  <col span=\"1\" style=\"background-color: pink;\"/>\n  <col span=\"1\"/>\n  <col span=\"1\" style=\"background-color: orange;\">\n  <col span=\"2\" style=\"background-color: cyan;\">\n</colgroup>\n```\nTrong phần tbody, cột nào KHÔNG được tô màu?","options":["#","VAT","Product Id","Product Name"],"correct":[2],"explanation":"Thứ tự: # hồng, Product Id không style (bỏ qua cột), Product Name cam, Unit Price và VAT xanh cyan (span=\"2\").","source":"bosung"},{"id":"bs-c4-06","chapter":4,"difficulty":2,"type":"single","question":"Bảng 3 cột. Muốn cột 1 để nguyên, cột 2 và cột 3 nền xanh lá bằng colgroup. Mã nào đúng?","options":["\n```\n<colgroup>\n  <col span=\"2\" style=\"background-color:green\">\n</colgroup>\n```","\n```\n<colgroup>\n  <col/>\n  <col colspan=\"2\" style=\"background-color:green\">\n</colgroup>\n```","\n```\n<colgroup>\n  <col/>\n  <col span=\"2\" style=\"background-color:green\">\n</colgroup>\n```","\n```\n<colgroup span=\"2\" style=\"background-color:green\">\n  <col/>\n</colgroup>\n```"],"correct":[2],"explanation":"Cột không muốn định dạng vẫn phải khai báo <col/> trống để giữ chỗ; thẻ col dùng span (không phải colspan).","source":"bosung"},{"id":"bs-c4-07","chapter":4,"difficulty":2,"type":"single","question":"Trang có iframe hiển thị nội dung. Muốn bấm liên kết \"Sản phẩm\" thì sanpham.html mở BÊN TRONG iframe. Mã nào đúng?","options":["<iframe name=\"khung\" src=\"home.html\"></iframe> ... <a href=\"sanpham.html\" name=\"khung\">Sản phẩm</a>","<iframe target=\"khung\" src=\"home.html\"></iframe> ... <a href=\"sanpham.html\" target=\"khung\">Sản phẩm</a>","<iframe id=\"khung\" src=\"home.html\"></iframe> ... <a href=\"sanpham.html\" target=\"_blank\">Sản phẩm</a>","<iframe name=\"khung\" src=\"home.html\"></iframe> ... <a href=\"sanpham.html\" target=\"khung\">Sản phẩm</a>"],"correct":[3],"explanation":"Đặt name cho iframe (khung đích) và dùng target=\"tên khung\" trong thẻ a, giống cách dùng với frameset.","source":"bosung"},{"id":"bs-c4-08","chapter":4,"difficulty":3,"type":"single","question":"(Bài tập 27) Chia trang: khung trên cao 100px chứa Logo.html; phần dưới chia 2 cột: trái 20% chứa Link.html, phải chứa Homepage.html (tên main). Mã nào đúng?","options":["\n```\n<frameset rows=\"100,*\">\n  <frame src=\"Logo.html\">\n  <frame cols=\"20%,*\">\n    <frame src=\"Link.html\">\n    <frame src=\"Homepage.html\" name=\"main\">\n  </frame>\n</frameset>\n```","\n```\n<frameset cols=\"100,*\">\n  <frame src=\"Logo.html\">\n  <frameset rows=\"20%,*\">\n    <frame src=\"Link.html\">\n    <frame src=\"Homepage.html\" name=\"main\">\n  </frameset>\n</frameset>\n```","\n```\n<frameset rows=\"100,*\">\n  <frame src=\"Logo.html\">\n  <frameset cols=\"20%,*\">\n    <frame src=\"Link.html\">\n    <frame src=\"Homepage.html\" name=\"main\">\n  </frameset>\n</frameset>\n```","\n```\n<body>\n<frameset rows=\"100,*\">\n  <frame src=\"Logo.html\">\n  <frame src=\"Link.html\">\n  <frame src=\"Homepage.html\" name=\"main\">\n</frameset>\n</body>\n```"],"correct":[2],"explanation":"rows chia theo chiều ngang (trên/dưới), cols chia theo cột (trái/phải). Muốn chia tiếp phải lồng thêm <frameset>. Trang dùng frameset không dùng <body>.","source":"bosung"},{"id":"bs-c4-09","chapter":4,"difficulty":1,"type":"single","question":"(Bài tập 32) Cho dòng chữ \"Khoa Hệ Thống Thông Tin\" chạy qua trái rồi chạy lại qua phải liên tục. Mã nào đúng?","options":["<marquee behavior=\"alternate\">Khoa Hệ Thống Thông Tin</marquee>","<marquee direction=\"alternate\">Khoa Hệ Thống Thông Tin</marquee>","<marquee loop=\"1\">Khoa Hệ Thống Thông Tin</marquee>","<marquee behavior=\"slide\">Khoa Hệ Thống Thông Tin</marquee>"],"correct":[0],"explanation":"behavior: scroll (chạy bình thường), slide (chạy 1 lần rồi dừng), alternate (chạy qua rồi chạy lại). direction chỉ nhận left, right, up, down.","source":"bosung"},{"id":"bs-c4-10","chapter":4,"difficulty":2,"type":"single","question":"(Slide 22, câu 5) Thiết lập đối tượng: chạy từ trên xuống, kiểu chạy scroll, lặp liên tục, tốc độ 15. Mã nào đúng?","options":["<marquee direction=\"down\" behavior=\"scroll\" loop=\"-1\" scrollamount=\"15\">","<marquee direction=\"bottom\" behavior=\"scroll\" loop=\"0\" scrollamount=\"15\">","<marquee direction=\"down\" behavior=\"slide\" loop=\"-1\" speed=\"15\">","<marquee direction=\"up\" behavior=\"scroll\" loop=\"1\" scrollamount=\"15\">"],"correct":[0],"explanation":"Chạy xuống: direction=\"down\"; lặp liên tục: loop=\"-1\"; tốc độ: scrollamount.","source":"bosung"},{"id":"bs-c4-11","chapter":4,"difficulty":2,"type":"single","question":"(Bài tập 32) Chèn bài hát nhac.mp3 làm nhạc nền, tự phát khi mở trang và phát lặp lại. Mã nào phù hợp nhất?","options":["<audio autoplay loop><source src=\"nhac.mp3\" type=\"audio/mpeg\"></audio>","<video src=\"nhac.mp3\" loop></video>","<music src=\"nhac.mp3\" autoplay></music>","<audio controls><source src=\"nhac.mp3\" type=\"video/mp4\"></audio>"],"correct":[0],"explanation":"autoplay tự phát, loop lặp lại, type của mp3 là audio/mpeg. Lưu ý: Chrome thường chặn tự phát có tiếng cho đến khi người dùng tương tác với trang.","source":"bosung"},{"id":"bs-c4-12","chapter":4,"difficulty":1,"type":"single","question":"Chèn video movie.mp4 trong thư mục media, rộng 320, cao 240, có thanh điều khiển. Mã nào đúng?","options":["<video size=\"320x240\" controls><src=\"media/movie.mp4\"></video>","<video width=\"320\" height=\"240\"><source href=\"media/movie.mp4\" type=\"mp4\"></video>","<movie width=\"320\" height=\"240\" controls src=\"media/movie.mp4\"></movie>","<video width=\"320\" height=\"240\" controls><source src=\"media/movie.mp4\" type=\"video/mp4\"></video>"],"correct":[3],"explanation":"Cú pháp theo slide 23: thẻ video, thuộc tính controls, thẻ con source có src và type.","source":"bosung"},{"id":"bs-c4-13","chapter":4,"difficulty":1,"type":"single","question":"(Bài tập 25, 26) Có thể đặt một thẻ <table> bên trong một ô <td> của bảng khác không?","options":["Không, trình duyệt sẽ báo lỗi","Chỉ được nếu bảng con không có viền","Có, gọi là bảng lồng nhau, thường dùng để dàn trang","Chỉ được đặt trong <th>"],"correct":[2],"explanation":"Bảng lồng nhau (nested table) là kỹ thuật dàn trang trong các bài Gargoyle, Dunston.","source":"bosung"},{"id":"bs-c4-14","chapter":4,"difficulty":1,"type":"single","question":"Bảng có 4 cột. Dòng cuối trong tfoot chỉ có 1 ô ghi \"Designed by [John]\" kéo dài hết chiều ngang bảng. Mã nào đúng?","options":["<tfoot><tr><td colspan=\"4\">Designed by [John]</td></tr></tfoot>","<tfoot><tr><td rowspan=\"4\">Designed by [John]</td></tr></tfoot>","<tfoot><td span=\"4\">Designed by [John]</td></tfoot>","<tfoot colspan=\"4\"><tr><td>Designed by [John]</td></tr></tfoot>"],"correct":[0],"explanation":"Gộp ngang 4 cột dùng colspan=\"4\" trên ô td.","source":"bosung"},{"id":"bs-c5-01","chapter":5,"difficulty":2,"type":"single","question":"(Slide 28) External CSS: h3 { color: red; text-align: left; font-size: 8pt }. Internal CSS (khai báo sau link): h3 { text-align: right; font-size: 20pt }. Thẻ h3 hiển thị thế nào?","options":["Màu đỏ, căn trái, cỡ 8pt","Màu đỏ, căn phải, cỡ 20pt","Màu đỏ, căn trái, cỡ 20pt","Màu mặc định (đen), căn phải, cỡ 20pt"],"correct":[1],"explanation":"Các thuộc tính được gộp lại: color chỉ có ở External nên vẫn đỏ; text-align và font-size bị Internal ghi đè.","source":"bosung"},{"id":"bs-c5-02","chapter":5,"difficulty":1,"type":"single","question":"Cho <style> p { color: blue } </style> và <p style=\"color: red\">Sale 50%</p>. Chữ Sale 50% màu gì?","options":["Đỏ","Đen mặc định","Tím (trộn 2 màu)","Xanh dương"],"correct":[0],"explanation":"Inline CSS có độ ưu tiên cao nhất.","source":"bosung"},{"id":"bs-c5-03","chapter":5,"difficulty":3,"type":"single","question":"Trong head, thẻ <style> p { color: green } </style> được viết TRƯỚC thẻ <link rel=\"stylesheet\" href=\"a.css\">, file a.css có p { color: orange }. Chữ trong thẻ p màu gì?","options":["Xanh lá, vì Internal luôn thắng External","Đen mặc định vì bị xung đột","Cam xen kẽ xanh lá","Cam (orange), vì quy tắc khai báo sau ghi đè quy tắc trước khi cùng selector"],"correct":[3],"explanation":"Thứ tự \"Internal ưu tiên hơn External\" đúng khi link được đặt trước style (cách viết thông thường). Bản chất là cùng selector thì quy tắc đọc sau thắng.","source":"bosung"},{"id":"bs-c5-04","chapter":5,"difficulty":2,"type":"single","question":"(Bài tập 33) Đoạn CSS sau tạo hiệu ứng gì?\n```\nbody {\n  background-image: url('hinh/camel.gif');\n  background-position: right bottom;\n  background-repeat: no-repeat;\n  background-attachment: fixed;\n}\n```","options":["Hình lạc đà ở góc trên bên trái, cuộn theo nội dung","Hình lạc đà lặp lại kín cả trang","Hình lạc đà lặp theo hàng ngang ở cuối trang","Một hình con lạc đà duy nhất ở góc dưới bên phải, đứng yên khi cuộn trang"],"correct":[3],"explanation":"no-repeat: không lặp; right bottom: góc dưới phải; fixed: cố định khi cuộn.","source":"bosung"},{"id":"bs-c5-05","chapter":5,"difficulty":3,"type":"single","question":"(Bài tập 34) Có lỗi trong dòng: <p style=\"font-family: verdana; font-size=14pt;\">. Kết quả hiển thị là:","options":["Trình duyệt báo lỗi và không hiển thị đoạn văn","Chữ vẫn dùng font Verdana nhưng cỡ chữ 14pt KHÔNG được áp dụng vì viết font-size=14pt sai cú pháp","Cả hai thuộc tính đều bị bỏ qua","Cả font Verdana và cỡ 14pt đều được áp dụng"],"correct":[1],"explanation":"Trong CSS phải dùng dấu hai chấm property: value. Khai báo sai bị bỏ qua riêng, các khai báo đúng khác vẫn có hiệu lực.","source":"bosung"},{"id":"bs-c5-06","chapter":5,"difficulty":1,"type":"single","question":"Selector h1, h2, .note { color: green } áp dụng cho những phần tử nào?","options":["Tất cả thẻ h1, tất cả thẻ h2 và mọi phần tử có class=\"note\"","Chỉ thẻ h2 có class note nằm trong h1","Chỉ các phần tử có đủ cả 3 điều kiện","Chỉ thẻ h1 và h2, bỏ qua .note"],"correct":[0],"explanation":"Dấu phẩy là nhóm selector (multiple selectors): mỗi selector được áp dụng riêng.","source":"bosung"},{"id":"bs-c5-07","chapter":5,"difficulty":2,"type":"single","question":"CSS có p.left { text-align: left }. Thẻ <h1 class=\"left\">Tiêu đề</h1> có bị căn trái theo quy tắc này không?","options":["Có, nhưng chỉ khi h1 nằm trong p","Không, vì p.left chỉ áp dụng cho thẻ p có class left","Trình duyệt báo lỗi","Có, vì class left áp dụng cho mọi thẻ"],"correct":[1],"explanation":"tên_tag.tên_class gắn class với 1 thẻ cụ thể. Muốn dùng chung cho mọi thẻ thì viết .left.","source":"bosung"},{"id":"bs-c5-08","chapter":5,"difficulty":1,"type":"single","question":"Cho CSS: p { color: red; /* color: blue; */ }. Chữ trong thẻ p màu gì?","options":["Báo lỗi","Xanh dương","Đen mặc định","Đỏ"],"correct":[3],"explanation":"Phần nằm trong /* */ là ghi chú, bị bỏ qua.","source":"bosung"},{"id":"bs-c5-09","chapter":5,"difficulty":2,"type":"single","question":"(Slide 24, câu 5) Tạo style cho thẻ p: chữ đỏ, font Tahoma, căn giữa, cỡ 30pt, in nghiêng. Mã nào đúng?","options":["p { color: red; font-family: Tahoma; text-align: center; font-size: 30pt; font-style: italic; }","p { color: red; font-family: Tahoma; text-align: center; font-size: 30pt; font-weight: italic; }","p { color: red, font-family: Tahoma, text-align: center, font-size: 30pt, font-style: italic }","p { text-color: red; font: Tahoma; align: center; size: 30pt; font-style: italic; }"],"correct":[0],"explanation":"In nghiêng dùng font-style: italic (font-weight dùng cho đậm). Các khai báo ngăn cách bằng dấu chấm phẩy.","source":"bosung"},{"id":"bs-c6-01","chapter":6,"difficulty":3,"type":"single","question":"(Slide 29) CSS khai báo p.right { text-align: right } rồi đến p.left { text-align: left }. Thẻ <p class=\"right left\">Xin chào</p> được căn lề thế nào?","options":["Không căn lề vì 2 class xung đột","Căn phải, vì right đứng trước trong thuộc tính class","Căn giữa (kết hợp 2 class)","Căn trái, vì p.left khai báo SAU trong CSS"],"correct":[3],"explanation":"Hai selector có cùng độ ưu tiên thì quy tắc viết sau trong CSS thắng. Thứ tự tên class trong thuộc tính class không quan trọng.","source":"bosung"},{"id":"bs-c6-02","chapter":6,"difficulty":2,"type":"single","question":"CSS: #tieude { color: red } và .xanh { color: blue }. Thẻ <h1 id=\"tieude\" class=\"xanh\">Sale</h1> màu gì?","options":["Đỏ, vì selector id ưu tiên hơn selector class","Đen mặc định","Tím do trộn màu","Xanh, vì class viết sau id trong thẻ"],"correct":[0],"explanation":"Độ ưu tiên: inline > id > class > tên thẻ.","source":"bosung"},{"id":"bs-c6-03","chapter":6,"difficulty":2,"type":"single","question":"(Bài tập 47) Selector tbody tr:nth-child(2n+1) chọn những dòng nào của tbody?","options":["Dòng 1, 3, 5, ... (dòng lẻ)","Chỉ dòng thứ 3","Mọi dòng trừ dòng đầu tiên","Dòng 2, 4, 6, ... (dòng chẵn)"],"correct":[0],"explanation":"Với n = 0, 1, 2... thì 2n+1 = 1, 3, 5... Dòng chẵn là 2n.","source":"bosung"},{"id":"bs-c6-04","chapter":6,"difficulty":2,"type":"single","question":"(Bài tập 47) Bảng đang có 5 dòng trong tbody, tô màu bằng tbody tr:nth-child(2n) {background-color: pink}. Dùng JavaScript thêm dòng thứ 6 vào tbody thì dòng mới có màu gì?","options":["Không có màu, vì CSS chỉ áp dụng lúc tải trang","Vàng","Hồng (pink), vì CSS tự nhận dạng dòng chẵn kể cả dòng thêm mới","Whitesmoke"],"correct":[2],"explanation":"nth-child tính lại theo vị trí thực tế, nên dòng mới tự động được tô theo chẵn/lẻ.","source":"bosung"},{"id":"bs-c6-05","chapter":6,"difficulty":2,"type":"single","question":"Cho HTML và CSS:\n```\n<div class=\"menu\">\n  <p>A</p>\n  <section><p>B</p></section>\n  <p>C</p>\n</div>\n.menu > p { color: red; }\n```\nNhững chữ nào màu đỏ?","options":["Chỉ B","Chỉ A","A và C","A, B và C"],"correct":[2],"explanation":"> là child selector, chỉ chọn con trực tiếp (cấp 1). B là cháu (nằm trong section) nên không được chọn. Nếu viết .menu p (descendant) thì cả B cũng đỏ.","source":"bosung"},{"id":"bs-c6-06","chapter":6,"difficulty":2,"type":"single","question":"(Bài tập 35) CSS: ol { list-style-type: upper-roman } ol ol { list-style-type: decimal } ol ol ul { list-style-type: circle }. Các mục của danh sách <ol> nằm BÊN TRONG một <ol> khác được đánh dấu bằng gì?","options":["a, b, c","Hình tròn rỗng (circle)","I, II, III (upper-roman)","1, 2, 3 (decimal)"],"correct":[3],"explanation":"Selector ol ol chọn ol nằm trong ol, cụ thể hơn ol nên ghi đè thành decimal. ol ol ul áp dụng cho ul nằm trong cấp đó.","source":"bosung"},{"id":"bs-c6-07","chapter":6,"difficulty":3,"type":"single","question":"(Bài tập 36) CSS theo thứ tự: a:link { color: red } a:visited { color: green } a:hover { color: hotpink } a:active { color: blue }. Rê chuột vào một liên kết ĐÃ TỪNG được truy cập thì chữ màu gì?","options":["Đỏ","Xanh dương","Hồng (hotpink), vì a:hover khai báo sau a:visited","Xanh lá, vì liên kết đã truy cập"],"correct":[2],"explanation":"Liên kết vừa thỏa :visited vừa thỏa :hover; cùng độ ưu tiên nên quy tắc viết sau thắng. Đây là lý do nên viết đúng thứ tự link, visited, hover, active.","source":"bosung"},{"id":"bs-c6-08","chapter":6,"difficulty":2,"type":"single","question":"(Slide 33) Phần tử có height: 200px; margin: 10px; padding: 20px; border: 5px solid #000. Tổng chiều cao (total element height) là bao nhiêu?","options":["200px","235px","270px","250px"],"correct":[2],"explanation":"200 + padding (20+20) + border (5+5) + margin (10+10) = 270px.","source":"bosung"},{"id":"bs-c6-09","chapter":6,"difficulty":2,"type":"single","question":"Khai báo padding: 5px 10px 20px; tương đương với:","options":["top 5px, right 10px, bottom 20px, left 0px","top 5px, right 10px, bottom 20px, left 10px","top 5px, right 20px, bottom 10px, left 20px","top 5px, bottom 5px, left 10px, right 20px"],"correct":[1],"explanation":"3 giá trị: top | left-right | bottom. Giá trị giữa dùng chung cho trái và phải.","source":"bosung"},{"id":"bs-c6-10","chapter":6,"difficulty":2,"type":"single","question":"(Slide 33, câu 5) margin-top: 7px; margin-bottom: 15px; margin-left: 2px; margin-right: 8px viết gọn thành:","options":["margin: 7px 15px 2px 8px;","margin: 7px 8px 15px 2px;","margin: 2px 8px 7px 15px;","margin: 7px 2px 15px 8px;"],"correct":[1],"explanation":"Thứ tự 4 giá trị theo chiều kim đồng hồ: top right bottom left.","source":"bosung"},{"id":"bs-c6-11","chapter":6,"difficulty":2,"type":"single","question":"(Bài tập 37) Menu xổ xuống dùng CSS:\n```\n#container li ul { position: absolute; display: none; }\n#container li:hover ul { display: block; }\n```\nHiệu ứng là gì?","options":["Menu cha bị ẩn khi rê chuột","Menu con luôn hiện, rê chuột vào thì ẩn đi","Menu con ẩn sẵn, chỉ hiện ra khi rê chuột vào mục menu cha","Menu con chỉ hiện khi nhấn chuột phải"],"correct":[2],"explanation":"display: none ẩn ul con; li:hover ul đổi thành block khi rê chuột vào li cha.","source":"bosung"},{"id":"bs-c6-12","chapter":6,"difficulty":3,"type":"single","question":"(Bài tập 37) Vì sao mục menu cha được khai báo #container ul li { position: relative; } khi menu con dùng position: absolute?","options":["Vì position: relative làm chữ in đậm","Để mục cha không bị ẩn","Để menu con định vị tuyệt đối theo mục cha gần nhất có position khác static (ngay dưới mục cha)","Không có tác dụng gì, có thể bỏ"],"correct":[2],"explanation":"absolute định vị dựa theo phần tử cha gần nhất có position không phải static (slide 33).","source":"bosung"},{"id":"bs-c6-13","chapter":6,"difficulty":2,"type":"single","question":"(Bài tập 38 Bốn mùa) Bốn thẻ p cùng có CSS: width: 45%; float: left; margin-left: 2%. Kết quả bố cục là:","options":["Các đoạn bị ẩn","Các đoạn văn xếp thành 2 cột, mỗi hàng 2 đoạn nằm cạnh nhau","Bốn đoạn xếp chồng thành 1 cột","Bốn đoạn nằm trên cùng 1 hàng"],"correct":[1],"explanation":"float: left đẩy phần tử kế tiếp lên nằm cạnh; 2 đoạn 45% (+ margin) vừa 1 hàng, đoạn thứ 3 xuống hàng.","source":"bosung"},{"id":"bs-c6-14","chapter":6,"difficulty":1,"type":"single","question":"(Bài tập 37) Quy tắc * { margin: 0; padding: 0; } có tác dụng gì?","options":["Chỉ xóa margin của thẻ body","Xóa khoảng cách margin và padding mặc định của MỌI phần tử","Không hợp lệ vì * không phải selector","Ẩn toàn bộ phần tử"],"correct":[1],"explanation":"* là selector chọn tất cả phần tử, thường dùng để reset CSS mặc định của trình duyệt.","source":"bosung"},{"id":"bs-c6-15","chapter":6,"difficulty":2,"type":"single","question":"(Bài tập 39) Thuộc tính border-collapse: collapse đặt cho table có tác dụng gì?","options":["Gộp viền của các ô liền kề thành một nét viền duy nhất","Ẩn toàn bộ viền bảng","Thu nhỏ bảng về kích thước nhỏ nhất","Trộn tất cả các ô thành một ô"],"correct":[0],"explanation":"Mặc định mỗi ô có viền riêng (viền đôi); collapse gộp lại thành 1 nét.","source":"bosung"},{"id":"bs-c6-16","chapter":6,"difficulty":2,"type":"single","question":"(Bài tập 42) Selector UL B { color: rgb(155,0,0) } chọn phần tử nào?","options":["Thẻ ul có class B","Các thẻ b nằm bên trong thẻ ul (ở bất kỳ cấp nào)","Cả thẻ ul và thẻ b","Thẻ b nằm ngay sau thẻ ul"],"correct":[1],"explanation":"Khoảng trắng là descendant selector. Tên thẻ trong CSS không phân biệt hoa thường.","source":"bosung"},{"id":"bs-c6-17","chapter":6,"difficulty":3,"type":"single","question":"(Slide 33, ví dụ Box) Bấm vào nút đóng sau thì điều gì xảy ra?\n```\n<div class=\"borderdiv\">\n  <div class=\"alert\">\n    <span class=\"closebtn\"\n      onclick=\"this.parentElement.parentElement.style.display='none';\">\n      <img src=\"close.png\"/>\n    </span>\n    Khoa Hệ Thống Thông Tin - UEL\n  </div>\n  Khoa Hệ Thống Thông Tin thuộc Trường ĐH Kinh Tế - Luật...\n</div>\n```","options":["Chỉ ẩn thanh div.alert","Chỉ ẩn thẻ span","Ẩn toàn bộ div.borderdiv (cả thanh tiêu đề lẫn đoạn nội dung)","Chỉ ẩn hình close.png"],"correct":[2],"explanation":"this là span; parentElement là div.alert; parentElement.parentElement là div.borderdiv.","source":"bosung"},{"id":"bs-c6-18","chapter":6,"difficulty":1,"type":"single","question":"Selector p:first-letter { font-size: 24px; color: orange } định dạng phần nào?","options":["Từ đầu tiên của mỗi đoạn p","Dòng đầu tiên của mỗi đoạn p","Đoạn p đầu tiên trong trang","Chữ cái đầu tiên của mỗi đoạn p"],"correct":[3],"explanation":"first-letter: chữ cái đầu; first-line: dòng đầu (slide 30).","source":"bosung"},{"id":"bs-c6-19","chapter":6,"difficulty":2,"type":"single","question":"Muốn mọi ô của bảng khi rê chuột vào thì đổi nền vàng VÀ con trỏ chuột thành hình bàn tay, CSS nào đúng?","options":["tbody tr:visited { background: yellow; mouse: pointer; }","tbody tr:active { background-color: yellow; cursor: hand-pointer; }","tbody tr:hover { background-color: yellow; cursor: pointer; }","tbody tr.hover { background-color: yellow; cursor: pointer; }"],"correct":[2],"explanation":":hover là trạng thái rê chuột (dấu hai chấm, không phải dấu chấm); cursor: pointer hiển thị bàn tay.","source":"bosung"},{"id":"bs-c7-01","chapter":7,"difficulty":2,"type":"single","question":"(Slide 35) Form gửi bằng method=\"get\" tới ServerGet.html, có 2 ô name=\"txtten\" (nhập Obama) và name=\"txtemail\" (nhập Obama@gmail.com). Sau khi bấm Submit, địa chỉ trên thanh URL là:","options":["ServerGet.html&txtten=Obama?txtemail=Obama@gmail.com","ServerGet.html?txtten=Obama&txtemail=Obama%40gmail.com","ServerGet.html/txtten/Obama/txtemail/Obama@gmail.com","ServerGet.html (dữ liệu được gửi ngầm, không hiện trên URL)"],"correct":[1],"explanation":"GET ghép dữ liệu vào URL sau dấu ?, các cặp name=value nối bằng &. Ký tự @ được mã hóa thành %40.","source":"bosung"},{"id":"bs-c7-02","chapter":7,"difficulty":3,"type":"single","question":"Trong form method=\"get\" có ô <input type=\"text\" id=\"ho\" value=\"Tran\"> (KHÔNG có thuộc tính name). Khi submit, giá trị Tran có được gửi đi không?","options":["Có, gửi dưới dạng id=Tran","Có, gửi dưới dạng ho=Tran","Trình duyệt báo lỗi và không cho submit","Không, vì chỉ những control có thuộc tính name mới được gửi"],"correct":[3],"explanation":"Slide 36 ghi name là thuộc tính quan trọng: dữ liệu gửi đi theo cặp name=value.","source":"bosung"},{"id":"bs-c7-03","chapter":7,"difficulty":2,"type":"single","question":"Cho <label for=\"email\">Email</label> <input type=\"email\" id=\"txtEmail\">. Bấm vào chữ Email thì sao?","options":["Trình duyệt báo lỗi","Không có gì xảy ra vì for không khớp với id của ô nhập","Ô nhập bị ẩn đi","Con trỏ nhảy vào ô txtEmail"],"correct":[1],"explanation":"Thuộc tính for của label phải trùng với id của control thì bấm label mới focus vào control.","source":"bosung"},{"id":"bs-c7-04","chapter":7,"difficulty":3,"type":"single","question":"Cho 2 nút radio:\n```\n<input type=\"radio\" name=\"gioitinh\" value=\"nam\"> Nam\n<input type=\"radio\" name=\"gioiTinh\" value=\"nu\"> Nữ\n```\nNgười dùng thao tác thế nào được?","options":["Không chọn được nút nào","Chọn Nam thì Nữ tự động được chọn","Chọn được CẢ HAI cùng lúc, vì name khác nhau (phân biệt hoa thường) nên không cùng nhóm","Chỉ chọn được 1 trong 2"],"correct":[2],"explanation":"Radio cùng nhóm khi có CÙNG name; gioitinh và gioiTinh là hai tên khác nhau.","source":"bosung"},{"id":"bs-c7-05","chapter":7,"difficulty":2,"type":"single","question":"Combobox <select name=\"traicay\"> có <option value=\"saurieng\">Sầu riêng</option>. Người dùng chọn Sầu riêng rồi submit bằng GET. Dữ liệu gửi đi là:","options":["traicay=Sầu riêng","traicay=saurieng","option=saurieng","saurieng=Sầu riêng"],"correct":[1],"explanation":"Gửi đi theo name của select và value của option được chọn; chữ hiển thị chỉ dành cho người xem.","source":"bosung"},{"id":"bs-c7-06","chapter":7,"difficulty":1,"type":"single","question":"(Bài tập 48) Nút \"Click to cancel\" xóa trắng dữ liệu trên Form mà không cần viết JavaScript. Mã nào đúng?","options":["<input type=\"reset\" value=\"Click to cancel\">","<input type=\"button\" value=\"Click to cancel\">","<input type=\"clear\" value=\"Click to cancel\">","<input type=\"submit\" value=\"Click to cancel\">"],"correct":[0],"explanation":"Nút reset đưa mọi control về trạng thái mặc định.","source":"bosung"},{"id":"bs-c7-07","chapter":7,"difficulty":2,"type":"single","question":"(Bài tập 48) Nút \"Click to register\" khi bấm hiện hộp thông báo \"Đăng ký\" và KHÔNG gửi form. Mã nào đúng?","options":["<input type=\"button\" value=\"Click to register\" onclick=\"message('Đăng ký')\">","<input type=\"reset\" value=\"Click to register\" onclick=\"alert('Đăng ký')\">","<input type=\"button\" value=\"Click to register\" onclick=\"alert('Đăng ký')\">","<input type=\"button\" value=\"Click to register\" onclick=\"alert(\"Đăng ký\")\">"],"correct":[2],"explanation":"type=\"button\" không tự submit. Giá trị onclick đã nằm trong nháy kép nên chuỗi bên trong phải dùng nháy đơn. Hàm hiện thông báo là alert.","source":"bosung"},{"id":"bs-c7-08","chapter":7,"difficulty":3,"type":"single","question":"Ô nhập <input type=\"text\" name=\"fname\" value=\"Mickey\">. Người dùng xóa đi và gõ \"Donald\", sau đó bấm nút reset. Ô nhập hiển thị gì?","options":["MickeyDonald","Mickey","Donald","Rỗng"],"correct":[1],"explanation":"Reset đưa control về giá trị MẶC ĐỊNH ban đầu (value trong mã), không phải xóa trắng.","source":"bosung"},{"id":"bs-c7-09","chapter":7,"difficulty":1,"type":"single","question":"(Slide 37, câu 3) Thiết kế khung đăng nhập có tiêu đề nhóm \"Đăng nhập\". Mã nào đúng?","options":["\n```\n<legend>\n  <fieldset>Đăng nhập</fieldset>\n  Username: <input type=\"text\" name=\"user\"><br>\n  Mật khẩu: <input type=\"text\" name=\"pwd\"><br>\n  <input type=\"submit\" value=\"Đăng nhập\">\n</legend>\n```","\n```\n<group>\n  <caption>Đăng nhập</caption>\n  Username: <input type=\"text\" name=\"user\"><br>\n  Mật khẩu: <input type=\"password\" name=\"pwd\"><br>\n  <input type=\"submit\" value=\"Đăng nhập\">\n</group>\n```","\n```\n<fieldset title=\"Đăng nhập\">\n  Username: <input type=\"text\" name=\"user\"><br>\n  Mật khẩu: <input type=\"password\" name=\"pwd\"><br>\n  <input type=\"reset\" value=\"Đăng nhập\">\n</fieldset>\n```","\n```\n<fieldset>\n  <legend>Đăng nhập</legend>\n  Username: <input type=\"text\" name=\"user\"><br>\n  Mật khẩu: <input type=\"password\" name=\"pwd\"><br>\n  <input type=\"submit\" value=\"Đăng nhập\">\n</fieldset>\n```"],"correct":[3],"explanation":"fieldset nhóm các control, legend là tiêu đề nhóm nằm ngay bên trong fieldset. Ô mật khẩu dùng type=\"password\".","source":"bosung"},{"id":"bs-c7-10","chapter":7,"difficulty":2,"type":"single","question":"Trong form giỏ hàng có <input type=\"hidden\" name=\"masp\" value=\"SP01\">. Phát biểu nào đúng?","options":["Ô này không hiển thị trên trang nhưng giá trị masp=SP01 vẫn được gửi đi khi submit","Ô này không hiển thị và cũng không được gửi đi","Ô này hiển thị nhưng không cho sửa","Ô này chỉ hiển thị khi rê chuột"],"correct":[0],"explanation":"Hidden field lưu giá trị ẩn trên trang và vẫn được gửi kèm dữ liệu form.","source":"bosung"},{"id":"bs-c7-11","chapter":7,"difficulty":3,"type":"single","question":"(Bài tập 52, 53) Vì sao bài Contact và Sản phẩm yêu cầu dùng method GET để chuyển dữ liệu sang một trang HTML mới?","options":["Vì HTML không hỗ trợ thuộc tính method=\"post\"","Vì GET bảo mật hơn POST","Vì GET gửi được dữ liệu không giới hạn","Vì trang nhận là HTML tĩnh, chỉ đọc được dữ liệu nằm trên URL; POST cần trang xử lý phía server"],"correct":[3],"explanation":"Slide 35: chỉ sử dụng được POST khi action chỉ định đến trang xử lý trên Server. Trang HTML tĩnh đọc tham số GET bằng JavaScript (location.search).","source":"bosung"},{"id":"bs-c7-12","chapter":7,"difficulty":2,"type":"single","question":"Ô nhập nhiều dòng có sẵn nội dung mặc định \"Nhập góp ý...\". Mã nào đúng?","options":["<textarea rows=\"4\" cols=\"30\">Nhập góp ý...</textarea>","<input type=\"textarea\" rows=\"4\" value=\"Nhập góp ý...\">","<textarea rows=\"4\" cols=\"30\" value=\"Nhập góp ý...\"/>","<textbox lines=\"4\">Nhập góp ý...</textbox>"],"correct":[0],"explanation":"Nội dung mặc định của textarea nằm giữa thẻ mở và thẻ đóng; rows/cols quy định kích thước.","source":"bosung"},{"id":"bs-c7-13","chapter":7,"difficulty":2,"type":"single","question":"Muốn tạo danh sách cho phép người dùng giữ Ctrl để chọn NHIỀU loại nội thất, hiển thị sẵn 4 dòng. Mã nào đúng?","options":["<input type=\"checkbox\" size=\"4\" multiple>","<select name=\"loai\" multiple=\"4\">...</select>","<select name=\"loai\" size=\"4\">...</select>","<select name=\"loai\" multiple size=\"4\">...</select>"],"correct":[3],"explanation":"Listbox = select + size (số dòng hiển thị) + multiple (chọn nhiều).","source":"bosung"},{"id":"bs-c8-01","chapter":8,"difficulty":2,"type":"single","question":"Đoạn mã sau in ra gì?\n```\nvar a = \"5\";\nvar b = 2;\ndocument.write(a + b);\n```","options":["Lỗi","52","NaN","7"],"correct":[1],"explanation":"Toán tử + gặp chuỗi thì nối chuỗi: \"5\" + 2 = \"52\".","source":"bosung"},{"id":"bs-c8-02","chapter":8,"difficulty":3,"type":"single","question":"Giá trị của x sau đoạn mã là gì?\n```\nvar x = \"10\" - 3 + \"2\";\n```","options":["\"72\"","NaN","\"1032\"","9"],"correct":[0],"explanation":"Phép trừ chuyển chuỗi thành số: \"10\" - 3 = 7; sau đó 7 + \"2\" là nối chuỗi thành \"72\".","source":"bosung"},{"id":"bs-c8-03","chapter":8,"difficulty":2,"type":"single","question":"(Slide 41 ví dụ 1) Nếu hàm cong viết innerHTML = a + b (BỎ eval) và người dùng nhập a = 3, b = 4 vào 2 ô input, kết quả hiển thị là:","options":["7","34","undefined","NaN"],"correct":[1],"explanation":"Giá trị lấy từ ô input (.value) luôn là chuỗi, nên + sẽ nối chuỗi. eval(a) + eval(b) chuyển về số nên ra 7.","source":"bosung"},{"id":"bs-c8-04","chapter":8,"difficulty":2,"type":"single","question":"(Slide 46) Kết quả của Number(\"999\") + Number(false) là:","options":["NaN","\"999false\"","1000","999"],"correct":[3],"explanation":"Number(\"999\") = 999; Number(false) = 0; Number(true) = 1; Number(\"999 888\") = NaN.","source":"bosung"},{"id":"bs-c8-05","chapter":8,"difficulty":2,"type":"single","question":"Biểu thức isNaN(parseInt(\"abc123\")) trả về:","options":["NaN","123","true","false"],"correct":[2],"explanation":"parseInt đọc từ trái sang; gặp chữ ngay đầu nên trả về NaN, isNaN(NaN) = true. Ngược lại parseInt(\"123abc\") = 123.","source":"bosung"},{"id":"bs-c8-06","chapter":8,"difficulty":3,"type":"single","question":"Đoạn mã sau in ra gì?\n```\nvar x = 3, s = \"\";\nswitch (x) {\n  case 1: s += \"A\";\n  default: s += \"D\";\n  case 2: s += \"B\"; break;\n  case 4: s += \"C\";\n}\ndocument.write(s);\n```","options":["B","DBC","D","DB"],"correct":[3],"explanation":"Không có case 3 nên nhảy vào default, thêm D; vì không có break nên chạy tiếp xuống case 2 thêm B rồi gặp break.","source":"bosung"},{"id":"bs-c8-07","chapter":8,"difficulty":2,"type":"single","question":"(Slide 48, câu 5) Tháng 1, 2, 3 đều in \"Quý 1\". Cách viết switch nào tối ưu và đúng?","options":["\n```\nswitch (thang) {\n  case (1..3):\n    document.write(\"Quý 1\"); break;\n}\n```","\n```\nswitch (thang) {\n  case 1 || 2 || 3:\n    document.write(\"Quý 1\"); break;\n}\n```","\n```\nswitch (thang) {\n  case 1, 2, 3:\n    document.write(\"Quý 1\"); break;\n}\n```","\n```\nswitch (thang) {\n  case 1: case 2: case 3:\n    document.write(\"Quý 1\"); break;\n}\n```"],"correct":[3],"explanation":"Nhiều case cùng thực hiện một lệnh thì viết các case liền nhau không có break ở giữa.","source":"bosung"},{"id":"bs-c8-08","chapter":8,"difficulty":3,"type":"single","question":"Đoạn mã sau, gt bằng bao nhiêu?\n```\nvar gt = 1, i = 1;\nwhile (i <= 4) {\n  gt = gt * i;\n  i += 2;\n}\n```","options":["3","24","8","1"],"correct":[0],"explanation":"i = 1: gt = 1; i = 3: gt = 3; i = 5 thì dừng. Chỉ nhân 1 và 3.","source":"bosung"},{"id":"bs-c8-09","chapter":8,"difficulty":2,"type":"single","question":"Đoạn mã sau, s bằng bao nhiêu?\n```\nvar s = 0;\nfor (var i = 1; i <= 10; i++) {\n  if (i % 2 != 0) continue;\n  s += i;\n}\n```","options":["30","0","55","25"],"correct":[0],"explanation":"continue bỏ qua số lẻ, chỉ cộng các số chẵn 2 + 4 + 6 + 8 + 10 = 30.","source":"bosung"},{"id":"bs-c8-10","chapter":8,"difficulty":2,"type":"single","question":"Đoạn mã sau, s bằng bao nhiêu?\n```\nvar s = 0;\nfor (var i = 1; i <= 10; i++) {\n  if (i == 4) break;\n  s += i;\n}\n```","options":["55","4","6","10"],"correct":[2],"explanation":"break thoát vòng lặp khi i = 4, nên chỉ cộng 1 + 2 + 3 = 6.","source":"bosung"},{"id":"bs-c8-11","chapter":8,"difficulty":2,"type":"single","question":"Đoạn mã sau in ra gì?\n```\nvar i = 10;\ndo {\n  i++;\n} while (i < 5);\ndocument.write(i);\n```","options":["Không in gì vì điều kiện sai ngay từ đầu","10","11","5"],"correct":[2],"explanation":"do...while luôn chạy thân vòng lặp ít nhất 1 lần trước khi kiểm tra điều kiện.","source":"bosung"},{"id":"bs-c8-12","chapter":8,"difficulty":3,"type":"single","question":"Biến dem bằng bao nhiêu sau 2 vòng lặp lồng nhau?\n```\nvar dem = 0;\nfor (var i = 1; i <= 3; i++) {\n  for (var j = 1; j <= i; j++) {\n    dem++;\n  }\n}\n```","options":["9","3","4","6"],"correct":[3],"explanation":"i = 1 chạy 1 lần, i = 2 chạy 2 lần, i = 3 chạy 3 lần: 1 + 2 + 3 = 6.","source":"bosung"},{"id":"bs-c8-13","chapter":8,"difficulty":2,"type":"single","question":"Với d = 7, biến xl nhận giá trị gì?\n```\nvar xl = d >= 8 ? \"Giỏi\" : d >= 6.5 ? \"Khá\" : \"Trung bình\";\n```","options":["Trung bình","Lỗi cú pháp","Khá","Giỏi"],"correct":[2],"explanation":"Toán tử 3 ngôi lồng nhau 2 cấp (slide 44 câu 5): 7 >= 8 sai, xét tiếp 7 >= 6.5 đúng nên là Khá.","source":"bosung"},{"id":"bs-c8-14","chapter":8,"difficulty":2,"type":"single","question":"Cho x = 6, y = 3. Biểu thức (x > 5 && y > 5) || !(x == y) có giá trị:","options":["false","NaN","true","undefined"],"correct":[2],"explanation":"(true && false) = false; !(6 == 3) = true; false || true = true.","source":"bosung"},{"id":"bs-c8-15","chapter":8,"difficulty":2,"type":"single","question":"Giá trị cuối cùng của x là bao nhiêu?\n```\nvar x = 10;\nx += 5;\nx *= 2;\nx %= 7;\n```","options":["4","0","2","30"],"correct":[2],"explanation":"x = 15, rồi 30, rồi 30 % 7 = 2.","source":"bosung"},{"id":"bs-c8-16","chapter":8,"difficulty":3,"type":"single","question":"Sau đoạn mã, a và b bằng bao nhiêu?\n```\nvar a = 5;\nvar b = ++a + a++;\n```","options":["a = 7, b = 13","a = 7, b = 12","a = 6, b = 12","a = 7, b = 11"],"correct":[1],"explanation":"++a tăng trước rồi dùng (a = 6, lấy 6); a++ dùng trước rồi tăng (lấy 6, a thành 7). b = 6 + 6 = 12.","source":"bosung"},{"id":"bs-c8-17","chapter":8,"difficulty":2,"type":"single","question":"(Slide 47, câu 6) Điều kiện nào kiểm tra đúng năm y là năm nhuận?","options":["y % 4 == 0 && y % 400 == 0","y % 4 == 0","(y % 4 == 0 && y % 100 != 0) || y % 400 == 0","(y % 4 == 0 || y % 100 != 0) && y % 400 == 0"],"correct":[2],"explanation":"Năm nhuận chia hết cho 4 nhưng không chia hết cho 100, hoặc chia hết cho 400 (2000 nhuận, 1900 không nhuận).","source":"bosung"},{"id":"bs-c8-18","chapter":8,"difficulty":3,"type":"single","question":"(Bài tập 55) Giải phương trình bậc 2 với delta >= 0. Cách viết nghiệm x1 nào ĐÚNG?","options":["x1 = (-b + Math.sqrt(delta)) / 2 * a","x1 = -b + Math.sqrt(delta) / 2 * a","x1 = -b + Math.sqrt(delta) / (2 * a)","x1 = (-b + Math.sqrt(delta)) / (2 * a)"],"correct":[3],"explanation":"Phải đặt ngoặc cho cả tử số và mẫu số. Viết / 2 * a thì JavaScript tính (.../2)*a theo thứ tự trái sang phải.","source":"bosung"},{"id":"bs-c8-19","chapter":8,"difficulty":2,"type":"single","question":"Đoạn mã sau in ra gì?\n```\nfunction nhanDoi(x) {\n  x * 2;\n}\ndocument.write(nhanDoi(3));\n```","options":["undefined","6","3","Lỗi cú pháp"],"correct":[0],"explanation":"Hàm không có lệnh return nên trả về undefined.","source":"bosung"},{"id":"bs-c8-20","chapter":8,"difficulty":2,"type":"single","question":"(Slide 45, câu 5) Hàm có thể gọi lại chính nó. Kết quả gt(4) là bao nhiêu?\n```\nfunction gt(n) {\n  if (n <= 1) return 1;\n  return n * gt(n - 1);\n}\n```","options":["10","4","24","Lỗi vì hàm không được gọi chính nó"],"correct":[2],"explanation":"Đệ quy: 4 × 3 × 2 × 1 = 24.","source":"bosung"},{"id":"bs-c8-21","chapter":8,"difficulty":3,"type":"single","question":"(Bài tập 54) Hàm tìm MAX lấy 2 giá trị trực tiếp từ ô input nên a = \"9\", b = \"10\" (kiểu chuỗi). Đoạn mã document.write(a > b ? a : b) in ra:","options":["NaN","true","9","10"],"correct":[2],"explanation":"So sánh 2 chuỗi là so sánh từng ký tự: \"9\" > \"1\" nên \"9\" > \"10\" là true. Cần đổi sang số bằng parseFloat/Number trước khi so sánh.","source":"bosung"},{"id":"bs-c8-22","chapter":8,"difficulty":3,"type":"single","question":"(Slide 42, câu 2) Đoạn mã sau chạy thế nào?\n```\n<head>\n  <script>\n    document.getElementById(\"intro\").innerText = \"Welcome\";\n  </script>\n</head>\n<body>\n  <p id=\"intro\"></p>\n</body>\n```","options":["Thẻ p hiển thị Welcome","Lỗi: script trong head chạy khi thẻ p chưa được nạp nên getElementById trả về null","Hiển thị Welcome ở đầu trang, ngoài thẻ p","Không lỗi nhưng chỉ chạy sau khi tải lại trang"],"correct":[1],"explanation":"Script đặt trong head chạy ngay khi trang mở, lúc đó body chưa được nạp. Cách sửa: đặt script cuối body (như slide 58) hoặc gọi trong hàm khi bấm nút.","source":"bosung"},{"id":"bs-c8-23","chapter":8,"difficulty":1,"type":"single","question":"Đoạn mã sau in ra gì?\n```\nvar Java = 1;\nvar java = 2;\ndocument.write(Java + java);\n```","options":["2","11","3","Lỗi vì trùng tên biến"],"correct":[2],"explanation":"JavaScript phân biệt chữ hoa thường nên Java và java là 2 biến khác nhau.","source":"bosung"},{"id":"bs-c8-24","chapter":8,"difficulty":1,"type":"single","question":"Lệnh document.write(\"Tôi nói \\\"Xin chào\\\"\"); hiển thị gì trên trang?","options":["Báo lỗi chuỗi","Tôi nói Xin chào","Tôi nói \"Xin chào\"","Tôi nói \\\"Xin chào\\\""],"correct":[2],"explanation":"Dấu \\ là ký tự thoát (escaping character): \\\" hiển thị dấu nháy kép.","source":"bosung"},{"id":"bs-c8-25","chapter":8,"difficulty":3,"type":"single","question":"(Bài tập 57) Hai ô thành tiền chứa \"30000\" và \"45000\". Code tính tổng viết: tong = 0; tong = tong + tt1.value; tong = tong + tt2.value; Kết quả tong là:","options":["\"75000\"","75000","NaN","\"03000045000\""],"correct":[3],"explanation":"0 + \"30000\" là nối chuỗi thành \"030000\", rồi nối tiếp \"45000\". Phải đổi số: tong += parseFloat(tt1.value).","source":"bosung"},{"id":"bs-c8-26","chapter":8,"difficulty":2,"type":"single","question":"(Bài tập 58) Giá trị v nhập vào các ô Activity, Pulse... chỉ được từ 0 đến 2. Điều kiện nào dùng để báo \"nhập lại\"?","options":["if (isNaN(v) || v < 0 || v > 2)","if (isNaN(v) && v < 0 && v > 2)","if (!isNaN(v) || v > 2)","if (v >= 0 || v <= 2)"],"correct":[0],"explanation":"Báo lỗi khi không phải số HOẶC nhỏ hơn 0 HOẶC lớn hơn 2; dùng && thì điều kiện không bao giờ đúng.","source":"bosung"},{"id":"bs-c8-27","chapter":8,"difficulty":1,"type":"single","question":"Lệnh nào gán sự kiện bấm nút để gọi hàm XuLyCong() (slide 41 ví dụ 2)?","options":["<input type=\"button\" value=\"Tính +\" onclick=\"XuLyCong()\"/>","<input type=\"button\" value=\"Tính +\" onclick=\"XuLyCong\"/>","<input type=\"button\" value=\"Tính +\" click=\"XuLyCong()\"/>","<input type=\"button\" value=\"Tính +\" onclick=XuLyCong{}/>"],"correct":[0],"explanation":"Thuộc tính sự kiện là onclick, giá trị là lời gọi hàm có cặp ngoặc tròn.","source":"bosung"},{"id":"bs-c9-01","chapter":9,"difficulty":2,"type":"single","question":"Cho str = \"time and tide wait for no man\". str.indexOf(\"tide\") trả về:","options":["10","-1","5","9"],"correct":[3],"explanation":"Đếm từ 0: \"time \" (0-4), \"and \" (5-8), \"tide\" bắt đầu tại 9.","source":"bosung"},{"id":"bs-c9-02","chapter":9,"difficulty":2,"type":"single","question":"Cho str = \"Apple, Banana, Kiwi\". str.slice(-4) trả về:","options":["\"\"","\"Banana, Kiwi\"","\"Appl\"","\"Kiwi\""],"correct":[3],"explanation":"Số âm đếm ngược từ cuối chuỗi; -4 lấy 4 ký tự cuối.","source":"bosung"},{"id":"bs-c9-03","chapter":9,"difficulty":3,"type":"single","question":"Cho str = \"Apple, Banana, Kiwi\". str.slice(-4, -1) trả về:","options":["\"Kiw\"","\"iwi\"","\"wi\"","\"Kiwi\""],"correct":[0],"explanation":"Lấy từ vị trí -4 (K) đến TRƯỚC vị trí -1 (i cuối), nên được Kiw.","source":"bosung"},{"id":"bs-c9-04","chapter":9,"difficulty":2,"type":"single","question":"Cho str = \"Apple, Banana, Kiwi\". str.substr(15, 4) trả về:","options":["\"Kiw\"","\"a, K\"","\"Banana\"","\"Kiwi\""],"correct":[3],"explanation":"substr(vị trí bắt đầu, SỐ ký tự). K nằm ở vị trí 15.","source":"bosung"},{"id":"bs-c9-05","chapter":9,"difficulty":3,"type":"single","question":"(Slide 52, câu 4) Cho s = \"SV1;Tèo Mộng Mơ;teo@uel.edu.vn\". Lệnh nào lấy đúng email?","options":["s.substring(s.lastIndexOf(\";\"))","s.substring(s.lastIndexOf(\";\") + 1)","s.substring(s.indexOf(\";\") + 1)","s.substr(s.lastIndexOf(\";\"), 1)"],"correct":[1],"explanation":"lastIndexOf(\";\") cho vị trí dấu ; cuối cùng, +1 để bỏ dấu ; đi. Cách khác: s.split(\";\")[2].","source":"bosung"},{"id":"bs-c9-06","chapter":9,"difficulty":2,"type":"single","question":"Kết quả của \"Please visit Microsoft!\".replace(\"MICROSOFT\", \"W3Schools\") là:","options":["Báo lỗi","\"Please visit Microsoft!\" (không thay đổi)","\"Please visit MICROSOFT!\"","\"Please visit W3Schools!\""],"correct":[1],"explanation":"replace phân biệt hoa thường; muốn không phân biệt dùng biểu thức /MICROSOFT/i (thêm g để thay tất cả).","source":"bosung"},{"id":"bs-c9-07","chapter":9,"difficulty":3,"type":"single","question":"(Slide 53, câu 4) Hàm chuẩn hóa chuỗi sau trả về gì khi gọi chuanHoa(\"  nGUYỄN   văn  tèo \")?\n```\nfunction chuanHoa(s) {\n  var arr = s.trim().split(\" \");\n  var kq = [];\n  for (var i = 0; i < arr.length; i++) {\n    if (arr[i] == \"\") continue;\n    kq.push(arr[i].charAt(0).toUpperCase() + arr[i].substring(1).toLowerCase());\n  }\n  return kq.join(\" \");\n}\n```","options":["\" Nguyễn   Văn  Tèo \"","\"NGUYỄN VĂN TÈO\"","\"Nguyễn Văn Tèo\"","\"nGUYỄN   văn  tèo\""],"correct":[2],"explanation":"trim bỏ khoảng trắng 2 đầu, split tách theo dấu cách (sinh ra phần tử rỗng ở chỗ có nhiều dấu cách, được continue bỏ qua), mỗi từ viết hoa chữ đầu rồi join lại bằng 1 khoảng trắng.","source":"bosung"},{"id":"bs-c9-08","chapter":9,"difficulty":3,"type":"single","question":"\"a,b,,c\".split(\",\").length bằng bao nhiêu?","options":["5","3","4","6"],"correct":[2],"explanation":"Giữa 2 dấu phẩy liền nhau có 1 chuỗi rỗng: [\"a\", \"b\", \"\", \"c\"].","source":"bosung"},{"id":"bs-c9-09","chapter":9,"difficulty":1,"type":"single","question":"Lệnh nào lấy ký tự CUỐI CÙNG của chuỗi s?","options":["s.charAt(s.length)","s.lastIndexOf(s)","s.charAt(s.length - 1)","s.charAt(-1)"],"correct":[2],"explanation":"Vị trí bắt đầu từ 0 nên ký tự cuối ở vị trí length - 1. charAt(s.length) trả về chuỗi rỗng.","source":"bosung"},{"id":"bs-c9-10","chapter":9,"difficulty":3,"type":"single","question":"Math.floor(-4.7) trả về:","options":["-4","4","-5","-4.7"],"correct":[2],"explanation":"floor làm tròn XUỐNG (về phía âm vô cùng), nên -4.7 thành -5. Math.ceil(-4.7) = -4.","source":"bosung"},{"id":"bs-c9-11","chapter":9,"difficulty":2,"type":"single","question":"(Bài tập: tung xúc xắc) Lệnh nào sinh số nguyên ngẫu nhiên từ 1 đến 6?","options":["Math.round(Math.random() * 6)","Math.random(1, 6)","Math.floor(Math.random() * 6)","Math.floor(Math.random() * 6) + 1"],"correct":[3],"explanation":"Math.random() cho số trong [0, 1); nhân 6 được [0, 6); floor được 0..5; cộng 1 được 1..6. Math.round(...*6) có thể ra 0.","source":"bosung"},{"id":"bs-c9-12","chapter":9,"difficulty":2,"type":"single","question":"(Slide 54) Vì sao tính sin 90 độ phải viết Math.sin(90 * Math.PI / 180)?","options":["Vì Math.sin nhận góc theo đơn vị radian, phải đổi độ sang radian","Vì Math.sin chỉ nhận số nhỏ hơn 1","Để làm tròn kết quả","Vì Math.PI bằng 180"],"correct":[0],"explanation":"180 độ = PI radian, nên x độ = x * PI / 180 radian.","source":"bosung"},{"id":"bs-c9-13","chapter":9,"difficulty":2,"type":"single","question":"(Bài tập 58) Hiển thị ngày hiện hành theo định dạng d/m/yyyy. Lệnh nào đúng?","options":["d.getDay() + \"/\" + d.getMonth() + \"/\" + d.getFullYear()","d.getDate() + \"/\" + d.getMonth() + 1 + \"/\" + d.getYear()","d.getDate() + \"/\" + (d.getMonth() + 1) + \"/\" + d.getFullYear()","d.getDate() + \"/\" + d.getMonth() + \"/\" + d.getFullYear()"],"correct":[2],"explanation":"getDate là ngày trong tháng (getDay là thứ trong tuần); getMonth trả về 0-11 nên phải +1 và đặt trong ngoặc, nếu không sẽ thành nối chuỗi \"9\" + 1 = \"91\".","source":"bosung"},{"id":"bs-c9-14","chapter":9,"difficulty":3,"type":"single","question":"Ngày 21/10/2026 là thứ Tư. Lệnh new Date(2026, 9, 21).getDay() trả về:","options":["4","9","21","3"],"correct":[3],"explanation":"Tham số tháng tính từ 0 nên 9 là tháng 10. getDay trả về 0 (Chủ nhật) đến 6 (thứ Bảy); thứ Tư là 3.","source":"bosung"},{"id":"bs-c9-15","chapter":9,"difficulty":2,"type":"single","question":"(Bài tập 59) Tính số ngày còn lại đến Noel: diff = noel - today (kết quả là mili giây). Lệnh nào đổi sang số ngày?","options":["Math.ceil(diff / (1000 * 60 * 60 * 24))","diff.getDate()","Math.ceil(diff / 365)","Math.ceil(diff / (60 * 60 * 24))"],"correct":[0],"explanation":"Date lưu thời gian theo mili giây: 1 ngày = 1000 ms × 60 giây × 60 phút × 24 giờ.","source":"bosung"},{"id":"bs-c9-16","chapter":9,"difficulty":3,"type":"single","question":"Mảng a sau đoạn mã là gì?\n```\nvar a = [1, 2, 3];\na.unshift(0);\na.pop();\na.push(9);\na.shift();\n```","options":["[0, 1, 2, 9]","[1, 2, 9]","[1, 2, 3, 9]","[2, 3, 9]"],"correct":[1],"explanation":"unshift(0): [0,1,2,3]; pop(): [0,1,2]; push(9): [0,1,2,9]; shift(): [1,2,9].","source":"bosung"},{"id":"bs-c9-17","chapter":9,"difficulty":3,"type":"single","question":"Sau đoạn mã, weekday.length bằng bao nhiêu?\n```\nvar weekday = new Array(2);\nweekday[0] = \"Sunday\";\nweekday[1] = \"Monday\";\nweekday[3] = \"Wednesday\";\n```","options":["Lỗi vì vượt kích thước mảng","2","4","3"],"correct":[2],"explanation":"Mảng JavaScript tự mở rộng; gán vị trí 3 thì length = 4 (vị trí 2 là empty).","source":"bosung"},{"id":"bs-c9-18","chapter":9,"difficulty":1,"type":"single","question":"[\"ghe\", \"ban\", \"tu\"].indexOf(\"giuong\") trả về:","options":["0","undefined","-1","3"],"correct":[2],"explanation":"indexOf trả về -1 khi không tìm thấy; thường dùng để kiểm tra phần tử đã có trong mảng chưa.","source":"bosung"},{"id":"bs-c9-19","chapter":9,"difficulty":3,"type":"single","question":"Đoạn mã sau chạy thế nào?\n```\nvar person = {\n  firstName: \"John\",\n  lastName: \"Doe\",\n  fullName: function() {\n    return firstName + \" \" + lastName;\n  }\n};\ndocument.write(person.fullName());\n```","options":["In ra undefined undefined","Lỗi vì firstName, lastName chưa được khai báo; trong phương thức phải dùng this.firstName","In ra John Doe","In ra nội dung của hàm"],"correct":[1],"explanation":"Bên trong phương thức, thuộc tính của chính đối tượng phải truy cập qua this.","source":"bosung"},{"id":"bs-c9-20","chapter":9,"difficulty":2,"type":"single","question":"(Slide 55, câu 5) Đối tượng sinh viên có thuộc tính namSinh. Cách khai báo phương thức tuoi trả về tuổi nào đúng?","options":["tuoi: new Date().getFullYear() - this.namSinh()","tuoi = function() { return Date.getFullYear() - namSinh; }","function tuoi: { return new Date().getFullYear() - this.namSinh; }","tuoi: function() { return new Date().getFullYear() - this.namSinh; }"],"correct":[3],"explanation":"Trong đối tượng, phương thức khai báo dạng tên: function() {...}; năm hiện tại là new Date().getFullYear().","source":"bosung"},{"id":"bs-c9-21","chapter":9,"difficulty":2,"type":"single","question":"Với var car = { type: \"Fiat\", model: \"500\" }, biểu thức nào trả về undefined?","options":["car.Model","car.type","car.model","car[\"model\"]"],"correct":[0],"explanation":"Tên thuộc tính phân biệt hoa thường: car.Model không tồn tại.","source":"bosung"},{"id":"bs-c9-22","chapter":9,"difficulty":3,"type":"single","question":"(Bài tập 63) Kiểm tra email đơn giản: hợp lệ khi có @ không đứng đầu và có dấu chấm sau @. Với email = \"teo@uel\", biểu thức sau trả về gì?\n```\nemail.indexOf(\"@\") > 0 && email.lastIndexOf(\".\") > email.indexOf(\"@\")\n```","options":["-1","true","false","NaN"],"correct":[2],"explanation":"indexOf(\"@\") = 3 > 0 đúng; nhưng không có dấu chấm nên lastIndexOf(\".\") = -1, không lớn hơn 3.","source":"bosung"},{"id":"bs-c9-23","chapter":9,"difficulty":2,"type":"single","question":"Lệnh nào nối họ, tên lót, tên (ho, lot, ten) thành họ tên đầy đủ có dấu cách (slide 53, câu 3)?","options":["ho.concat(lot, ten)","ho + lot + ten","concat(ho, lot, ten)","ho.concat(\" \", lot, \" \", ten)"],"correct":[3],"explanation":"concat nhận nhiều đối số; phải thêm chuỗi \" \" để có khoảng trắng. Cách khác: ho + \" \" + lot + \" \" + ten.","source":"bosung"},{"id":"bs-c10-01","chapter":10,"difficulty":1,"type":"single","question":"(Slide 56) Với HTML <body><h1>DOM Lesson one</h1><p>Hello world!</p></body>, nút cha của nút văn bản \"Hello world!\" là:","options":["<body>","<html>","<h1>","<p>"],"correct":[3],"explanation":"Nút văn bản là con của thẻ chứa nó; h1 và p là 2 nút anh em (sibling).","source":"bosung"},{"id":"bs-c10-02","chapter":10,"difficulty":2,"type":"single","question":"(Slide 58) Kết quả của p.innerText = \"<font color='red'>Welcome</font>\"; là:","options":["Hiển thị chữ Welcome màu đen","Hiển thị chữ Welcome màu đỏ","Hiển thị nguyên văn chuỗi <font color='red'>Welcome</font>","Báo lỗi"],"correct":[2],"explanation":"innerText gán văn bản thuần, không phân tích thẻ HTML. Muốn ra chữ đỏ phải dùng innerHTML.","source":"bosung"},{"id":"bs-c10-03","chapter":10,"difficulty":3,"type":"single","question":"Sau 2 lệnh sau, thẻ p có định dạng gì?\n```\np.setAttribute(\"style\", \"color:red\");\np.setAttribute(\"style\", \"font-size:20px\");\n```","options":["Chữ đỏ, cỡ 20px","Chỉ màu đỏ","Chỉ cỡ chữ 20px, KHÔNG còn màu đỏ","Báo lỗi vì gán style 2 lần"],"correct":[2],"explanation":"setAttribute ghi đè TOÀN BỘ giá trị thuộc tính style. Muốn giữ cả hai: setAttribute(\"style\", \"color:red;font-size:20px\") hoặc p.style.fontSize = \"20px\".","source":"bosung"},{"id":"bs-c10-04","chapter":10,"difficulty":1,"type":"single","question":"(Slide 59) Thứ tự các bước thêm mới một HTML element là:","options":["appendChild -> createElement -> thiết lập thuộc tính -> getElementById","getElementById lấy holder -> createElement tạo thẻ -> thiết lập thuộc tính -> appendChild vào holder","thiết lập thuộc tính -> getElementById -> createElement -> appendChild","createElement -> appendChild -> getElementById -> thiết lập thuộc tính"],"correct":[1],"explanation":"Bước 1 lấy holder, bước 2 tạo thẻ, bước 3 gán thuộc tính, bước 4 đưa vào holder.","source":"bosung"},{"id":"bs-c10-05","chapter":10,"difficulty":3,"type":"single","question":"(Slide 59) Hàm loadProducts tạo 6 thẻ li từ mảng 6 sản phẩm và appendChild vào ol. Người dùng bấm nút Load Products 2 lần thì ol có bao nhiêu li?","options":["0","12","6","36"],"correct":[1],"explanation":"Mỗi lần bấm lại thêm nối đuôi 6 li mới, không xóa cái cũ. Muốn tránh trùng có thể gán olHolder.innerHTML = \"\" trước vòng lặp.","source":"bosung"},{"id":"bs-c10-06","chapter":10,"difficulty":2,"type":"single","question":"(Slide 60) Trong hàm addProduct, nếu QUÊN dòng tbody.appendChild(tr) thì điều gì xảy ra khi bấm Add Product?","options":["Dòng vẫn hiện bình thường","Trình duyệt báo lỗi ngay khi tải trang","Không có dòng nào hiện lên bảng vì tr chỉ được tạo trong bộ nhớ, chưa gắn vào cây DOM","Dòng hiện ra ở cuối trang, ngoài bảng"],"correct":[2],"explanation":"createElement chỉ tạo phần tử; phải appendChild vào một nút trên cây DOM thì mới hiển thị.","source":"bosung"},{"id":"bs-c10-07","chapter":10,"difficulty":2,"type":"single","question":"(Slide 60) Trong code frmProduct.productId.value, frmProduct và productId là gì?","options":["Cả hai đều là tên hàm JavaScript","frmProduct là name của thẻ form, productId là id của ô input bên trong form","frmProduct là id của bảng, productId là name của bảng","frmProduct là tên file, productId là tên cột"],"correct":[1],"explanation":"Có thể truy cập control qua tên form rồi đến id/name của control. Cách tổng quát hơn: document.getElementById(\"productId\").value.","source":"bosung"},{"id":"bs-c10-08","chapter":10,"difficulty":3,"type":"single","question":"(Slide 61) Nếu sửa dòng xóa thành tbody.removeChild(this.parentElement) (this là hình thùng rác) thì sao?","options":["Lỗi, vì this.parentElement là td, không phải con trực tiếp của tbody","Xóa toàn bộ tbody","Chỉ xóa hình thùng rác","Vẫn xóa được cả dòng"],"correct":[0],"explanation":"Cấu trúc tbody > tr > td > img. removeChild chỉ xóa được nút con trực tiếp, nên phải truyền tr = this.parentElement.parentElement.","source":"bosung"},{"id":"bs-c10-09","chapter":10,"difficulty":2,"type":"single","question":"(Bài tập 62) Rê chuột vào dòng tr thì tô nền vàng. Code nào đúng?","options":["tr.onmouseover = function() { this.backgroundColor = \"yellow\"; }","tr.mouseover = function() { this.style = yellow; }","tr.onmouseover = function() { this.style.backgroundColor = \"yellow\"; }","tr.onmouseover = function() { this.style.background-color = \"yellow\"; }"],"correct":[2],"explanation":"Trong JavaScript, thuộc tính CSS có gạch nối được viết dạng camelCase: backgroundColor. Sự kiện là onmouseover (rời chuột: onmouseout/onmouseleave).","source":"bosung"},{"id":"bs-c10-10","chapter":10,"difficulty":3,"type":"single","question":"(Bài tập 64) Muốn xóa TẤT CẢ các dòng đang tô nền đỏ trong tbody, vì sao nên duyệt từ dòng CUỐI về dòng ĐẦU?\n```\nfor (var i = tbody.rows.length - 1; i >= 0; i--) {\n  if (tbody.rows[i].style.backgroundColor == \"red\")\n    tbody.removeChild(tbody.rows[i]);\n}\n```","options":["Vì duyệt ngược chạy nhanh gấp đôi","Vì khi xóa một dòng, các dòng phía sau dồn lên đổi chỉ số; duyệt xuôi sẽ bỏ sót dòng liền sau dòng vừa xóa","Không có lý do, duyệt xuôi cũng cho kết quả giống hệt","Vì removeChild chỉ xóa được dòng cuối"],"correct":[1],"explanation":"rows là danh sách động; duyệt ngược thì việc xóa không ảnh hưởng tới các chỉ số chưa duyệt.","source":"bosung"},{"id":"bs-c10-11","chapter":10,"difficulty":2,"type":"single","question":"(Bài tập 65) Lệnh ul.insertBefore(newLi, ul.children[1]) chèn newLi vào đâu?","options":["Vào cuối danh sách","Vào vị trí thứ 2, ngay trước phần tử con thứ hai hiện tại","Thay thế phần tử con thứ hai","Vào đầu danh sách"],"correct":[1],"explanation":"insertBefore(nút mới, nút tham chiếu): chèn trước nút tham chiếu. children[1] là phần tử thứ hai (chỉ số từ 0).","source":"bosung"},{"id":"bs-c10-12","chapter":10,"difficulty":2,"type":"single","question":"(Bài tập 65) Lệnh nào thay nội dung li cũ (oldLi) bằng li mới (newLi) trong ul?","options":["ul.replaceChild(oldLi, newLi)","ul.removeChild(newLi, oldLi)","oldLi.replaceChild(newLi)","ul.replaceChild(newLi, oldLi)"],"correct":[3],"explanation":"Slide 57: replaceChild(new, old) — tham số đầu là nút MỚI, tham số sau là nút CŨ.","source":"bosung"},{"id":"bs-c10-13","chapter":10,"difficulty":3,"type":"single","question":"Lệnh document.getElementsByTagName(\"p\").innerHTML = \"Hết hàng\"; có tác dụng gì?","options":["Không đổi được thẻ p nào, vì kết quả là một danh sách các phần tử; phải dùng chỉ số [i] hoặc vòng lặp","Đổi nội dung tất cả thẻ p thành Hết hàng","Đổi nội dung thẻ p đầu tiên","Xóa toàn bộ thẻ p"],"correct":[0],"explanation":"getElementsByTagName/getElementsByClassName trả về danh sách (có s trong Elements). getElementById mới trả về 1 phần tử.","source":"bosung"},{"id":"bs-c10-14","chapter":10,"difficulty":2,"type":"single","question":"Cho <ul id=\"menu\"><li>Home</li><li>Sofa</li></ul>. document.querySelector(\"#menu li\").innerText trả về:","options":["\"HomeSofa\"","\"Sofa\"","\"Home\"","Danh sách 2 phần tử li"],"correct":[2],"explanation":"querySelector trả về phần tử ĐẦU TIÊN khớp CSS selector; querySelectorAll mới trả về tất cả.","source":"bosung"},{"id":"bs-c10-15","chapter":10,"difficulty":2,"type":"single","question":"(Slide 64) XML bookstore có 3 book theo thứ tự: Everyday Italian, HTML and Javascript, AngulaJS. Lệnh sau trả về gì?\n```\nxmlDoc.getElementsByTagName(\"title\")[1].childNodes[0].nodeValue\n```","options":["Đối tượng thẻ title","\"AngulaJS\"","\"HTML and Javascript\"","\"Everyday Italian\""],"correct":[2],"explanation":"Chỉ số bắt đầu từ 0 nên [1] là title thứ hai; childNodes[0] là nút văn bản, nodeValue là nội dung chữ.","source":"bosung"},{"id":"bs-c10-16","chapter":10,"difficulty":2,"type":"single","question":"(Slide 63) Để chuyển chuỗi txt chứa XML thành đối tượng XML Document, đoạn code nào đúng?","options":["var xmlDoc = JSON.parse(txt);","var parser = new DOMParser(); var xmlDoc = parser.parseFromString(txt, \"text/xml\");","var parser = new DOMParser(); var xmlDoc = parser.parse(txt, \"xml\");","var xmlDoc = new DOMParser(txt, \"text/xml\");"],"correct":[1],"explanation":"Tạo đối tượng DOMParser rồi gọi parseFromString(chuỗi, \"text/xml\"). JSON.parse dùng cho JSON.","source":"bosung"},{"id":"bs-c10-17","chapter":10,"difficulty":2,"type":"single","question":"Với XML <book category=\"COOKING\">...</book>, lệnh nào lấy giá trị COOKING (book là phần tử đã truy xuất)?","options":["book.setAttribute(\"category\")","book.getAttribute(\"category\")","book.getElementsByTagName(\"category\")[0].nodeValue","book.category.childNodes[0]"],"correct":[1],"explanation":"category là XML Attribute (thuộc tính), không phải Element con. getAttribute đọc, setAttribute ghi.","source":"bosung"},{"id":"bs-c10-18","chapter":10,"difficulty":2,"type":"single","question":"Đoạn XML nào HỢP LỆ (well-formed)?","options":["<sanpham><ten>Ghế</ten><gia>500</gia></sanpham>","<ten>Ghế</ten><ten>Bàn</ten>","<sanpham><Ten>Ghế</ten></sanpham>","<sanpham ma=SP01><ten>Ghế</ten></sanpham>"],"correct":[0],"explanation":"XML phân biệt hoa thường (Ten khác ten), phải có đúng 1 thẻ root, giá trị thuộc tính phải đặt trong dấu nháy.","source":"bosung"},{"id":"bs-c10-19","chapter":10,"difficulty":2,"type":"single","question":"Trong XML muốn lưu tên cửa hàng \"Ben & Jerry\" trong thẻ <ten>, ta viết:","options":["<ten>Ben &amp; Jerry</ten>","<ten>Ben &and; Jerry</ten>","<ten>Ben & Jerry</ten>","<ten>\"Ben & Jerry\"</ten>"],"correct":[0],"explanation":"Ký tự & phải viết thành &amp; (tương tự &lt; &gt; &apos; &quot;).","source":"bosung"},{"id":"bs-c10-20","chapter":10,"difficulty":3,"type":"single","question":"(Slide 66) Trong hàm callAjax, xhr.send() được gọi TRƯỚC khi gán xhr.onreadystatechange. Vì sao code vẫn chạy đúng?","options":["Vì send() tự động chờ onreadystatechange được gán","Vì open dùng tham số async = true: phản hồi đến bất đồng bộ, sau khi hàm đã gán xong onreadystatechange","Code chạy sai, không bao giờ hiển thị dữ liệu","Vì readyState luôn bằng 4 ngay sau send()"],"correct":[1],"explanation":"AJAX = Asynchronous: send() không chặn chương trình, kết quả về sau. Tuy vậy nên gán onreadystatechange trước send() cho rõ ràng.","source":"bosung"},{"id":"bs-c10-21","chapter":10,"difficulty":3,"type":"single","question":"Mở file DanhSachSV.html bằng cách nhấp đúp (địa chỉ bắt đầu bằng file:///) thì đoạn AJAX đọc SV.xml không hiển thị dữ liệu. Cách khắc phục phù hợp nhất là:","options":["Xóa dòng xhr.send()","Chạy trang qua web server như Live Server (địa chỉ http://127.0.0.1:5500/...)","Đổi đuôi SV.xml thành SV.html","Đổi xhr.open(\"GET\", ...) thành xhr.open(\"POST\", ...)"],"correct":[1],"explanation":"Trình duyệt chặn XMLHttpRequest đọc file cục bộ qua giao thức file:// vì lý do bảo mật. Chạy qua http (Live Server, IIS, GitHub Pages) thì AJAX hoạt động.","source":"bosung"},{"id":"bs-c10-22","chapter":10,"difficulty":2,"type":"single","question":"Trong AJAX, readyState = 3 có nghĩa là gì?","options":["Request chưa được khởi tạo","Request đã xong và phản hồi sẵn sàng","Đã thiết lập kết nối server","Đang xử lý request (processing request)"],"correct":[3],"explanation":"0: chưa khởi tạo; 1: đã kết nối server; 2: server đã nhận request; 3: đang xử lý; 4: xong, phản hồi sẵn sàng.","source":"bosung"},{"id":"bs-c10-23","chapter":10,"difficulty":2,"type":"single","question":"(Bài tập 69) Gom các title của Employee thành danh sách KHÔNG trùng để nạp vào droplist. Đoạn code nào đúng?","options":["titles.push(t); titles.pop();","if (titles.indexOf(t) == -1) titles.push(t);","if (titles.indexOf(t) != -1) titles.push(t);","if (titles[t] == -1) titles.push(t);"],"correct":[1],"explanation":"Chỉ thêm khi chưa có trong mảng (indexOf trả về -1).","source":"bosung"},{"id":"bs-c10-24","chapter":10,"difficulty":2,"type":"single","question":"(Bài tập 63) Nạp các ngày 1 đến 31 vào combobox cboNgay bằng vòng lặp. Code nào đúng?","options":["\n```\nfor (var i = 1; i <= 31; i++) {\n  var opt = document.createElement(\"option\");\n  opt.value = i;\n  opt.innerText = i;\n  cboNgay.appendChild(opt);\n}\n```","\n```\nfor (var i = 1; i < 31; i++) {\n  var opt = document.createElement(\"option\");\n  opt.value = i;\n  opt.innerText = i;\n  cboNgay.appendChild(opt);\n}\n```","\n```\nvar opt = document.createElement(\"option\");\nfor (var i = 1; i <= 31; i++) {\n  opt.innerText = i;\n}\ncboNgay.appendChild(opt);\n```","\n```\nfor (var i = 1; i <= 31; i++) {\n  var opt = document.createElement(\"select\");\n  opt.value = i;\n  cboNgay.appendChild(opt);\n}\n```"],"correct":[0],"explanation":"Mỗi vòng tạo MỘT option mới rồi append. Điều kiện i < 31 thiếu ngày 31. Tạo 1 option ngoài vòng lặp thì chỉ có 1 mục (ngày 31).","source":"bosung"},{"id":"bs-c10-25","chapter":10,"difficulty":3,"type":"single","question":"(Bài tập 64) Click chuột vào dòng thì tô đỏ, click lần nữa thì bỏ tô. Code nào đúng?","options":["tr.onclick = function() { this.style.backgroundColor = \"red\"; }","tr.onclick = function() { this.style.backgroundColor = (this.style.backgroundColor == \"red\") ? \"\" : \"red\"; }","tr.onclick = function() { if (this.style.backgroundColor = \"red\") this.style.backgroundColor = \"\"; }","tr.ondblclick = function() { this.style.backgroundColor = \"red\"; }"],"correct":[1],"explanation":"Cần kiểm tra trạng thái hiện tại để đảo (toggle). Phương án dùng dấu = là phép gán (luôn đúng), không phải so sánh ==.","source":"bosung"},{"id":"bs-c11-01","chapter":11,"difficulty":2,"type":"single","question":"Chuỗi nào là JSON HỢP LỆ để truyền vào JSON.parse()?","options":["{\"ma\": \"sp1\", \"gia\": 15000}","{\"ma\": \"sp1\", \"gia\": 15000,}","{'ma': 'sp1', 'gia': 15000}","{ma: \"sp1\", gia: 15000}"],"correct":[0],"explanation":"JSON chuẩn: tên thuộc tính đặt trong nháy KÉP, chuỗi dùng nháy kép, không có dấu phẩy thừa ở cuối.","source":"bosung"},{"id":"bs-c11-02","chapter":11,"difficulty":3,"type":"single","question":"(Bài tập 73) Khai báo var sanphams = [{ ma: \"sp1\", ten: \"Cocacola\", gia: 15000 }, ...] trong thẻ script (tên thuộc tính không có nháy). Phát biểu nào đúng?","options":["Chỉ chạy được nếu đổi thành JSON.parse(sanphams)","Chạy được nhưng không truy cập được sanphams[0].ten","Báo lỗi cú pháp vì JSON bắt buộc có nháy","Chạy được, vì đây là object literal của JavaScript; nhưng nếu là chuỗi JSON đưa vào JSON.parse thì tên thuộc tính bắt buộc có nháy kép"],"correct":[3],"explanation":"Viết trực tiếp trong JavaScript thì key có thể không cần nháy. Quy tắc nháy kép áp dụng cho văn bản JSON (file .json, dữ liệu từ server).","source":"bosung"},{"id":"bs-c11-03","chapter":11,"difficulty":1,"type":"single","question":"(Slide 67) Với dmMayTinh (Sanphams gồm DELL Inspiron 14NR và HP Inspiron 113), lệnh dmMayTinh.Sanphams[1].TenSP trả về:","options":["\"DELL Inspiron 14NR\"","\"HP Inspiron 113\"","\"sp_2yyyy\"","undefined"],"correct":[1],"explanation":"Sanphams là mảng, [1] là phần tử thứ hai.","source":"bosung"},{"id":"bs-c11-04","chapter":11,"difficulty":2,"type":"single","question":"(Slide 67) Đoạn code sau tính được bao nhiêu với 2 sản phẩm SoLuong 100 và 130?\n```\nvar tong = 0;\nfor (var i = 0; i < dmMayTinh.Sanphams.length; i++) {\n  tong += dmMayTinh.Sanphams[i].SoLuong;\n}\n```","options":["130","230","2","100130"],"correct":[1],"explanation":"SoLuong là số (không có nháy) nên += là phép cộng số.","source":"bosung"},{"id":"bs-c11-05","chapter":11,"difficulty":3,"type":"single","question":"(Slide 67) Tổng giá trị kho = tổng (SoLuong × DonGia). Với DELL (100, 150000) và HP (130, 140000), kết quả là:","options":["290.000","29.000.000","33.000.000","33.200.000"],"correct":[3],"explanation":"100 × 150.000 = 15.000.000; 130 × 140.000 = 18.200.000; cộng lại 33.200.000.","source":"bosung"},{"id":"bs-c11-06","chapter":11,"difficulty":3,"type":"single","question":"(Bài tập 75) Mảng Sachs có số trang: 100, 200, 90, 70, 1000, 500, 600, 400, 300, 700. Đoạn code sau cho dem bằng bao nhiêu?\n```\nvar dem = 0;\nfor (var i = 0; i < sinhvien.Sachs.length; i++) {\n  if (sinhvien.Sachs[i].Trang >= 500) dem++;\n}\n```","options":["3","5","4","6"],"correct":[2],"explanation":"Các sách >= 500 trang: 1000, 500, 600, 700.","source":"bosung"},{"id":"bs-c11-07","chapter":11,"difficulty":2,"type":"single","question":"(Bài tập 75) sinhvien.Sachs có 10 cuốn, cuốn cuối là Bảo Đao. Lệnh nào lấy tên cuốn sách CUỐI CÙNG?","options":["sinhvien.Sachs[10].Ten","sinhvien.Sachs[sinhvien.Sachs.length].Ten","sinhvien.Sachs.last.Ten","sinhvien.Sachs[sinhvien.Sachs.length - 1].Ten"],"correct":[3],"explanation":"Chỉ số mảng từ 0 đến length - 1. Sachs[10] là undefined nên .Ten sẽ báo lỗi.","source":"bosung"},{"id":"bs-c11-08","chapter":11,"difficulty":2,"type":"single","question":"(Slide 67) Hàm xuLyHienThi ghép chuỗi table chứa các thẻ <table><tr><td>... rồi gán div.innerHTML = table. Nếu đổi thành div.innerText = table thì sao?","options":["Bảng hiển thị nhưng mất viền","Báo lỗi JavaScript","Trang hiển thị nguyên văn các thẻ <table>, <tr>, <td> dưới dạng chữ, không thành bảng","Bảng vẫn hiển thị bình thường"],"correct":[2],"explanation":"innerText không phân tích HTML.","source":"bosung"},{"id":"bs-c11-09","chapter":11,"difficulty":2,"type":"single","question":"JSON.stringify({ ma: \"sp1\", gia: 15000 }) trả về:","options":["'{ma:sp1,gia:15000}'","'[\"sp1\",15000]'","Một đối tượng có 2 thuộc tính","'{\"ma\":\"sp1\",\"gia\":15000}' (một chuỗi)"],"correct":[3],"explanation":"stringify chuyển đối tượng thành chuỗi JSON (tên thuộc tính có nháy kép); parse làm ngược lại.","source":"bosung"},{"id":"bs-c11-10","chapter":11,"difficulty":2,"type":"single","question":"(Bài tập 74) Dùng AJAX đọc file databaseSinhVien.json. Sau khi readyState == 4 và status == 200, lệnh nào lấy được dữ liệu dạng đối tượng?","options":["var data = JSON.parse(xhr.responseText);","var data = xhr.responseXML;","var data = JSON.stringify(xhr.responseText);","var data = xhr.responseText.json;"],"correct":[0],"explanation":"Server trả JSON dưới dạng văn bản, dùng responseText rồi JSON.parse. responseXML chỉ dùng cho XML.","source":"bosung"},{"id":"bs-c11-11","chapter":11,"difficulty":3,"type":"single","question":"Đối tượng var u = { \"first-name\": \"Thanh\" }. Lệnh nào lấy đúng giá trị Thanh?","options":["u.[first-name]","u.firstname","u.first-name","u[\"first-name\"]"],"correct":[3],"explanation":"Tên có dấu gạch ngang không dùng được cú pháp dấu chấm (sẽ bị hiểu là u.first trừ name); phải dùng ngoặc vuông.","source":"bosung"},{"id":"bs-c11-12","chapter":11,"difficulty":2,"type":"single","question":"(Bài tập 71) Hiển thị TẤT CẢ thuộc tính của đối tượng user (id, first_name, gender...) lên table mà không cần ghi tên từng thuộc tính. Vòng lặp nào phù hợp?","options":["for (var i = 0; i < user.length; i++) { html += user[i]; }","for (var key in user) { html += user.key; }","while (user.next()) { html += user.value; }","for (var key in user) { html += \"<tr><td>\" + key + \"</td><td>\" + user[key] + \"</td></tr>\"; }"],"correct":[3],"explanation":"for...in duyệt qua tên các thuộc tính của đối tượng; dùng user[key] để lấy giá trị. Đối tượng không có length; user.key tìm thuộc tính tên là \"key\".","source":"bosung"},{"id":"bs-c11-13","chapter":11,"difficulty":2,"type":"single","question":"Với var m = [[1, 2], [3, 4]], m[1][0] bằng bao nhiêu?","options":["3","4","2","1"],"correct":[0],"explanation":"Phần tử của JSON Array có thể là một mảng khác: m[1] = [3, 4], lấy phần tử đầu là 3.","source":"bosung"},{"id":"bs-c11-14","chapter":11,"difficulty":2,"type":"single","question":"(Bài tập 70) Phát biểu nào ĐÚNG khi so sánh JSON với XML?","options":["XML không dùng để trao đổi dữ liệu","JSON gọn hơn (không cần thẻ đóng), hỗ trợ trực tiếp kiểu mảng và đọc nhanh bằng JSON.parse","XML gọn hơn JSON vì có thẻ đóng mở","JSON chỉ dùng được với JavaScript"],"correct":[1],"explanation":"Cả hai đều lưu trữ và trao đổi dữ liệu, độc lập ngôn ngữ; JSON ngắn gọn hơn và dùng phổ biến cho API.","source":"bosung"}];
